window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0214", [{"word":"fabricate","ipa_uk":"/ˈfæbrɪkeɪt/","ipa_us":"/ˈfæbrɪkeɪt/","definition_zh":"制造；加工制作；组装；编造；捏造；伪造","definition_en":"to make something by putting parts or materials together, or to invent something false in order to deceive","core_image":"车间里钢板边被切齐，焊枪把两块料拼成一只支架，火花落在地上","scene":"工厂接到一张图纸，工人先下料再拼焊，第二天就交出一只临时支架。The shop can fabricate a replacement bracket overnight.","sceneCN":"这里指按图纸把材料加工成实物（第 1 个义项：用材料制作实物）；句意为这家车间一夜之间就能做出一个替换支架。图中可辨识物件：钢板、切割机、焊枪、支架。","pos":[{"tag":"v.","zh":"制造；制作；编造；捏造；伪造"}],"collocations":[{"phrase":"fabricate parts","zh":"加工零件"},{"phrase":"fabricate a story","zh":"编造故事"},{"phrase":"fabricate evidence","zh":"捏造证据"},{"phrase":"fabricate from steel","zh":"用钢材制造"},{"phrase":"fabricate a claim","zh":"编造说法"},{"phrase":"fabricated data","zh":"捏造的数据"}],"forms":[{"label":"动词原形","form":"fabricate"},{"label":"第三人称单数","form":"fabricates"},{"label":"过去式","form":"fabricated"},{"label":"过去分词","form":"fabricated"},{"label":"现在分词","form":"fabricating"},{"label":"名词","form":"fabrication"}],"derivatives":[{"word":"fabrication","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「制造；捏造」"},{"word":"fabricator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「制造者；捏造者」"},{"word":"fabricated","pos":"adj.","zh":"由该动词加已然词尾构成，义为「加工好的；编造的」"},{"word":"prefabricate","pos":"v.","zh":"由表示「预先」的前缀加该动词构成，义为「预制；预先加工」"},{"word":"prefabrication","pos":"n.","zh":"由预制动词加表示动作结果的名词尾构成，义为「预制加工」"}],"senses":[{"no":"01","title":"To make a thing from materials","titleCN":"用材料造出实物","definition":"to make a product by cutting, shaping or joining raw materials and parts","definitionCN":"通过切割、成形或接合原料与零件来做出产品","example":"The workshop can fabricate a steel frame in two days.","exampleCN":"这家车间两天就能造出一副钢架。","why":"The Latin word for a smith's shop supplied the idea of skilled making, and the verb still starts from material and hands.","whyCN":"拉丁语里表示铁匠铺的词给出了「手艺制作」的意思，这个动词至今仍从材料与双手出发。"},{"no":"02","title":"To fit parts into a whole","titleCN":"把零件装成整体","definition":"to assemble separate components into one finished structure","definitionCN":"把分开的部件装配成一个成品结构","example":"They fabricate the frame from four welded sections.","exampleCN":"他们用四段焊接件把这个框架拼成整体。","why":"Once the material is cut, the next step is joining, so the same verb covers assembly as well as shaping.","whyCN":"材料切好之后下一步就是接合，因此同一个动词既指成形，也指装配。"},{"no":"03","title":"To invent a story","titleCN":"编造故事或说法","definition":"to invent an account or excuse that has no basis in fact","definitionCN":"编造一个没有事实依据的说法或借口","example":"He fabricated a reason for missing the inspection.","exampleCN":"他为错过检查编造了一个理由。","why":"Making and making up share the picture of building something out of pieces, and a lie is assembled the same way.","whyCN":"「制造」与「编造」共享「用零件搭起来」的画面，谎言也是这样拼出来的。"},{"no":"04","title":"To forge a document","titleCN":"伪造文书或签名","definition":"to produce a false document, signature or record that appears genuine","definitionCN":"制作一份看起来真实、实为虚假的文件、签名或记录","example":"The clerk fabricated the safety certificate.","exampleCN":"那名职员伪造了安全证书。","why":"A document is a made object, so faking one is described with the verb for making.","whyCN":"文件也是被做出来的东西，因此伪造文件沿用了「制作」这个动词。"},{"no":"05","title":"To plant false evidence","titleCN":"捏造证据","definition":"to create or alter evidence so that an investigation reaches a false conclusion","definitionCN":"制造或改动证据，使调查得出错误结论","example":"The report says the inspector fabricated the test results.","exampleCN":"报告称检查员捏造了检测结果。","why":"Evidence is treated as a manufactured article, and the metaphor turns a lab record into a fabricated product.","whyCN":"证据被当作一件制造出来的物品，这个比喻把实验记录变成了加工产品。"},{"no":"06","title":"To frame someone","titleCN":"编造罪名诬陷他人","definition":"to invent a charge or accusation against an innocent person","definitionCN":"为无辜者编造罪名或指控","example":"They fabricated a complaint to remove him from the site.","exampleCN":"他们编造了一纸投诉，把他赶出工地。","why":"The charge is built piece by piece like a machine, and the person is trapped inside it.","whyCN":"罪名像机器一样被一件件拼起来，而人被关在这台机器里。"},{"no":"07","title":"To invent a theory","titleCN":"凭空臆造理论","definition":"to put forward a concept or explanation without evidence, as if it were established","definitionCN":"在没有证据的情况下提出一个概念或解释，仿佛它已经成立","example":"The paper fabricated a mechanism that no experiment supports.","exampleCN":"那篇论文臆造了一个没有任何实验支持的机制。","why":"Academic writing inherited the word through its Latin sense of constructing, and construction without material is invention.","whyCN":"学术写作经拉丁语「建造」义继承了这个词，而没有材料的建造就是臆造。"},{"no":"08","title":"To pre-make a component","titleCN":"预先加工构件","definition":"to produce a standard part in a shop before it is moved to the building site","definitionCN":"在工厂预先生产标准构件，再运到施工现场","example":"The supplier will fabricate the beams off site.","exampleCN":"供应商会在场外预先把这些梁加工好。","why":"Modern construction splits making from placing, and the verb stays with the making half.","whyCN":"现代建造把「制作」与「就位」分开，这个动词留在「制作」那一半。"},{"no":"09","title":"To generate a synthetic record","titleCN":"合成伪造的影像或记录","definition":"to create an image, recording or dataset by technical means and present it as real","definitionCN":"用技术手段生成图像、录音或数据集，并当作真实内容呈现","example":"The software can fabricate a convincing voice sample.","exampleCN":"这款软件能合成一段以假乱真的语音样本。","why":"The newest extension keeps the oldest structure: pieces are arranged until the result looks like something that occurred.","whyCN":"最新的这一层保留着最古老的结构：把碎片排列到看起来像真发生过一样。"}],"etymology":{"intro":{"en":"Fabricate comes from Latin fabricare, to make or fashion, from fabrica, a workshop or craft, and faber, a smith or artisan. English first used it for skilled making, then for making up lies.","cn":"这个词来自拉丁语 fabricare「制作、打造」，其名词 fabrica 指作坊或手艺，faber 指铁匠或工匠。英语先用它表示有手艺的制作，后来才引申为编造谎言。"},"items":[{"era":"LATIN FABER","en":"Faber meant a smith or skilled worker, especially one who worked hard materials such as stone, metal or wood.","cn":"这个词指铁匠或有手艺的工匠，尤指加工石、金属、木材等硬质材料的人。"},{"era":"LATIN FABRICA","en":"Fabrica named the workshop and the craft carried on there, so the place and the skill were one word.","cn":"这个词既指作坊，也指在作坊里进行的手艺，地点与技艺合为一体。"},{"era":"LATIN FABRICARE","en":"The verb meant to shape, build or construct, and it covered both ordinary products and elaborate structures.","cn":"这个动词意为塑造、建造、构造，既用于日常产品，也用于复杂的建筑。"},{"era":"ENGLISH, 15TH CENTURY","en":"English took the verb through French and used it first for the making of physical things by skilled labour.","cn":"英语经法语引入这个动词，最初用于表示以熟练劳动制作实物。"},{"era":"THE FALSE TURN","en":"By the eighteenth century the verb also meant to invent a falsehood; the first attestation date of that shift is uncertain and is usually given only as the eighteenth century.","cn":"到十八世纪，这个动词也指编造虚假内容；这一转变的首见年代不确定，通常只给十八世纪这一约数。"},{"era":"INDUSTRIAL AND DIGITAL","en":"Metal fabrication made the word a trade term, and digital tools later extended it to synthetic images and records.","cn":"金属加工使这个词成为行业术语，数字工具后来又把它扩展到合成影像与记录。"}]},"similar":{"note":{"en":"The first group looks or sounds like fabricate; the second group names neighbouring ideas of making and faking.","cn":"第一组在形音上与「fabricate」相近；第二组是与「制作、造假」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fabrication","ipa":"/ˌfæbrɪˈkeɪʃn/","tag":"same root","definition":"The noun for the act of making or the thing made, and also for a lie.","definitionCN":"指制造行为、制成品，也指编造出来的谎言。"},{"word":"fabricator","ipa":"/ˈfæbrɪkeɪtə/","tag":"same root","definition":"A person or firm that makes parts, or one who invents false accounts.","definitionCN":"指加工零件的个人或企业，也指编造说法的人。"},{"word":"prefabricate","ipa":"/ˌpriːˈfæbrɪkeɪt/","tag":"same root","definition":"To make a standard part in a factory before it is taken to the site.","definitionCN":"指在工厂预先制作标准构件，再运到现场。"},{"word":"fabric","ipa":"/ˈfæbrɪk/","tag":"same root","definition":"Woven cloth, and by extension the frame of a building; the same workshop word turned into material.","definitionCN":"指织物，也引申指建筑的结构骨架；是同一个作坊词转成的材料名。"},{"word":"fabulous","ipa":"/ˈfæbjələs/","tag":"different root","definition":"Resembling a fable; it looks close but belongs to the word for story, not to the smith's shop.","definitionCN":"指像寓言一样的；形近但属于「故事」那一系，与铁匠铺无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manufacture","ipa":"/ˌmænjuˈfæktʃə/","tag":"near meaning","definition":"To make goods on a large scale, usually in a factory and by machinery.","definitionCN":"指大规模制造商品，通常指工厂机械化生产。"},{"word":"assemble","ipa":"/əˈsembl/","tag":"near meaning","definition":"To put components together into a finished unit.","definitionCN":"指把部件装成一个成品。"},{"word":"forge","ipa":"/fɔːdʒ/","tag":"near meaning","definition":"To shape metal by heat and hammer, or to make a false document.","definitionCN":"指加热锤打成形金属，也指伪造文书。"},{"word":"falsify","ipa":"/ˈfɔːlsɪfaɪ/","tag":"near meaning","definition":"To alter a record or account so that it misrepresents the facts.","definitionCN":"指改动记录或说法，使其歪曲事实。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the smith's shop behind the word, its real family and its real trade phrases.","cn":"正常联想使用这个词背后的铁匠铺、真实同族词与真实行业搭配。"},"normal":[{"en":"The Latin faber was a smith, and fabricate began as the work done at that forge.","cn":"拉丁语 faber 是铁匠，fabricate 最初就是铁匠铺里做的活。"},{"en":"Fabric, fabrication, fabricator and prefabricate all come from the same workshop word.","cn":"织物、制造、制造者与预制都出自同一个作坊词。"},{"en":"Metal fabrication is a real trade, covering cutting, forming and welding.","cn":"金属加工是一门真实行业，涵盖切割、成形与焊接。"},{"en":"Fabricate evidence and fabricate a story are the two fixed phrases of the false sense.","cn":"捏造证据与编造故事是虚假义的两个固定说法。"},{"en":"Prefabricated beams arrive on site already made, which is the word doing its literal work.","cn":"预制梁到场时已经做好，正是这个词在字面意义上的用法。"}],"abstract":[{"en":"Fabrication is construction with no material behind it: a frame of air that looks solid.","cn":"编造是没有材料支撑的建造：一副看起来坚固的空气骨架。"},{"en":"The same hand that shapes steel can shape a lie, and the word refuses to tell them apart.","cn":"塑钢的手也能塑造谎言，而这个词拒绝把两者分开。"},{"en":"Every false record is a product with a workshop, a process and a quality check.","cn":"每一份假记录都是有作坊、有流程、有质检的产品。"}]},"examples":[{"en":"The team will fabricate the guardrail from galvanised steel.","cn":"这个班组会用镀锌钢加工护栏。"},{"en":"He tried to fabricate an alibi for the night of the accident.","cn":"他试图为事故当晚编造不在场证明。"},{"en":"Inspectors found that the lab had fabricated three test reports.","cn":"检查人员发现该实验室捏造了三份检测报告。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「法布瑞克特」——作坊里把料拼成件，件是真的叫制造，话是假的叫编造：制造、捏造","word":"fabricate"},"root":"拉丁语 fabricare「制作、打造」← fabrica「作坊、手艺」← faber「铁匠、工匠」；更早的词源属重构形式。英语十五世纪经法语引入，先指实物制作，十八世纪起兼指编造，确切年代来源不确定。","sensesIntro":{"en":"Nine senses move from the smith's bench outward: making a product, joining parts, inventing a story, forging a document, planting evidence, framing a person, inventing a theory, pre-making a component, and generating a synthetic record.","cn":"九个义项从铁匠台向外移动：制作产品、拼装部件、编造故事、伪造文书、捏造证据、诬陷他人、臆造理论、预先加工构件、合成伪造记录。"},"semanticMap":{"core":{"en":"CORE IMAGE: a smith joins cut pieces until a solid bracket stands on the bench.","cn":"核心意象：铁匠把切好的料拼在一起，直到一只结实的支架立在台上。"},"chain":["SMITH'S SHOP","CUT MATERIAL","JOINED PART","FINISHED PRODUCT","PRE-MADE UNIT","SYNTHETIC RECORD"],"branches":[{"senses":"01","en":"THE LITERAL MAKING: raw material becomes a finished article under skilled hands.","cn":"字面制作：原料在熟练的手下变成成品。"},{"senses":"02 · 08","en":"THE JOINED AND PRE-MADE PART: components fitted into a whole, or built in advance off site.","cn":"拼合与预制：部件被装成整体，或在场外提前做好。"},{"senses":"03 · 06","en":"THE INVENTED ACCOUNT: a story built for a reason, and a charge built around a person.","cn":"编造的说法：为某个理由搭起的故事，以及围着一个人搭起的罪名。"},{"senses":"04 · 05","en":"THE FALSE PAPER: a certificate or a test record made to look genuine.","cn":"假文件：做得像真的一样的一份证书或检测记录。"},{"senses":"07 · 09","en":"THE CONSTRUCT WITHOUT MATERIAL: a theory with no evidence and a voice sample with no speaker.","cn":"没有材料的构造：无证据的理论，以及无说话人的语音样本。"}]},"affixes":{"intro":{"en":"Fabricate is a Latin verb whose stem sits inside a whole family of English making words.","cn":"这是一个拉丁动词，其词干嵌在一整族英语「制作」词里。"},"latinIntro":{"en":"Latin supplies faber, fabrica and fabricare; the deeper root behind them is reconstructed rather than recorded, so it is listed as a reconstruction.","cn":"拉丁语提供了铁匠、作坊与制作三个词；它们更早的词根属重构而非有记录的形式，因此按重构形式列出。"},"items":[{"word":"faber","structure":"Latin noun","meaning":"smith; skilled worker","meaningCN":"铁匠；熟练工匠","example":"The smith gave the family its name.","exampleCN":"铁匠给了这一族词名字。"},{"word":"fabrica","structure":"Latin noun from faber","meaning":"workshop; craft","meaningCN":"作坊；手艺","example":"The place and the skill were named together.","exampleCN":"地点与技艺被同一个词命名。"},{"word":"fabricare","structure":"Latin verb from fabrica","meaning":"to make, shape, construct","meaningCN":"制作；塑造；建造","example":"The verb names the work of the shop.","exampleCN":"这个动词指作坊里的活。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or cause","meaningCN":"使……；做……","example":"The ending marks the English verb of action.","exampleCN":"这个词尾标明英语的动作动词。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result of making","meaningCN":"制作的动作或结果","example":"It forms the noun for the process and the lie.","exampleCN":"它构成表示工序与谎言的名词。"},{"word":"-or","structure":"agent noun ending","meaning":"the one who makes","meaningCN":"进行制作的人","example":"The ending names the worker or the firm.","exampleCN":"这个词尾指工人或企业。"},{"word":"pre-","structure":"Latin prefix","meaning":"before, in advance","meaningCN":"预先；在前","example":"It marks the part made before delivery.","exampleCN":"它标出交付前就做好的构件。"},{"word":"fabric","structure":"Latin fabrica through French","meaning":"woven material; structure","meaningCN":"织物；结构","example":"The workshop word became the cloth.","exampleCN":"作坊词变成了布料的名称。"},{"word":"*dhabh-","structure":"reconstructed root","meaning":"to fit together","meaningCN":"拼合；装配","example":"The form is a reconstruction, not a recorded word.","exampleCN":"该形式是重构，不是有记录的词。"}],"latinEntries":[{"word":"faber","structure":"Latin noun","meaning":"smith, artisan","meaningCN":"铁匠；工匠"},{"word":"fabrica","structure":"Latin noun","meaning":"workshop, craft","meaningCN":"作坊；手艺"},{"word":"fabricare","structure":"Latin verb","meaning":"to make, construct","meaningCN":"制作；建造"},{"word":"fabricatio","structure":"Latin noun from fabricare","meaning":"a making, a structure","meaningCN":"制作；构造物"}],"derivatives":[{"word":"fabrication","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「制造；捏造」"},{"word":"fabricator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「制造者；捏造者」"},{"word":"prefabricate","pos":"v.","zh":"由表示「预先」的前缀加该动词构成，义为「预制」"},{"word":"prefabrication","pos":"n.","zh":"由预制动词加表示动作结果的名词尾构成，义为「预制加工」"},{"word":"fabric","pos":"n.","zh":"由同一拉丁词干经法语而来，义为「织物；结构」"}]}},{"word":"fabrication process","ipa_uk":"/ˌfæbrɪˈkeɪʃn ˈprəʊses/","ipa_us":"/ˌfæbrɪˈkeɪʃn ˈprɑːses/","definition_zh":"制造工艺流程；加工工序；装配流程；半导体制造工艺；捏造过程","definition_en":"the sequence of steps by which raw material or parts are turned into a finished product, or the course of inventing something false","core_image":"一卷钢板沿轨道依次经过开卷、冲压、焊接与喷漆五台设备，每台旁都挂着检验牌","scene":"墙上挂着流程图，钢板从开卷到喷漆要经过五道工序，每道工序后都有一次检验。A clear fabrication process keeps every step of the bracket under control.","sceneCN":"这里指把原料变成成品的一整套加工步骤（第 1 个义项：制造工艺流程）；句意为清晰的制造流程让支架的每一步都处于受控状态。图中可辨识物件：卷料、冲床、焊接工位、喷漆房、检验台。","pos":[{"tag":"n.","zh":"制造工艺流程；加工工序；捏造过程"}],"collocations":[{"phrase":"fabrication process flow","zh":"制造工艺流程"},{"phrase":"fabrication process step","zh":"制造工序"},{"phrase":"metal fabrication process","zh":"金属加工工艺"},{"phrase":"semiconductor fabrication process","zh":"半导体制造工艺"},{"phrase":"fabrication process control","zh":"工艺控制"},{"phrase":"fabrication process design","zh":"工艺设计"}],"forms":[{"label":"单数","form":"fabrication process"},{"label":"复数","form":"fabrication processes"},{"label":"核心动词","form":"fabricate"},{"label":"动作名词","form":"fabrication"},{"label":"相关形容词","form":"fabricated"}],"derivatives":[{"word":"fabricate","pos":"v.","zh":"该复合词的核心动词，义为「制造；编造」"},{"word":"fabrication","pos":"n.","zh":"该复合词的核心名词，义为「制造；捏造」"},{"word":"fabricator","pos":"n.","zh":"由核心动词加表示施动者的名词尾构成，义为「制造者」"},{"word":"prefabrication","pos":"n.","zh":"由表示「预先」的前缀加核心动词再加名词尾构成，义为「预制加工」"},{"word":"process control","pos":"n.","zh":"由本词后半部分加表示控制的名词构成，义为「过程控制」"}],"senses":[{"no":"01","title":"The full sequence of making","titleCN":"一整套制造步骤","definition":"the ordered set of steps that turns raw material into a finished product","definitionCN":"把原料变成成品的一系列有次序的步骤","example":"The fabrication process begins with cutting and ends with inspection.","exampleCN":"这套制造流程从切割开始，以检验结束。","why":"The whole point of the phrase is order: each step assumes the one before it.","whyCN":"这个说法的要点就是次序：每一步都以前一步为前提。"},{"no":"02","title":"The metalworking route","titleCN":"金属加工工序","definition":"the cutting, forming and welding steps used to make a metal article","definitionCN":"制作金属件所用的切割、成形与焊接步骤","example":"Their fabrication process uses laser cutting before bending.","exampleCN":"他们的加工工序先激光切割，再折弯。","why":"Metal work is the oldest home of the word, and each trade step settled into its own stage.","whyCN":"金属加工是这个词语最古老的归处，每道手艺都沉淀为独立工序。"},{"no":"03","title":"The assembly route","titleCN":"装配流程","definition":"the order in which components are fitted together into a unit","definitionCN":"把部件装成一个整体所依照的顺序","example":"The fabrication process for the gearbox fixes the bearing before the cover.","exampleCN":"减速箱的装配流程先装轴承，再上端盖。","why":"When making means joining, the process becomes a sequence of fitting operations.","whyCN":"当「制作」指接合时，流程就成了一连串装配操作。"},{"no":"04","title":"The chip-making route","titleCN":"芯片制造工艺","definition":"the series of photographic and chemical steps that build circuits on a wafer","definitionCN":"在晶圆上构建电路的一连串光刻与化学步骤","example":"The fabrication process for these chips needs a clean room.","exampleCN":"这些芯片的制造工艺需要洁净室。","why":"Semiconductor work borrowed the metal shop word for a process measured in nanometres.","whyCN":"半导体行业借用了金属作坊的词，用来指以纳米计量的工艺。"},{"no":"05","title":"The precast route","titleCN":"预制构件生产流程","definition":"the factory sequence that produces standard parts before they reach the site","definitionCN":"在构件运到现场之前，于工厂生产标准件的流程","example":"The fabrication process for the panels includes curing in a mould.","exampleCN":"这些墙板的生产流程包括在模具中养护。","why":"Moving work indoors split the trade into repeatable shop stages.","whyCN":"把活计搬进室内，使这门手艺分成了可重复的车间工序。"},{"no":"06","title":"The additive route","titleCN":"增材制造流程","definition":"the layer-by-layer sequence by which a machine builds a part from a digital model","definitionCN":"机器依据数字模型逐层堆出零件的流程","example":"Their fabrication process prints the bracket in one piece.","exampleCN":"他们的制造流程把支架一次打印成整体。","why":"A new way of making still needed the old word for an ordered set of steps.","whyCN":"新的制作方式仍然需要那个表示有序步骤的老词。"},{"no":"07","title":"The course of inventing a story","titleCN":"编造说法的过程","definition":"the way a false account is gradually built up and made to sound consistent","definitionCN":"一段假说法被逐步搭建、并弄得听起来自洽的过程","example":"The fabrication process behind the rumour took weeks.","exampleCN":"这条谣言背后的编造过程持续了数周。","why":"The false sense of the root verb carries over, and a lie also has stages.","whyCN":"核心动词的虚假义延续下来，谎言同样有阶段。"},{"no":"08","title":"The course of forging records","titleCN":"伪造记录的流程","definition":"the steps by which false documents or data are prepared to pass inspection","definitionCN":"把假文件或假数据准备到能通过检查的步骤","example":"Auditors traced the fabrication process to a single laptop.","exampleCN":"审计人员把这条伪造流程追到了一台笔记本电脑。","why":"Paperwork has a route of its own, and the phrase follows the making wherever it goes.","whyCN":"文书有自己的路线，而这个说法跟着「制作」走到哪里算哪里。"}],"etymology":{"intro":{"en":"Fabrication process joins a Latin word for skilled making to a Latin word for going forward. The compound itself is modern English, and its engineering sense grew with factory production.","cn":"这个复合词把拉丁语表示「手艺制作」的词与表示「向前走」的词接在一起。复合形式本身是现代英语，其工程义随工厂生产发展而来。"},"items":[{"era":"LATIN FABER","en":"The making half goes back to faber, a smith, and fabrica, the shop where such work was done.","cn":"表示「制作」的那一半可追到铁匠 faber，以及做这类活的作坊 fabrica。"},{"era":"LATIN FABRICARE","en":"Fabricare supplied the verb for shaping and constructing, later shortened into the English making word.","cn":"fabricare 提供了表示塑造与建造的动词，后来演变为英语的「制作」词。"},{"era":"LATIN PROCEDERE","en":"Process comes from procedere, to go forward, built from pro, forward, and cedere, to go or yield.","cn":"process 来自 procedere「向前走」，由表示「向前」的前缀与表示「走、让」的词根构成。"},{"era":"MEDIEVAL PROCESS","en":"In medieval Latin processus named a progression or a course of events before English used it for a set of operations.","cn":"中世纪拉丁语 processus 指推进或事件进程，后来英语才用它指一套操作。"},{"era":"INDUSTRIAL COMPOUND","en":"Factory work made the two words a fixed pair, naming the route a material follows through machines.","cn":"工厂生产使这两个词固定成对，用来指材料穿过各台机器的路线。"},{"era":"SEMICONDUCTOR EXTENSION","en":"The chip industry adopted the phrase in the later twentieth century, and the first attestation date of that adoption is uncertain within that period.","cn":"芯片行业在二十世纪后期采用了这个说法，采用的首见年份不确定，只能定在二十世纪后期。"}]},"similar":{"note":{"en":"The first group looks or sounds like the phrase; the second group names neighbouring ideas about production routes.","cn":"第一组在形音上与这个词组相近；第二组是与「生产路线」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fabrication","ipa":"/ˌfæbrɪˈkeɪʃn/","tag":"same root","definition":"The act or result of making, and also a lie; the phrase adds the order of steps.","definitionCN":"指制作的行为或结果，也指谎言；本词组则加上了步骤次序。"},{"word":"fabricate","ipa":"/ˈfæbrɪkeɪt/","tag":"same root","definition":"The verb behind the phrase, covering both making and inventing.","definitionCN":"本词组背后的动词，兼指制作与编造。"},{"word":"fabricator","ipa":"/ˈfæbrɪkeɪtə/","tag":"same root","definition":"The worker or firm that carries out the making steps.","definitionCN":"指执行这些制作步骤的工人或企业。"},{"word":"processing","ipa":"/ˈprəʊsesɪŋ/","tag":"same root","definition":"The handling of material through a series of operations; it shares the second half of the phrase.","definitionCN":"指让材料经过一系列操作；与本词组后半部分同源。"},{"word":"fabrication plant","ipa":"/ˌfæbrɪˈkeɪʃn plɑːnt/","tag":"related phrase","definition":"The building where such a process is carried out, rather than the process itself.","definitionCN":"指执行该流程的厂房，而非流程本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manufacturing process","ipa":"/ˌmænjuˈfæktʃərɪŋ ˈprəʊses/","tag":"near meaning","definition":"The full industrial route for making goods, usually on a larger scale.","definitionCN":"指大规模生产商品的全套工业路线。"},{"word":"production line","ipa":"/prəˈdʌkʃn laɪn/","tag":"near meaning","definition":"The physical arrangement of stations through which a product moves.","definitionCN":"指产品依次经过的各工位的实体排列。"},{"word":"workflow","ipa":"/ˈwɜːkfləʊ/","tag":"near meaning","definition":"The ordered set of tasks that a job passes through, not always physical.","definitionCN":"指一项工作经过的有序任务集合，不一定是实物的。"},{"word":"procedure","ipa":"/prəˈsiːdʒə/","tag":"near meaning","definition":"An established way of doing a task step by step.","definitionCN":"指按步骤完成任务的既定做法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real smith-shop source, the real running-forward source and real factory phrases.","cn":"正常联想使用真实的铁匠铺来源、真实的「向前走」来源与真实工厂搭配。"},"normal":[{"en":"The first half is the smith's shop; the second half is a road that goes forward.","cn":"前半是铁匠铺，后半是一条向前的路。"},{"en":"A process is a course of steps, so the phrase is literally the road a part travels.","cn":"流程就是一串步骤的进程，因此这个词组字面上就是零件走过的路。"},{"en":"Metal fabrication, semiconductor fabrication and additive fabrication are three real routes.","cn":"金属加工、半导体制造与增材制造是三条真实的工艺路线。"},{"en":"Process control is the phrase that watches every stage of that road.","cn":"工艺控制就是盯着这条路每一段的说法。"},{"en":"A fabrication process flow chart is the same phrase drawn as boxes and arrows.","cn":"工艺流程图就是把同一个词组画成方框与箭头。"}],"abstract":[{"en":"A process is a promise that step five will not happen before step four.","cn":"流程是一个承诺：第五步不会跑到第四步前面。"},{"en":"The phrase turns an object into an itinerary.","cn":"这个词组把一件东西变成了一份行程。"},{"en":"A lie also has a process, which is why the false sense never fully left the phrase.","cn":"谎言也有流程，所以虚假义从未完全离开这个词组。"}]},"examples":[{"en":"Engineers shortened the fabrication process by removing one heat cycle.","cn":"工程师减去一次加热循环，缩短了制造流程。"},{"en":"Every fabrication process needs a final dimensional check.","cn":"每套制造流程都需要最后的尺寸检验。"},{"en":"The auditor asked who designed the fabrication process for the records.","cn":"审计人员追问是谁设计了这套伪造记录的流程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「法布瑞克申 普绕塞斯」——铁匠铺的活排成一条向前的路：制造工艺流程","word":"fabrication process"},"root":"前半来自拉丁语 fabricare「制作」← fabrica「作坊」← faber「铁匠」；后半来自拉丁语 processus「进程」← procedere「向前走」，由 pro-「向前」与 cedere「走、让」构成。复合词为现代英语，工程义随工厂生产而定型。","sensesIntro":{"en":"Eight senses follow one route: the whole making sequence, the metalworking route, the assembly route, the chip route, the precast route, the additive route, and the two false routes of inventing a story and forging records.","cn":"八个义项沿着同一条路线：整套制造步骤、金属加工路线、装配路线、芯片路线、预制路线、增材路线，以及编造说法与伪造记录这两条虚假路线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a steel strip travels past five machines, each leaving the part closer to its final shape.","cn":"核心意象：一卷钢板依次经过五台机器，每过一台就离最终形状更近一步。"},"chain":["RAW MATERIAL","CUTTING","FORMING","JOINING","INSPECTION","FINISHED PART"],"branches":[{"senses":"01","en":"THE WHOLE ROUTE: every step from raw stock to a checked product.","cn":"整条路线：从毛坯到检验合格品的每一步。"},{"senses":"02 · 03","en":"THE TRADE ROUTES: metal cut and welded, or components fitted in a fixed order.","cn":"行业路线：金属被切割焊接，或部件按固定次序装配。"},{"senses":"04 · 06","en":"THE NEW ROUTES: circuits built on a wafer, and a part grown layer by layer.","cn":"新路线：在晶圆上造电路，以及逐层堆出零件。"},{"senses":"05","en":"THE SHOP ROUTE: standard panels made and cured before they travel to the site.","cn":"车间路线：标准墙板做好并养护后再运往现场。"},{"senses":"07 · 08","en":"THE FALSE ROUTES: a rumour built week by week, and a record forged step by step.","cn":"虚假路线：一周周搭起来的谣言，以及一步步伪造出来的记录。"}]},"affixes":{"intro":{"en":"The phrase pairs a Latin making stem with a Latin going-forward stem; both halves still breed English words.","cn":"这个词组把拉丁语的「制作」词干与「向前走」词干配在一起，两半至今都在生成英语词。"},"latinIntro":{"en":"Latin gives fabricare and procedere as the two sources; no single Latin phrase lies behind the English compound.","cn":"拉丁语提供了「制作」与「向前走」两个来源；英语这个复合词背后并没有一个对应的拉丁词组。"},"items":[{"word":"faber","structure":"Latin noun","meaning":"smith, artisan","meaningCN":"铁匠；工匠","example":"The first half begins at the forge.","exampleCN":"前半部分从铁匠炉开始。"},{"word":"fabricare","structure":"Latin verb","meaning":"to make, construct","meaningCN":"制作；建造","example":"It supplies the making verb.","exampleCN":"它提供了表示制作的动词。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result of making","meaningCN":"制作的行为或结果","example":"The ending turns the verb into a noun.","exampleCN":"这个词尾把动词变成名词。"},{"word":"pro-","structure":"Latin prefix","meaning":"forward","meaningCN":"向前","example":"The prefix gives the second half its direction.","exampleCN":"这个前缀给了后半部分方向。"},{"word":"cedere","structure":"Latin verb","meaning":"to go, yield","meaningCN":"走；让","example":"The root supplies the movement in process.","exampleCN":"这个词根提供了「进程」里的移动。"},{"word":"processus","structure":"Latin noun from procedere","meaning":"a going forward; a course","meaningCN":"前进；进程","example":"The noun names a course of events.","exampleCN":"这个名词指事件的过程。"},{"word":"-ess","structure":"noun ending through French","meaning":"state or course","meaningCN":"状态；进程","example":"It carries the Latin noun into English.","exampleCN":"它把拉丁名词带进英语。"},{"word":"process control","structure":"process plus control","meaning":"keeping a process within limits","meaningCN":"把流程控制在限值内","example":"The phrase guards every stage.","exampleCN":"这个说法守住每一段工序。"},{"word":"fabrication plant","structure":"fabrication plus plant","meaning":"the building where making happens","meaningCN":"进行制作的厂房","example":"The place is named after the work.","exampleCN":"场所按所做的事命名。"}],"latinEntries":[{"word":"fabricare","structure":"Latin verb","meaning":"to make, construct","meaningCN":"制作；建造"},{"word":"fabricatio","structure":"Latin noun","meaning":"a making","meaningCN":"制作"},{"word":"procedere","structure":"Latin verb","meaning":"to go forward","meaningCN":"向前走"},{"word":"processus","structure":"Latin noun","meaning":"a course, a advance","meaningCN":"进程；推进"}],"derivatives":[{"word":"fabrication","pos":"n.","zh":"本复合词的核心名词，义为「制造；捏造」"},{"word":"fabricate","pos":"v.","zh":"本复合词的核心动词，义为「制造；编造」"},{"word":"process","pos":"n./v.","zh":"本复合词的后半部分，义为「流程；处理」"},{"word":"processing","pos":"n.","zh":"由后半部分加表示进行的名词尾构成，义为「加工；处理」"},{"word":"process control","pos":"n.","zh":"由后半部分加表示控制的名词构成，义为「过程控制」"}]}},{"word":"assembly","ipa_uk":"/əˈsembli/","ipa_us":"/əˈsembli/","definition_zh":"装配；组装；组件；总成；集会；议会；汇编；装配线","definition_en":"the act of fitting parts together into a whole, the unit so made, or a gathering of people","core_image":"传送带把齿轮、轴承与外壳送到同一工位，最后一颗螺栓拧紧，整台减速箱成形","scene":"传送带把齿轮、轴承和外壳送到同一工位，工人按顺序装好，最后拧紧端盖。The assembly of the gearbox takes four stations and one final check.","sceneCN":"这里指把零件装成整体的装配过程（第 1 个义项：装配动作）；句意为减速箱的装配要经过四个工位和最后一次检验。图中可辨识物件：传送带、齿轮、轴承、端盖、扭力扳手。","pos":[{"tag":"n.","zh":"装配；组件；集会；议会；汇编"}],"collocations":[{"phrase":"assembly line","zh":"装配线"},{"phrase":"assembly plant","zh":"装配厂"},{"phrase":"final assembly","zh":"总装"},{"phrase":"assembly instructions","zh":"装配说明"},{"phrase":"general assembly","zh":"全体大会；联合国大会"},{"phrase":"assembly language","zh":"汇编语言"}],"forms":[{"label":"单数","form":"assembly"},{"label":"复数","form":"assemblies"},{"label":"动词","form":"assemble"},{"label":"施动名词","form":"assembler"},{"label":"过去分词形容词","form":"assembled"}],"derivatives":[{"word":"assemble","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「装配；集合」"},{"word":"assembler","pos":"n.","zh":"由动词加表示施动者的名词尾构成，义为「装配工；汇编程序」"},{"word":"assembled","pos":"adj.","zh":"由动词加已然词尾构成，义为「装配好的；集合起来的」"},{"word":"assemblyman","pos":"n.","zh":"由该名词加表示人的成分构成，义为「议员」"},{"word":"disassemble","pos":"v.","zh":"由表示「分开」的前缀加动词构成，义为「拆卸」"}],"senses":[{"no":"01","title":"The act of fitting parts","titleCN":"把零件装起来的动作","definition":"the process of putting separate components together to form a finished unit","definitionCN":"把分开的部件组合成一个成品的过程","example":"Assembly takes longer than machining for this housing.","exampleCN":"对这个壳体来说，装配比机加工更费时。","why":"The Latin source meant bringing together at one time, and the modern shop kept that gathering of parts.","whyCN":"拉丁语来源意为同时聚到一起，现代车间保留了这个「零件聚齐」的意思。"},{"no":"02","title":"The finished unit","titleCN":"装成的组件或总成","definition":"a set of parts that has been joined into one working unit","definitionCN":"已被接合成一个工作整体的一套零件","example":"Each assembly is tested before it leaves the bench.","exampleCN":"每个总成离开工作台前都要测试。","why":"Once the parts are together, the whole thing takes the name of the act that made it.","whyCN":"零件一旦合在一起，整体就沿用了使之成立的那个动作的名字。"},{"no":"03","title":"The line or shop","titleCN":"装配线或装配车间","definition":"the section of a factory where parts are fitted together, or the line itself","definitionCN":"工厂中把零件装合的部门，或装配线本身","example":"The assembly runs two shifts during the launch.","exampleCN":"投产期间装配线开两班。","why":"The act gave its name to the place and the line where it happens, a common shift from event to location.","whyCN":"动作给了发生它的地点与线路一个名字，这是从事件转向场所的常见转义。"},{"no":"04","title":"A gathering of people","titleCN":"人群的集会","definition":"a group of people who have come together for a shared purpose","definitionCN":"为共同目的聚到一起的一群人","example":"A crowd formed an assembly outside the gate.","exampleCN":"一群人在大门外聚集起来。","why":"People assembled long before machines did, and the noun kept the social meaning alongside the mechanical one.","whyCN":"人聚在一起比机器装配早得多，这个名词因此把社会义与机械义并留下来。"},{"no":"05","title":"A law-making body","titleCN":"议会或立法机构","definition":"a formal body of elected members who meet to make laws","definitionCN":"由当选成员组成、开会制定法律的正式机构","example":"The assembly passed the safety bill last week.","exampleCN":"议会上周通过了安全法案。","why":"A legislature is literally a standing gathering, and several languages name it with their word for assembly.","whyCN":"立法机构字面上就是一个常设的集会，多种语言都用本族的「集会」词为它命名。"},{"no":"06","title":"The school gathering","titleCN":"学校的集体朝会","definition":"a routine meeting of all pupils and staff, usually at the start of the day","definitionCN":"全体师生按例举行的集会，通常在一天开始时","example":"The head teacher spoke at morning assembly.","exampleCN":"校长在早间朝会上讲话。","why":"School life borrowed the plain social sense and gave it a timetable.","whyCN":"校园生活借用了朴素的社会义，再给它配上一张时间表。"},{"no":"07","title":"A low-level program language","titleCN":"汇编语言","definition":"a programming language whose instructions correspond closely to machine operations","definitionCN":"指令与机器操作密切对应的一种程序设计语言","example":"The firmware routine was written in assembly.","exampleCN":"这段固件程序是用汇编语言写的。","why":"The word for putting parts together was reused for putting machine instructions together.","whyCN":"表示「把部件拼起来」的词被再次用来指「把机器指令拼起来」。"},{"no":"08","title":"A kit of parts","titleCN":"待装的零件套件","definition":"a complete set of parts supplied together for a user to put together","definitionCN":"一并供应、供使用者自行组装的一整套零件","example":"The flat-pack assembly included every screw.","exampleCN":"这套平板包装的待装件配齐了每一颗螺钉。","why":"Before there is assembly there is a set of parts, and retail named the box after the job ahead.","whyCN":"在装配之前先有一套零件，零售业便用后面那道工序来命名这个箱子。"},{"no":"09","title":"The military call","titleCN":"军队集合号","definition":"a signal, usually on a bugle or drum, that orders soldiers to gather","definitionCN":"通常以军号或鼓发出、命令士兵集合的信号","example":"The bugler sounded assembly at dawn.","exampleCN":"号手在黎明吹响集合号。","why":"The oldest social sense turned into a formal signal, and the call keeps the noun alive in barracks.","whyCN":"最古老的社会义变成了正式信号，这个名词因此在军营里保留下来。"}],"etymology":{"intro":{"en":"Assembly comes through Old French assemblee, a gathering, from the verb assembler, and that verb goes back to Latin ad, to, plus simul, together. The mechanical sense is a later English development.","cn":"这个词经古法语 assemblee「集会」而来，源自动词 assembler；该动词可追到拉丁语的 ad「向」与 simul「同时、一起」。机械义是英语后来发展出的用法。"},"items":[{"era":"LATIN SIMUL","en":"Simul meant at the same time or together, and it is the element that gives the whole family its sense of gathering.","cn":"这个词意为「同时、一起」，是整族词「聚拢」义的来源成分。"},{"era":"LATIN ASSIMULARE","en":"The Latin verb meant to bring together or make alike, built with ad plus simul; its later form passed into French.","cn":"这一拉丁动词意为「聚到一起、使相同」，由 ad 与 simul 构成；其后期形式传入法语。"},{"era":"OLD FRENCH ASSEMBLER","en":"French assembler meant to gather people or things, and the derived noun assemblee named the gathering itself.","cn":"法语 assembler 指把人或物聚在一起，派生名词 assemblee 指集会本身。"},{"era":"ENGLISH, 14TH CENTURY","en":"English adopted the noun for a meeting of people, which remains the sense of the political and school uses.","cn":"英语接受了这个指人群集会的名词，政治与学校用法仍保留此义。"},{"era":"MECHANICAL SHIFT","en":"With industrial production the same noun was applied to the joining of parts; the first attestation period of this shift is uncertain, though it falls after the industrial revolution.","cn":"随着工业生产，同一个名词被用于零件的接合；这一转变的首见时期不确定，只能定在工业革命之后。"},{"era":"COMPUTING","en":"In the mid twentieth century the word entered computing for a low-level language that builds machine instructions.","cn":"二十世纪中叶，这个词进入计算机领域，指一种拼装机器指令的低级语言。"}]},"similar":{"note":{"en":"The first group looks or sounds like assembly; the second group names neighbouring ideas of joining and meeting.","cn":"第一组在形音上与「assembly」相近；第二组是与「拼合、集会」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"assemble","ipa":"/əˈsembl/","tag":"same root","definition":"The verb for putting parts or people together.","definitionCN":"指把零件或人聚到一起的动词。"},{"word":"assembler","ipa":"/əˈsemblə/","tag":"same root","definition":"A worker who fits parts, or a program that converts assembly code.","definitionCN":"指装配工，也指转换汇编代码的程序。"},{"word":"disassemble","ipa":"/ˌdɪsəˈsembl/","tag":"derived opposite","definition":"To take a unit apart into its components.","definitionCN":"指把整体拆成部件。"},{"word":"assimilation","ipa":"/əˌsɪməˈleɪʃn/","tag":"same root","definition":"The process of becoming alike or absorbed; it shares the Latin together element but not the shop sense.","definitionCN":"指变得相同或被吸收的过程；共享拉丁语「一起」成分，但没有车间义。"},{"word":"assemblee","ipa":"/asɑːmˈbleɪ/","tag":"source form","definition":"The Old French noun for a gathering, the direct ancestor of the English word.","definitionCN":"古法语指集会的名词，是英语词的直接祖先。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assembly line","ipa":"/əˈsembli laɪn/","tag":"near meaning","definition":"The moving line along which a product is put together station by station.","definitionCN":"指产品逐站装合的移动生产线。"},{"word":"gathering","ipa":"/ˈɡæðərɪŋ/","tag":"near meaning","definition":"A meeting or coming together of people, without the mechanical sense.","definitionCN":"指人的聚会或聚集，不含机械义。"},{"word":"fitting","ipa":"/ˈfɪtɪŋ/","tag":"near meaning","definition":"The act of placing and adjusting a part into its position.","definitionCN":"指把部件就位并调整的动作。"},{"word":"subassembly","ipa":"/ˌsʌbəˈsembli/","tag":"near meaning","definition":"A smaller unit put together before it joins the final product.","definitionCN":"指在进入总装前先装好的较小总成。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real French gathering source, the real machine-shop family and real fixed phrases.","cn":"正常联想使用真实的法语集会来源、真实的车间同族词与真实固定搭配。"},"normal":[{"en":"Latin simul meant together, and every sense of assembly is some kind of together.","cn":"拉丁语 simul 意为一起，assembly 的每个义项都是某种「一起」。"},{"en":"Assembly line, assembly plant and final assembly are the shop phrases.","cn":"装配线、装配厂与总装是车间里的说法。"},{"en":"The General Assembly is the political sense written on a nameplate.","cn":"联合国大会就是把政治义写在了门牌上。"},{"en":"Assemble, assembler and disassemble cover the act, the worker and the reverse.","cn":"装配、装配者与拆卸覆盖了动作、执行者与反向操作。"},{"en":"Morning assembly at school is the same gathering word with a bell.","cn":"学校的早间朝会是同一个「集会」词配上一只铃。"}],"abstract":[{"en":"An assembly is a whole that exists only while its parts agree to stay.","cn":"装配体是一个只有零件同意留下时才存在的整体。"},{"en":"The line is a sentence written in stations instead of words.","cn":"装配线是用工位而不是词写成的句子。"},{"en":"A parliament and a gearbox share one name because both are gatherings that must hold together.","cn":"议会与减速箱共用一个名字，因为两者都是必须撑住不散的集合。"}]},"examples":[{"en":"The assembly of the pump is checked with a torque wrench.","cn":"泵的装配要用扭力扳手检查。"},{"en":"A faulty bearing stopped the whole assembly line.","cn":"一个坏轴承让整条装配线停了下来。"},{"en":"The assembly voted to extend the inspection programme.","cn":"议会投票决定延长检查计划。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿森布利」——把零件一个个「阿」地凑齐、森森排好，最后成一体：装配、集会","word":"assembly"},"root":"古法语 assemblee「集会」← assembler「聚在一起」← 拉丁语 adsimulare ← ad-「向」+ simul「同时、一起」。原义为人的聚集，工业时代转指零件接合，二十世纪中叶又进入计算机领域指汇编语言；机械义转变的确切时期来源不确定。","sensesIntro":{"en":"Nine senses gather something: parts into a unit, a unit that results, the line that makes it, people at a meeting, a legislature, a school morning, a program language, a kit of parts, and a bugle call.","cn":"九个义项都在把东西聚起来：零件聚成整体、聚成的总成、完成它的装配线、开会的人群、立法机构、学校朝会、程序语言、待装套件与军号集合。"},"semanticMap":{"core":{"en":"CORE IMAGE: parts arrive one by one and leave as a single gearbox.","cn":"核心意象：零件一件件到来，离开时已是一台完整的减速箱。"},"chain":["SEPARATE PARTS","ARRIVAL AT STATION","FITTING","TIGHTENING","TESTED UNIT","POLITICAL GATHERING"],"branches":[{"senses":"01","en":"THE ACT: hands and tools fit one component after another.","cn":"动作：手与工具把部件一件件装上。"},{"senses":"02 · 08","en":"THE RESULT AND THE KIT: the joined unit, and the box of parts waiting to become one.","cn":"结果与套件：接合好的整体，以及等待变成整体的那箱零件。"},{"senses":"03","en":"THE PLACE: the line and the shop where fitting happens all day.","cn":"场所：整天进行装配的线路与车间。"},{"senses":"04 · 06 · 09","en":"PEOPLE GATHERED: a crowd, a school morning, and a bugle that calls soldiers in.","cn":"聚起来的人：人群、学校朝会，以及把士兵召回来的军号。"},{"senses":"05 · 07","en":"THE FORMAL GATHERINGS: a legislature that meets to decide, and instructions gathered into a program language.","cn":"正式集合：开会决定的立法机构，以及把指令聚成程序语言。"}]},"affixes":{"intro":{"en":"Assembly is a French noun resting on a Latin prefix and a Latin together word; its English family is still productive.","cn":"这是一个法语名词，建立在拉丁语前缀与表示「一起」的词上；其英语词族至今仍在生成新词。"},"latinIntro":{"en":"Latin ad and simul are the two real sources, and the Latin verb adsimulare stands behind the French form.","cn":"拉丁语的 ad 与 simul 是两个真实来源，拉丁动词 adsimulare 则位于法语形式之后。"},"items":[{"word":"ad-","structure":"Latin prefix","meaning":"to, toward","meaningCN":"向；朝","example":"The prefix points the gathering inward.","exampleCN":"这个前缀把聚集指向内部。"},{"word":"simul","structure":"Latin adverb","meaning":"at the same time; together","meaningCN":"同时；一起","example":"The word supplies the core of togetherness.","exampleCN":"这个词提供了「一起」的核心。"},{"word":"adsimulare","structure":"ad- plus simul","meaning":"to bring together, make alike","meaningCN":"聚到一起；使相同","example":"The Latin verb is the bridge to French.","exampleCN":"这一拉丁动词是通往法语的桥。"},{"word":"assembler","structure":"French verb plus agent ending","meaning":"to gather","meaningCN":"聚集","example":"The French verb names the act of gathering.","exampleCN":"这个法语动词指聚集的动作。"},{"word":"-ee","structure":"French past-participle noun ending","meaning":"the result of the act","meaningCN":"动作的结果","example":"The ending turns the verb into a gathering.","exampleCN":"这个词尾把动词变成一场集会。"},{"word":"-ly","structure":"English noun ending","meaning":"state or quality","meaningCN":"状态或性质","example":"It carries the French noun into English shape.","exampleCN":"它把法语名词带入英语形式。"},{"word":"-er","structure":"agent noun ending","meaning":"the one who gathers","meaningCN":"进行聚集的人或物","example":"The worker and the program both take it.","exampleCN":"工人与程序都用了这个词尾。"},{"word":"dis-","structure":"Latin prefix","meaning":"apart, away","meaningCN":"分开；离开","example":"The prefix reverses the fitting.","exampleCN":"这个前缀把装配反过来。"},{"word":"sub-","structure":"Latin prefix","meaning":"under, below","meaningCN":"在下；次级","example":"It marks a smaller unit inside the whole.","exampleCN":"它标出整体内部较小的单元。"}],"latinEntries":[{"word":"simul","structure":"Latin adverb","meaning":"together, at the same time","meaningCN":"一起；同时"},{"word":"adsimulare","structure":"Latin verb","meaning":"to bring together","meaningCN":"聚到一起"},{"word":"assimilare","structure":"Latin verb","meaning":"to make alike","meaningCN":"使相同"}],"derivatives":[{"word":"assemble","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「装配；集合」"},{"word":"assembler","pos":"n.","zh":"由动词加表示施动者的名词尾构成，义为「装配工；汇编程序」"},{"word":"disassemble","pos":"v.","zh":"由表示「分开」的前缀加动词构成，义为「拆卸」"},{"word":"subassembly","pos":"n.","zh":"由表示「次级」的前缀加该名词构成，义为「分总成」"},{"word":"assemblyman","pos":"n.","zh":"由该名词加表示人的成分构成，义为「议员」"}]}},{"word":"installation","ipa_uk":"/ˌɪnstəˈleɪʃn/","ipa_us":"/ˌɪnstəˈleɪʃn/","definition_zh":"安装；安装好的设备；就职；艺术装置；军事设施；软件安装","definition_en":"the act of putting equipment or a system in place and making it ready to use, the equipment so placed, or a formal ceremony of appointing someone","core_image":"屋顶的空调外机被吊上支架，铜管接好，抽真空后加注冷媒，出风口吹出凉风","scene":"屋顶的空调外机被吊上支架，铜管接好后抽真空，再加注冷媒，试机时出风正常。The installation of the rooftop unit took a crane and two technicians.","sceneCN":"这里指把设备装到位并接通使其可用（第 1 个义项：设备安装）；句意为屋顶机组的安装动用了吊车和两名技师。图中可辨识物件：外机、支架、铜管、真空泵、冷媒罐。","pos":[{"tag":"n.","zh":"安装；装置；就职；军事设施"}],"collocations":[{"phrase":"installation cost","zh":"安装费用"},{"phrase":"installation guide","zh":"安装指南"},{"phrase":"software installation","zh":"软件安装"},{"phrase":"electrical installation","zh":"电气安装工程"},{"phrase":"installation art","zh":"装置艺术"},{"phrase":"military installation","zh":"军事设施"}],"forms":[{"label":"单数","form":"installation"},{"label":"复数","form":"installations"},{"label":"动词","form":"install"},{"label":"施动者","form":"installer"},{"label":"形容词","form":"installed"}],"derivatives":[{"word":"install","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「安装；使就职」"},{"word":"installer","pos":"n.","zh":"由动词加表示施动者的名词尾构成，义为「安装者；安装程序」"},{"word":"installed","pos":"adj.","zh":"由动词加已然词尾构成，义为「已安装的」"},{"word":"reinstall","pos":"v.","zh":"由表示「重新」的前缀加动词构成，义为「重新安装」"},{"word":"installation","pos":"n.","zh":"本词本身，义为「安装；装置」"}],"senses":[{"no":"01","title":"Putting equipment in place","titleCN":"把设备装到位","definition":"the work of placing a machine or system and connecting it so that it can run","definitionCN":"把机器或系统就位、接好并使其能够运转的工作","example":"Installation of the boiler takes three days.","exampleCN":"锅炉安装需要三天。","why":"The Latin source meant placing someone in a seat, and equipment is placed on its own seat, a base or a bracket.","whyCN":"拉丁语来源意为把人安置到座位上，设备也被安置在它自己的座位、底座或支架上。"},{"no":"02","title":"The equipment installed","titleCN":"装好的设备","definition":"the apparatus or system that has been put in place and is in working order","definitionCN":"已经就位并可正常运转的装置或系统","example":"The new installation supplies power to the whole wing.","exampleCN":"这套新设备为整栋侧楼供电。","why":"The name of the act passes to the thing that results from it, as with many building words.","whyCN":"动作的名字转给了它产生的东西，许多建筑类词都是这样。"},{"no":"03","title":"Software loading","titleCN":"软件安装","definition":"the process of copying a program onto a device and preparing it to run","definitionCN":"把程序复制到设备上并准备运行的过程","example":"The installation failed because the disk was full.","exampleCN":"由于磁盘已满，这次软件安装失败了。","why":"A program is placed on a machine just as a pump is placed in a plant, so the same noun carried over.","whyCN":"程序被放进机器，就像泵被放进工厂，同一个名词因此延续下来。"},{"no":"04","title":"A formal appointment","titleCN":"正式就职","definition":"a ceremony in which a person is formally placed in an office or position","definitionCN":"正式把某人安放到某个职位上的仪式","example":"The installation of the new director took place in the hall.","exampleCN":"新主任的就职仪式在大厅举行。","why":"This is the oldest sense: a person is installed into a seat, and the seat is the office.","whyCN":"这是最古老的一层：人被安放进一个座位，而那个座位就是职位。"},{"no":"05","title":"An art installation","titleCN":"艺术装置","definition":"a work of art built for a particular space, often filling the room","definitionCN":"为特定空间搭建的艺术作品，常占满整个房间","example":"The gallery installation uses fifty hanging lamps.","exampleCN":"这件画廊装置用了五十盏悬吊灯。","why":"Art borrowed the fitting word for a work that is placed into a room rather than hung on a wall.","whyCN":"艺术借用了「安置」这个词，指被放进房间里、而不是挂在墙上的作品。"},{"no":"06","title":"A military base","titleCN":"军事设施","definition":"a permanent military site with buildings, equipment and a garrison","definitionCN":"设有建筑、装备与驻军的常设军事场所","example":"The installation covers four hundred hectares.","exampleCN":"这处军事设施占地四百公顷。","why":"A base is a fixed placing of forces, and military language kept the settled sense of the noun.","whyCN":"基地是把兵力固定安置下来，军事语言保留了这个名词「安顿」的意思。"},{"no":"07","title":"A building services job","titleCN":"系统安装工程","definition":"the trade work of fitting wiring, piping or heating into a building","definitionCN":"把线路、管道或供暖系统装进建筑的行业工作","example":"The electrical installation was signed off on Friday.","exampleCN":"电气安装工程周五通过验收。","why":"Whole trades grew around placing services in buildings, and the noun names both the job and its result.","whyCN":"整门行业围绕把管线装进建筑而发展，这个名词兼指工程与其成果。"},{"no":"08","title":"A display arrangement","titleCN":"陈列布置","definition":"the arrangement of objects in a space for exhibition or display","definitionCN":"为展览或展示在空间里摆放物件的方式","example":"The museum installation puts the tools in a circle.","exampleCN":"博物馆的陈列把这些工具摆成一圈。","why":"The art sense widened to any deliberate placing of objects in a room.","whyCN":"艺术义扩展为任何有意把物件放进房间的摆置。"}],"etymology":{"intro":{"en":"Installation goes back to Medieval Latin installatio and the verb installare, to place in a seat, from in, in, and stallum, a stall or seat. The word entered English through French and only later covered equipment.","cn":"这个词可追到中世纪拉丁语 installatio 与动词 installare「安置在座位上」，由 in「在……里」与 stallum「座位、位置」构成。它经法语进入英语，后来才用于设备。"},"items":[{"era":"LATIN IN-","en":"The prefix meant in or into, and it marks the movement of someone or something into a fixed place.","cn":"这个前缀意为「在内、进入」，标出人或物进入一个固定位置的动作。"},{"era":"LATIN STALLUM","en":"Stallum meant a stall, stand or seat, a word of Germanic origin rather than native Latin.","cn":"这个词指摊位、架子或座位，属日耳曼语来源，而非拉丁语本族词。"},{"era":"MEDIEVAL LATIN INSTALLARE","en":"The verb meant to place a cleric or official in his seat, and the ceremony was part of the meaning.","cn":"这一动词意为把教士或官员安置到他的座位上，仪式本身就是词义的一部分。"},{"era":"FRENCH AND ENGLISH","en":"French installer and the noun installation carried the word into English, where the appointment sense came first.","cn":"法语 installer 与名词 installation 把词带入英语，其中就职义最先出现。"},{"era":"INDUSTRIAL WIDENING","en":"From the eighteenth century the word was applied to placing machinery, pipes and wiring; the first attestation date of the widening is uncertain and can only be placed at or after the eighteenth century.","cn":"从十八世纪起，这个词被用于安放机械、管道与线路；这一扩展的首见年代不确定，只能约略定在十八世纪及其后。"},{"era":"MODERN EXTENSIONS","en":"Software and installation art gave the noun two new homes in the later twentieth century, both keeping the idea of placing something into a prepared space.","cn":"软件与装置艺术在二十世纪后期给了这个名词两个新归宿，都保留了「把东西放进预备好的空间」这一意思。"}]},"similar":{"note":{"en":"The first group looks or sounds like installation; the second group names neighbouring ideas of fitting and placing.","cn":"第一组在形音上与「installation」相近；第二组是与「装设、安放」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"install","ipa":"/ɪnˈstɔːl/","tag":"same root","definition":"The verb for placing equipment or appointing a person.","definitionCN":"指安放设备或任命人员的动词。"},{"word":"installer","ipa":"/ɪnˈstɔːlə/","tag":"same root","definition":"A person who fits equipment, or a program that sets software up.","definitionCN":"指安装设备的人，也指安装软件的程序。"},{"word":"instalment","ipa":"/ɪnˈstɔːlmənt/","tag":"different root","definition":"One part of a payment or a serial story; it looks close but belongs to a different settlement word.","definitionCN":"指分期付款的一期或连载的一段；形近但属于另一个表示「结算」的词。"},{"word":"stall","ipa":"/stɔːl/","tag":"same root","definition":"A stand or a seat, the source noun hidden inside installation.","definitionCN":"指摊位或座位，是藏在「安装」一词里的来源名词。"},{"word":"instance","ipa":"/ˈɪnstəns/","tag":"different root","definition":"An example or occurrence; it shares the opening sound but not the seat.","definitionCN":"指例子或事例；开头音相同，但与「座位」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fitting","ipa":"/ˈfɪtɪŋ/","tag":"near meaning","definition":"The act of adjusting and fixing a part into position.","definitionCN":"指把部件调整并固定到位的动作。"},{"word":"setup","ipa":"/ˈsetʌp/","tag":"near meaning","definition":"The arranging of equipment so that it is ready to work.","definitionCN":"指把设备安排到可工作的状态。"},{"word":"erection","ipa":"/ɪˈrekʃn/","tag":"near meaning","definition":"The raising and fixing of a structure or machine into place.","definitionCN":"指把结构或机器立起并固定到位。"},{"word":"commissioning","ipa":"/kəˈmɪʃənɪŋ/","tag":"near meaning","definition":"The testing and handing over of a new plant after installation.","definitionCN":"指新设备安装后进行的测试与移交。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real seat word inside the term, its real trade family and real building phrases.","cn":"正常联想使用这个术语里真实的「座位」词、真实行业词族与真实建筑搭配。"},"normal":[{"en":"The hidden noun is stall, a seat, so installation is literally seating something.","cn":"藏在里面的是 stall「座位」，因此 installation 字面上就是给某物安排座位。"},{"en":"The first installation was a bishop being seated in his church.","cn":"最早的一次「就职」是把主教安置到他的教堂座位上。"},{"en":"Install, installer and reinstall are the everyday family.","cn":"安装、安装者与重装是日常同族词。"},{"en":"Electrical installation and installation cost are real contract phrases.","cn":"电气安装工程与安装费用是真实的合同说法。"},{"en":"Installation art puts a whole room in place instead of a picture on a wall.","cn":"装置艺术安置的是整个房间，而不是墙上的一幅画。"}],"abstract":[{"en":"Installation is the moment a thing stops being cargo and starts being part of the building.","cn":"安装就是一件东西不再是货物、开始成为建筑一部分的那一刻。"},{"en":"Every installed machine has accepted a seat someone else prepared.","cn":"每一台装好的机器都接受了一个别人预备好的座位。"},{"en":"Software installation is the same ceremony without a crane.","cn":"软件安装是同一场仪式，只是没有吊车。"}]},"examples":[{"en":"The installation of the turbine was delayed by heavy rain.","cn":"涡轮机的安装因大雨推迟。"},{"en":"A faulty cable turned the installation into a fire risk.","cn":"一根有故障的电缆使这套设备成了火灾隐患。"},{"en":"Visitors walked through the installation for twenty minutes.","cn":"参观者在这件装置里走了二十分钟。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因斯特雷申」——把机器「因」地放进它的座位、斯特拉稳：安装、就职","word":"installation"},"root":"中世纪拉丁语 installare「安置在座位上」← in-「在内」+ stallum「座位、摊位」（日耳曼语来源）；名词 installatio 经法语进入英语。最早义为教士或官员就职，十八世纪起扩展到机械与管线安装，确切年代来源不确定；二十世纪后期又衍生软件安装与装置艺术。","sensesIntro":{"en":"Eight senses place something: equipment on a base, the equipment that results, a program on a disk, a person in an office, a work in a gallery, a base on the ground, services in a building, and objects in a display.","cn":"八个义项都在安置某物：把设备放上底座、安置后形成的设备、把程序装进磁盘、把人安置到职位、把作品放进画廊、把基地建在地上、把系统装进建筑、把物件摆进陈列。"},"semanticMap":{"core":{"en":"CORE IMAGE: a unit is lifted onto a prepared base, connected and switched on.","cn":"核心意象：一台机组被吊上预备好的底座，接好管线并通电运行。"},"chain":["A SEAT","A PERSON PLACED","A MACHINE PLACED","CONNECTIONS MADE","SYSTEM RUNNING","SPACE OCCUPIED"],"branches":[{"senses":"01","en":"THE ACT OF PLACING: equipment moved onto its base and made ready.","cn":"安置的动作：设备被移到它的底座上并准备就绪。"},{"senses":"02 · 07","en":"THE WORKING SYSTEM: the installed apparatus, and the trade that wires a whole building.","cn":"运行的系统：装好的装置，以及给整栋建筑布线的行业。"},{"senses":"03","en":"THE PROGRAM SEATED: software copied in and made ready to run.","cn":"程序就座：软件被复制进来并准备运行。"},{"senses":"04 · 06","en":"THE FORMAL SEAT: a person installed in office, and a garrison installed on a base.","cn":"正式座位：人被安放到职位上，以及驻军被安置在基地里。"},{"senses":"05 · 08","en":"THE OCCUPIED ROOM: a work built for a gallery, and objects arranged for display.","cn":"被占用的房间：为画廊搭建的作品，以及为陈列摆好的物件。"}]},"affixes":{"intro":{"en":"Installation is built from a Latin prefix, a Germanic-derived Latin noun and a French noun ending.","cn":"这个词由一个拉丁语前缀、一个源自日耳曼语的拉丁名词和一个法语名词词尾构成。"},"latinIntro":{"en":"Latin in and stallum are the real parts; stallum itself came from Germanic, so it is not a native Latin root.","cn":"拉丁语的 in 与 stallum 是真实构件；stallum 本身来自日耳曼语，并非拉丁语本族词根。"},"items":[{"word":"in-","structure":"Latin prefix","meaning":"in, into","meaningCN":"在内；进入","example":"The prefix marks entry into a place.","exampleCN":"这个前缀标出进入某处。"},{"word":"stallum","structure":"Medieval Latin noun of Germanic origin","meaning":"stall, stand, seat","meaningCN":"摊位；架子；座位","example":"The seat is the hidden core of the word.","exampleCN":"座位是这个词隐藏的核心。"},{"word":"installare","structure":"in- plus stallum","meaning":"to place in a seat","meaningCN":"安置在座位上","example":"The verb began as a ceremony of seating.","exampleCN":"这个动词最初是一场就座仪式。"},{"word":"installatio","structure":"Latin noun from installare","meaning":"a placing in office","meaningCN":"就职安置","example":"The noun first named an appointment.","exampleCN":"这个名词最初指任命。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result of","meaningCN":"动作或其结果","example":"The ending carries the verb into a noun.","exampleCN":"这个词尾把动词带入名词。"},{"word":"-er","structure":"agent noun ending","meaning":"the one who installs","meaningCN":"进行安装的人或物","example":"The installer fits the unit.","exampleCN":"安装者负责装好机组。"},{"word":"re-","structure":"Latin prefix","meaning":"again","meaningCN":"再次","example":"A reinstall repeats the placing.","exampleCN":"重装就是再做一次安置。"},{"word":"installed","structure":"verb plus completed-state ending","meaning":"already placed","meaningCN":"已经安置好的","example":"The adjective describes the finished state.","exampleCN":"这个形容词描述完成后的状态。"},{"word":"stall","structure":"English noun from the same Germanic source","meaning":"a stand or booth","meaningCN":"摊位；货摊","example":"The English word kept the physical stand.","exampleCN":"英语词保留了实体的摊位。"}],"latinEntries":[{"word":"stallum","structure":"Medieval Latin noun","meaning":"stall, seat","meaningCN":"摊位；座位"},{"word":"installare","structure":"Medieval Latin verb","meaning":"to place in a seat","meaningCN":"安置在座位上"},{"word":"installatio","structure":"Medieval Latin noun","meaning":"a placing in office","meaningCN":"就职安置"}],"derivatives":[{"word":"install","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「安装；使就职」"},{"word":"installer","pos":"n.","zh":"由动词加表示施动者的名词尾构成，义为「安装者；安装程序」"},{"word":"reinstall","pos":"v.","zh":"由表示「重新」的前缀加动词构成，义为「重新安装」"},{"word":"installed","pos":"adj.","zh":"由动词加已然词尾构成，义为「已安装的」"},{"word":"installment","pos":"n.","zh":"由动词的另一名词尾构成，义为「分期付款的一期」，与安装义分属不同用法"}]}},{"word":"install","ipa_uk":"/ɪnˈstɔːl/","ipa_us":"/ɪnˈstɔːl/","definition_zh":"安装；装设；使就职；任命；安顿；使扎根","definition_en":"to place equipment or a system in position and make it ready for use, or to put someone formally into an office","core_image":"技师把新泵放上底座，找正后拧紧地脚螺栓，再接上进出水管","scene":"技师把新泵放上底座，找正后拧紧地脚螺栓，再接上进出水管，然后点动试车。Two workers install the pump on its base before the line restarts.","sceneCN":"这里指把设备固定到位并接好管路（第 1 个义项：安装设备）；句意为两名工人在生产线重启前把泵装到它的底座上。图中可辨识物件：泵、底座、地脚螺栓、进出水管、水平仪。","pos":[{"tag":"v.","zh":"安装；装设；使就职；安顿"}],"collocations":[{"phrase":"install equipment","zh":"安装设备"},{"phrase":"install software","zh":"安装软件"},{"phrase":"install a system","zh":"安装系统"},{"phrase":"install a new director","zh":"任命新主任"},{"phrase":"install piping","zh":"铺设管道"},{"phrase":"install oneself","zh":"安顿下来；就座"}],"forms":[{"label":"动词原形","form":"install"},{"label":"第三人称单数","form":"installs"},{"label":"过去式","form":"installed"},{"label":"过去分词","form":"installed"},{"label":"现在分词","form":"installing"},{"label":"名词","form":"installation"}],"derivatives":[{"word":"installation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「安装；装置」"},{"word":"installer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「安装者；安装程序」"},{"word":"installed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已安装的」"},{"word":"reinstall","pos":"v.","zh":"由表示「重新」的前缀加该动词构成，义为「重新安装」"},{"word":"installment","pos":"n.","zh":"由该动词的另一名词尾构成，义为「分期的一期」，与安装义分属不同用法"}],"senses":[{"no":"01","title":"To place equipment","titleCN":"把设备装到位","definition":"to put a machine or piece of equipment in its position and connect it for use","definitionCN":"把机器或设备放到位置上，并接好使其可用","example":"They will install the compressor next to the tank.","exampleCN":"他们会把压缩机装在储罐旁边。","why":"The oldest sense was seating a person, and a machine is seated on a base in exactly the same way.","whyCN":"最古老的意思是给人安排座位，而机器是以完全相同的方式被安置在底座上。"},{"no":"02","title":"To load software","titleCN":"安装软件","definition":"to copy a program onto a device and prepare it to run","definitionCN":"把程序复制到设备上并准备运行","example":"Please install the driver before you plug in the printer.","exampleCN":"请先安装驱动程序，再插上打印机。","why":"A program is placed into a machine and given a seat in memory, so the same verb serves.","whyCN":"程序被放进机器并在内存里得到一个座位，因此沿用了同一个动词。"},{"no":"03","title":"To appoint formally","titleCN":"使正式就职","definition":"to place someone formally in an office or position, often with a ceremony","definitionCN":"正式把某人安放到某个职位上，常伴以仪式","example":"The board installed her as chief engineer.","exampleCN":"董事会任命她为总工程师。","why":"This is the original sense: a person is installed into the seat that the office provides.","whyCN":"这是本义：人被安置到职位所提供的那个座位上。"},{"no":"04","title":"To settle oneself","titleCN":"安顿或就座","definition":"to place oneself comfortably in a seat, room or new home","definitionCN":"把自己舒服地安置在座位、房间或新居中","example":"She installed herself by the window and waited.","exampleCN":"她在窗边坐下，然后等着。","why":"The reflexive use keeps the physical seat that the political sense had already generalized.","whyCN":"反身用法保留了那个实体座位，而政治义早已把它抽象化了。"},{"no":"05","title":"To lay pipes or cables","titleCN":"铺设管线","definition":"to fit wiring, piping or ductwork permanently into a building or site","definitionCN":"把线路、管道或风管永久装入建筑或场地","example":"Crews install the cooling pipes under the floor.","exampleCN":"施工队把冷却管铺在地板下面。","why":"Services are fixed objects like machines, and the trade says install rather than put.","whyCN":"管线与机器一样是固定物件，行业里说「安装」而不说「放」。"},{"no":"06","title":"To fix a part in place","titleCN":"把部件固定到位","definition":"to fit a component into a machine and secure it so that it stays aligned","definitionCN":"把部件装进机器并固定住，使其保持对中","example":"Install the bearing before you tension the belt.","exampleCN":"先装好轴承，再张紧皮带。","why":"Fitting a part is the smallest unit of the larger act, and the verb covers both scales.","whyCN":"装一个部件是更大动作的最小单位，这个动词兼指两个尺度。"},{"no":"07","title":"To establish an idea","titleCN":"使观念扎根","definition":"to place an idea, habit or value firmly in a person or group","definitionCN":"把观念、习惯或价值牢固地放进一个人或群体心里","example":"The training aims to install a habit of checking twice.","exampleCN":"这项培训旨在养成复核两遍的习惯。","why":"A mind is treated as a room with seats, and an idea is installed in one of them.","whyCN":"心智被当作一个有座位的房间，观念被安置进其中一个。"},{"no":"08","title":"To load a device with something","titleCN":"把东西装进装置","definition":"to put a required item into a machine or holder so that it is ready","definitionCN":"把所需物件放进机器或容器中备用","example":"Install a fresh filter before the test run.","exampleCN":"试运行前装上一只新滤芯。","why":"The container sense of the seat word survives: something is put into a prepared slot.","whyCN":"「座位」的容器义残留下来：某物被放进预备好的槽位。"}],"etymology":{"intro":{"en":"Install comes from Medieval Latin installare, to place in a seat, from in, in, and stallum, a stall or seat of Germanic origin; English took it through French installer.","cn":"这个词来自中世纪拉丁语 installare「安置在座位上」，由 in「在内」与源自日耳曼语的 stallum「座位」构成；英语经法语 installer 引入。"},"items":[{"era":"LATIN IN-","en":"The prefix meant in or into, and it fixes the direction of the action toward a prepared place.","cn":"这个前缀意为「在内、进入」，把动作方向固定为进入一个预备好的位置。"},{"era":"LATIN STALLUM","en":"Stallum meant a stall or seat and came into Latin from Germanic, so its deeper origin is not Latin.","cn":"这个词指摊位或座位，由日耳曼语进入拉丁语，因此其更深来源并非拉丁语。"},{"era":"MEDIEVAL LATIN INSTALLARE","en":"The verb named the seating of a cleric or officer, and the ceremony gave the word its formal weight.","cn":"这个动词指把教士或官员安置就座，仪式赋予了它正式的分量。"},{"era":"FRENCH INSTALLER","en":"French carried both the verb and the noun to English, where appointment remained the leading sense for centuries.","cn":"法语把动词与名词一并带入英语，就职义在数百年间一直居主导。"},{"era":"MACHINES AND SERVICES","en":"Industrial English extended the verb to machinery, pipes and wiring; the first attestation date of that extension is uncertain and falls within the industrial era.","cn":"工业时代的英语把这个动词扩展到机械、管道与线路；这一扩展的首见年代不确定，只知发生在工业时代。"},{"era":"SOFTWARE","en":"Computing gave the verb its largest modern use, where a program is placed into a machine and made ready.","cn":"计算机领域赋予这个动词今日最大的用量，程序被放进机器并准备运行。"}]},"similar":{"note":{"en":"The first group looks or sounds like install; the second group names neighbouring ideas of placing and fitting.","cn":"第一组在形音上与「install」相近；第二组是与「安放、装配」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"installation","ipa":"/ˌɪnstəˈleɪʃn/","tag":"same root","definition":"The noun for the act and for the equipment that results.","definitionCN":"指安装动作及由此产生的设备。"},{"word":"installer","ipa":"/ɪnˈstɔːlə/","tag":"same root","definition":"A person who fits equipment, or a setup program.","definitionCN":"指安装设备的人，也指安装程序。"},{"word":"instalment","ipa":"/ɪnˈstɔːlmənt/","tag":"different root","definition":"One part of a payment or a serial; it looks close but comes from a different settlement word.","definitionCN":"指分期付款的一期或连载的一段；形近但来自另一个表示「结算」的词。"},{"word":"stall","ipa":"/stɔːl/","tag":"same root","definition":"A stand or seat, the physical noun behind the verb.","definitionCN":"指摊位或座位，是这个动词背后的实体名词。"},{"word":"instead","ipa":"/ɪnˈsted/","tag":"different root","definition":"In place of another; it shares the opening but has no seat in it.","definitionCN":"指代替另一者；开头相同，但里面没有「座位」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fit","ipa":"/fɪt/","tag":"near meaning","definition":"To place a part into its position and adjust it until it works.","definitionCN":"指把部件放到位置并调整到可用。"},{"word":"set up","ipa":"/ˌset ˈʌp/","tag":"near meaning","definition":"To arrange equipment and make it ready for operation.","definitionCN":"指把设备安排好并使其可运行。"},{"word":"mount","ipa":"/maʊnt/","tag":"near meaning","definition":"To fix a component onto a support or surface.","definitionCN":"指把部件固定到支架或表面上。"},{"word":"appoint","ipa":"/əˈpɔɪnt/","tag":"near meaning","definition":"To choose and formally place someone in a position.","definitionCN":"指选定并正式把某人放到职位上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real seat inside the verb, its real family and real trade phrases.","cn":"正常联想使用这个动词里真实的「座位」、真实同族词与真实行业搭配。"},"normal":[{"en":"Install hides stall, a seat, so the verb means to give something a seat.","cn":"install 里藏着 stall「座位」，所以这个动词意为给某物一个座位。"},{"en":"Install a director and install a pump use the same seating picture.","cn":"任命主任与安装水泵用的是同一个「就座」画面。"},{"en":"Installation, installer and reinstall extend the verb in three directions.","cn":"安装、安装者与重装把动词向三个方向延伸。"},{"en":"Install software is the modern phrase that most learners meet first.","cn":"安装软件是学习者最先遇到的现代说法。"},{"en":"Install piping and install equipment are contract language on any site.","cn":"铺设管道与安装设备是任何工地的合同语言。"}],"abstract":[{"en":"To install is to make a thing stop being portable.","cn":"安装就是让一件东西不再便携。"},{"en":"An idea can be installed because the mind is treated as a room with seats.","cn":"观念可以被安装，因为心智被当作一个有座位的房间。"},{"en":"Every installation is a promise that the thing will stay where it was put.","cn":"每一次安装都是一个承诺：这东西会留在被放下的地方。"}]},"examples":[{"en":"The crew will install the new pump during the night shift.","cn":"班组会在夜班期间安装新泵。"},{"en":"You must install the update before the system will start.","cn":"必须先安装更新，系统才会启动。"},{"en":"The company installed him as head of safety last month.","cn":"公司上月任命他为安全负责人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因斯托」——把机器「因」地放进它的座位并托稳：安装、任命","word":"install"},"root":"中世纪拉丁语 installare「安置在座位上」← in-「在内」+ stallum「座位」（日耳曼语来源），经法语 installer 进入英语。本义为教士或官员就职，工业时代扩展为设备与管线安装，计算机时代又指软件安装；扩展年代的确切分界来源不确定。","sensesIntro":{"en":"Eight senses all give something a seat: a machine, a program, a person in office, oneself, pipes, a component, an idea, and an item dropped into a slot.","cn":"八个义项都在给某物一个座位：机器、程序、任职的人、自己、管线、部件、观念，以及放进槽位的物件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pump is lowered onto its base and bolted down until it cannot move.","cn":"核心意象：泵被放到它的底座上，拧紧到不能再移动。"},"chain":["A SEAT","A THING LOWERED","ALIGNED","BOLTED","CONNECTED","RUNNING"],"branches":[{"senses":"01 · 06","en":"THE MACHINE SEATED: a unit placed and a component fixed inside it.","cn":"机器就座：整机就位，以及部件固定在机内。"},{"senses":"02","en":"THE PROGRAM SEATED: software copied in and given memory to run.","cn":"程序就座：软件被复制进来并得到运行所需的内存。"},{"senses":"03 · 04","en":"THE PERSON SEATED: an officer placed by ceremony, and a body settling into a chair.","cn":"人就座：官员经仪式就职，以及身体安顿到椅子里。"},{"senses":"05","en":"THE SERVICES SEATED: pipes and cables fixed permanently into the building.","cn":"管线就座：管道与电缆被永久固定进建筑。"},{"senses":"07 · 08","en":"THE INVISIBLE SEATING: a habit placed in a mind, and a filter placed in a housing.","cn":"看不见的就座：习惯被放进心里，滤芯被放进壳里。"}]},"affixes":{"intro":{"en":"Install is a Latin-derived verb with a Germanic-origin noun inside it and a living English family around it.","cn":"这是一个拉丁来源的动词，内部含一个日耳曼来源的名词，周围是一族活跃的英语派生词。"},"latinIntro":{"en":"Latin in and stallum form the verb; stallum itself is Germanic in origin, so it is not a native Latin root.","cn":"拉丁语的 in 与 stallum 构成这个动词；stallum 本身源自日耳曼语，并非拉丁语本族词根。"},"items":[{"word":"in-","structure":"Latin prefix","meaning":"in, into","meaningCN":"在内；进入","example":"The prefix marks the movement into place.","exampleCN":"这个前缀标出进入位置的动作。"},{"word":"stallum","structure":"Medieval Latin noun of Germanic origin","meaning":"stall, seat","meaningCN":"摊位；座位","example":"The hidden noun supplies the seat.","exampleCN":"隐藏的名词提供了座位。"},{"word":"installare","structure":"in- plus stallum","meaning":"to place in a seat","meaningCN":"安置在座位上","example":"The Latin verb is the direct source.","exampleCN":"这个拉丁动词是直接来源。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result of placing","meaningCN":"安置的动作或结果","example":"The ending builds the noun installation.","exampleCN":"这个词尾构成名词 installation。"},{"word":"-er","structure":"agent noun ending","meaning":"the one who places","meaningCN":"执行安置的人或物","example":"An installer does the fitting.","exampleCN":"安装者完成装设。"},{"word":"re-","structure":"Latin prefix","meaning":"again","meaningCN":"再次","example":"The prefix marks a repeated placing.","exampleCN":"这个前缀标出再次安置。"},{"word":"-ed","structure":"completed-state ending","meaning":"already placed","meaningCN":"已经安置好的","example":"The adjective describes the finished state.","exampleCN":"这个形容词描述完成状态。"},{"word":"-ment","structure":"noun ending through French","meaning":"result or means","meaningCN":"结果或手段","example":"It builds a noun of another branch of meaning.","exampleCN":"它构成另一支词义的名词。"},{"word":"stall","structure":"English noun from Germanic","meaning":"a stand or booth","meaningCN":"摊位；货摊","example":"The physical stand survives beside the verb.","exampleCN":"实体摊位与这个动词并存。"}],"latinEntries":[{"word":"stallum","structure":"Medieval Latin noun","meaning":"stall, seat","meaningCN":"摊位；座位"},{"word":"installare","structure":"Medieval Latin verb","meaning":"to place in a seat","meaningCN":"安置在座位上"},{"word":"installatio","structure":"Medieval Latin noun","meaning":"a placing in office","meaningCN":"就职安置"}],"derivatives":[{"word":"installation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「安装；装置」"},{"word":"installer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「安装者；安装程序」"},{"word":"reinstall","pos":"v.","zh":"由表示「重新」的前缀加该动词构成，义为「重新安装」"},{"word":"installed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已安装的」"},{"word":"installment","pos":"n.","zh":"由该动词的另一名词尾构成，义为「分期的一期」，与安装义分属不同用法"}]}},{"word":"repair","ipa_uk":"/rɪˈpeə/","ipa_us":"/rɪˈper/","definition_zh":"修理；修补；修复；弥补；维修工作","definition_en":"to mend something broken or damaged so that it works again, or to put right a loss or a relationship","core_image":"断了的链条被接回原位，师傅转动曲柄，链节咬住齿轮，轮子重新转起来","scene":"自行车链子掉了，师傅把链节接回、调好松紧，试骑一圈不再打滑。A skilled hand can repair the chain in ten minutes.","sceneCN":"这里指把损坏的物件修回可用状态（第 1 个义项：修理破损物件）；句意为熟练的手十分钟就能把链条修好。图中可辨识物件：链条、链节、齿轮、曲柄、扳手。","pos":[{"tag":"v.","zh":"修理；修复；弥补"},{"tag":"n.","zh":"修理；维修工作；修补处"}],"collocations":[{"phrase":"repair a machine","zh":"修理机器"},{"phrase":"repair the damage","zh":"弥补损失；修复损害"},{"phrase":"repair relations","zh":"修复关系"},{"phrase":"under repair","zh":"正在维修中"},{"phrase":"repair shop","zh":"修理店"},{"phrase":"beyond repair","zh":"无法修复"}],"forms":[{"label":"动词原形","form":"repair"},{"label":"第三人称单数","form":"repairs"},{"label":"过去式","form":"repaired"},{"label":"过去分词","form":"repaired"},{"label":"现在分词","form":"repairing"},{"label":"名词复数","form":"repairs"}],"derivatives":[{"word":"repairer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「修理者」"},{"word":"repairable","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可修理的」"},{"word":"reparation","pos":"n.","zh":"由同一拉丁词干加表示动作结果的名词尾构成，义为「赔偿；补偿」"},{"word":"irreparable","pos":"adj.","zh":"由表示否定的前缀加表示「可修复的」形容词构成，义为「无法修复的」"},{"word":"repairman","pos":"n.","zh":"由该名词加表示人的成分构成，义为「修理工」"}],"senses":[{"no":"01","title":"To mend a broken object","titleCN":"修理破损物件","definition":"to restore a damaged machine or article to working order by replacing or fixing its parts","definitionCN":"通过更换或修复部件，使损坏的机器或物品恢复可用状态","example":"He can repair the pump without removing the casing.","exampleCN":"他不用拆下外壳就能修好这台泵。","why":"The Latin source meant to make ready again, and the everyday sense stays close to that: put the thing back in order.","whyCN":"拉丁语来源意为「重新准备好」，日常义离此不远：把东西恢复整齐。"},{"no":"02","title":"To restore a structure","titleCN":"修复建筑或结构","definition":"to make a building, road or bridge sound again after wear or damage","definitionCN":"在磨损或损坏之后，使建筑、道路或桥梁重新坚固可用","example":"Crews repair the bridge deck every summer.","exampleCN":"施工队每年夏天修复桥面。","why":"Large structures fail in small places, so repair is usually local work with a wide consequence.","whyCN":"大型结构总在小地方失效，因此修复常是局部作业、影响却很广。"},{"no":"03","title":"To mend a relationship","titleCN":"修复关系","definition":"to restore trust or goodwill between people or groups after a quarrel","definitionCN":"在争执之后恢复人与人、群体与群体之间的信任或善意","example":"The two departments tried to repair their working ties.","exampleCN":"两个部门试图修复工作上的联系。","why":"A relationship is imagined as a structure with cracks, and the same verb is used to fill them.","whyCN":"关系被想象成有裂缝的结构，同一个动词被用来填补裂缝。"},{"no":"04","title":"To make up for damage","titleCN":"弥补损失或过错","definition":"to do something that balances or corrects the harm one has caused","definitionCN":"做出足以抵消或纠正自己造成的损害的事","example":"The firm agreed to repair the loss with a refund.","exampleCN":"公司同意用退款来弥补损失。","why":"The word widened from objects to accounts: what was broken is made whole again.","whyCN":"这个词从物件扩展到账目：被弄坏的东西重新变得完整。"},{"no":"05","title":"To heal living tissue","titleCN":"修复活体组织","definition":"to restore damaged cells or tissue to a healthy state","definitionCN":"使受损的细胞或组织恢复到健康状态","example":"The body repairs the tissue around the joint.","exampleCN":"身体会修复关节周围的组织。","why":"Biology borrowed the mechanic's word for a process that also puts broken parts back together.","whyCN":"生物学借用了机械工的词，用来指同样把破损部分拼回去的过程。"},{"no":"06","title":"The work of mending","titleCN":"维修工作","definition":"the activity or job of fixing things, often as a trade or a scheduled task","definitionCN":"修理东西的活动或工作，常指一门行业或一项计划内任务","example":"The repair took longer than the replacement.","exampleCN":"这次维修比换新还费时。","why":"English nouns readily name an activity, and the verb's work became a countable job.","whyCN":"英语名词很自然地指活动，这个动词的活计于是成了可数的工作。"},{"no":"07","title":"A mended place","titleCN":"修补处","definition":"a patch or mended spot on an object, showing where the damage was","definitionCN":"物件上被补过的地方，看得出原来损坏的位置","example":"You can see the repair on the inner tube.","exampleCN":"你能看到内胎上的补丁。","why":"The result of mending is visible, and the noun names that visible spot rather than the act.","whyCN":"修补的结果看得见，这个名词指那处看得见的痕迹，而不是动作。"},{"no":"08","title":"To fix data or code","titleCN":"修复数据或程序","definition":"to correct damaged files, records or software so that they function again","definitionCN":"纠正受损的文件、记录或软件，使其重新正常工作","example":"A tool can repair the corrupted index file.","exampleCN":"有个工具能修复损坏的索引文件。","why":"Digital damage looks like physical damage, and the old verb moved into the new workshop.","whyCN":"数字损坏看起来像实体损坏，这个老动词便搬进了新作坊。"}],"etymology":{"intro":{"en":"Repair comes from Old French reparer and Latin reparare, to restore, from re, again, and parare, to prepare or make ready. A separate English phrase, repair to a place, comes from a different Latin word and is not related.","cn":"这个词来自古法语 reparer 与拉丁语 reparare「恢复」，由 re「再次」与 parare「准备、使就绪」构成。英语里另有「前往某处」的 repair to，来自另一个拉丁词，与此无关。"},"items":[{"era":"LATIN PARARE","en":"Parare meant to prepare, provide or make ready, and it is the stem that carries the idea of putting something in order.","cn":"这个词意为准备、提供、使就绪，是承载「把东西弄整齐」这一意思的词干。"},{"era":"LATIN RE-","en":"The prefix meant again or back, so reparare was to make ready once more what had fallen out of order.","cn":"这个前缀意为「再次、回到」，因此 reparare 是把失序之物重新准备好。"},{"era":"LATIN REPARARE","en":"The verb covered restoring buildings, health and fortunes, and its range was wider than a single broken object.","cn":"这个动词涵盖修复建筑、健康与境况，范围比单件破损物品更宽。"},{"era":"OLD FRENCH REPARER","en":"French kept the verb and passed it to English, where it first meant to restore something to sound condition.","cn":"法语保留了这个动词并传给英语，英语最初指使某物恢复完好状态。"},{"era":"THE UNRELATED REPAIR TO","en":"The phrase meaning to go to a place comes from Latin repatriare, to return to one's country, and merely looks the same.","cn":"表示「前往某处」的词组来自拉丁语 repatriare「返回祖国」，只是形同而来源不同。"},{"era":"MECHANICAL AND DIGITAL","en":"The industrial trades fixed the noun to maintenance work, and computing later applied it to files; the first attestation date of the digital use is uncertain.","cn":"工业行业把这个名词固定到维修工作上，计算机领域后来又用于文件；数字用法的首见年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like repair; the second group names neighbouring ideas of mending.","cn":"第一组在形音上与「repair」相近；第二组是与「修补」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reparation","ipa":"/ˌrepəˈreɪʃn/","tag":"same root","definition":"Compensation for harm done, or the act of making something whole again.","definitionCN":"指对损害的赔偿，或使某物恢复完整的行动。"},{"word":"repairable","ipa":"/rɪˈpeərəbl/","tag":"same root","definition":"Able to be mended rather than thrown away.","definitionCN":"指可以修好而不必丢弃的。"},{"word":"repairer","ipa":"/rɪˈpeərə/","tag":"same root","definition":"A person whose work is mending things.","definitionCN":"指以修理东西为业的人。"},{"word":"repair to","ipa":"/rɪˈpeə tə/","tag":"different root","definition":"To go to a place, especially in a group; the phrase comes from a different Latin word.","definitionCN":"指前往某处，尤指成群前往；该词组来自另一个拉丁词。"},{"word":"prepare","ipa":"/prɪˈpeə/","tag":"same root","definition":"To make ready in advance; it shares the Latin stem but has no sense of mending.","definitionCN":"指提前准备好；共享拉丁词干，但没有修补义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mend","ipa":"/mend/","tag":"near meaning","definition":"To fix something torn or broken, often by sewing or patching.","definitionCN":"指修补撕裂或破损之物，常指缝补。"},{"word":"fix","ipa":"/fɪks/","tag":"near meaning","definition":"To make a faulty thing work again.","definitionCN":"指使出故障的东西重新工作。"},{"word":"restore","ipa":"/rɪˈstɔː/","tag":"near meaning","definition":"To bring something back to an earlier good condition.","definitionCN":"指使某物回到早先的良好状态。"},{"word":"maintenance","ipa":"/ˈmeɪntənəns/","tag":"near meaning","definition":"Regular work done to keep equipment in good order, rather than fixing a failure.","definitionCN":"指为保持设备良好而做的例行工作，而非修复故障。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real re-plus-ready source, the real trade family and real fixed phrases.","cn":"正常联想使用真实的「再次准备好」来源、真实行业同族词与真实固定搭配。"},"normal":[{"en":"Repair is re plus ready: make the thing ready again.","cn":"repair 就是「再次」加「准备好」：把东西重新弄好。"},{"en":"Repair a machine, repair relations and repair the damage are the three ranges of the verb.","cn":"修理机器、修复关系、弥补损失是这个动词的三个范围。"},{"en":"Under repair and beyond repair are the two fixed states on a site notice.","cn":"维修中与无法修复是工地告示上的两种固定状态。"},{"en":"Repairable, repairer and repairman are the everyday family.","cn":"可修复的、修理者与修理工是日常同族词。"},{"en":"Repair to a place looks the same but comes from a different Latin word.","cn":"前往某处的 repair to 形同，但来自另一个拉丁词。"}],"abstract":[{"en":"Repair does not undo the break; it makes the break stop mattering.","cn":"修理并不撤销那次断裂，而是让那道断裂不再要紧。"},{"en":"A repaired joint is a small admission that things can be made whole again.","cn":"一处修补过的接头，是对「东西还能重新完整」的小小承认。"},{"en":"To repair a relationship you must first admit where the crack is.","cn":"要修复一段关系，先得承认裂缝在哪里。"}]},"examples":[{"en":"The workshop can repair the gearbox in one shift.","cn":"这个车间一个班次就能修好减速箱。"},{"en":"Nothing could repair the damage done to the samples.","cn":"没有什么能弥补这些样本所受的损害。"},{"en":"Both sides met to repair the trust between them.","cn":"双方会面，修复彼此之间的信任。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑞佩尔」——把坏掉的东西「瑞」地重新配对、配回原位：修理","word":"repair"},"root":"古法语 reparer ← 拉丁语 reparare「恢复」← re-「再次」+ parare「准备、使就绪」。parare 是表示「预备」的真实词干；另有一个同形词组 repair to「前往」，来自拉丁语 repatriare「返回祖国」，两者不同源。工业时代固定为维修义，数字时代扩展为文件修复，确切年代来源不确定。","sensesIntro":{"en":"Eight senses all make something whole again: an object, a structure, a relationship, a loss, living tissue, a job of mending, a visible patch, and a corrupted file.","cn":"八个义项都在使某物重新完整：物件、结构、关系、损失、活体组织、维修工作、可见补丁与损坏的文件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a broken link is joined again and the wheel turns without a jump.","cn":"核心意象：断开的链节被重新接上，轮子转起来不再跳动。"},"chain":["BROKEN PART","FIND THE FAULT","REPLACE OR JOIN","TEST","WORKING AGAIN","TRUST RESTORED"],"branches":[{"senses":"01","en":"THE OBJECT MENDED: a machine restored to working order.","cn":"物件修好：机器恢复到可用状态。"},{"senses":"02 · 07","en":"THE STRUCTURE AND THE PATCH: a bridge made sound, and the visible spot where it was mended.","cn":"结构与补丁：桥梁恢复坚固，以及修补后看得见的痕迹。"},{"senses":"03","en":"THE RELATIONSHIP MENDED: trust rebuilt after a quarrel.","cn":"关系修复：争执之后重建信任。"},{"senses":"04 · 06","en":"THE ACCOUNT MADE WHOLE: damage paid back, and the trade of mending itself.","cn":"账目补全：损害得到补偿，以及修理这门行业本身。"},{"senses":"05 · 08","en":"THE LIVING AND THE DIGITAL: tissue healed, and a corrupted file made readable.","cn":"活体与数字：组织愈合，以及损坏文件恢复可读。"}]},"affixes":{"intro":{"en":"Repair is built from a Latin prefix and a Latin ready-making verb; its English descendants run from repairer to irreparable.","cn":"这个词由拉丁语前缀与表示「使就绪」的动词构成；英语派生词从修理者一直到无法修复的。"},"latinIntro":{"en":"Latin re- and parare are both real sources, and reparare is the compound that English borrowed through French.","cn":"拉丁语的 re- 与 parare 都是真实来源，reparare 则是英语经法语借入的复合动词。"},"items":[{"word":"re-","structure":"Latin prefix","meaning":"again, back","meaningCN":"再次；回到","example":"The prefix says the making ready happens a second time.","exampleCN":"这个前缀说明「使就绪」是第二次发生。"},{"word":"parare","structure":"Latin verb","meaning":"to prepare, make ready","meaningCN":"准备；使就绪","example":"The stem carries the idea of order.","exampleCN":"这个词干承载「秩序」的意思。"},{"word":"reparare","structure":"re- plus parare","meaning":"to restore, renew","meaningCN":"恢复；更新","example":"The Latin compound is the direct source.","exampleCN":"这个拉丁复合词是直接来源。"},{"word":"-er","structure":"agent noun ending","meaning":"the one who mends","meaningCN":"进行修补的人","example":"The ending builds the name of the worker.","exampleCN":"这个词尾构成工种的名称。"},{"word":"-able","structure":"adjective ending","meaning":"can be done","meaningCN":"可以被……的","example":"It marks what can still be mended.","exampleCN":"它标出还能修的东西。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result of restoring","meaningCN":"恢复的动作或结果","example":"It builds the noun for compensation.","exampleCN":"它构成表示赔偿的名词。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"It marks a damage that cannot be undone.","exampleCN":"它标出无法挽回的损害。"},{"word":"-man","structure":"English compound element","meaning":"person who works with","meaningCN":"从事……的人","example":"It builds the trade name repairman.","exampleCN":"它构成行业名称修理工。"},{"word":"reparatio","structure":"Latin noun from reparare","meaning":"a restoring, a renewal","meaningCN":"恢复；更新","example":"The Latin noun names the act of making whole.","exampleCN":"这个拉丁名词指使完整的行为。"}],"latinEntries":[{"word":"parare","structure":"Latin verb","meaning":"to prepare, make ready","meaningCN":"准备；使就绪"},{"word":"reparare","structure":"Latin verb","meaning":"to restore, renew","meaningCN":"恢复；更新"},{"word":"reparatio","structure":"Latin noun","meaning":"a restoring","meaningCN":"恢复"}],"derivatives":[{"word":"repairable","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可修理的」"},{"word":"repairer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「修理者」"},{"word":"reparation","pos":"n.","zh":"由同一拉丁词干加表示动作结果的名词尾构成，义为「赔偿；补偿」"},{"word":"irreparable","pos":"adj.","zh":"由表示否定的前缀加表示「可修复的」形容词构成，义为「无法修复的」"},{"word":"repairman","pos":"n.","zh":"由该名词加表示人的成分构成，义为「修理工」"}]}},{"word":"durable","ipa_uk":"/ˈdjʊərəbl/","ipa_us":"/ˈdʊrəbl/","definition_zh":"耐用的；持久的；耐磨的；稳固的；耐用品","definition_en":"able to withstand wear, pressure or time, and continuing to exist or work for a long period","core_image":"同一双工装靴在碎石上走了三年，鞋底花纹磨浅了，接缝却没有开裂","scene":"一双工装靴在碎石上走了三年，鞋底花纹已经磨浅，接缝仍然没有裂开。These boots are durable enough for a full season on rough ground.","sceneCN":"这里指经得起长期磨损（第 1 个义项：耐用的）；句意为这双靴子足够耐用，能在碎石地上撑过整个季节。图中可辨识物件：工装靴、磨浅的鞋底、完好的接缝、碎石地。","pos":[{"tag":"adj.","zh":"耐用的；持久的；稳固的"},{"tag":"n.","zh":"耐用品（常用复数）"}],"collocations":[{"phrase":"durable goods","zh":"耐用品"},{"phrase":"durable material","zh":"耐用材料"},{"phrase":"durable peace","zh":"持久和平"},{"phrase":"durable solution","zh":"持久方案"},{"phrase":"durable design","zh":"耐用设计"},{"phrase":"long and durable","zh":"长久而持久"}],"forms":[{"label":"原级","form":"durable"},{"label":"比较级","form":"more durable"},{"label":"最高级","form":"most durable"},{"label":"名词（性质）","form":"durability"},{"label":"名词复数（耐用品）","form":"durables"},{"label":"副词","form":"durably"}],"derivatives":[{"word":"durability","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「耐久性；耐用程度」"},{"word":"durably","pos":"adv.","zh":"由该形容词加副词尾构成，义为「持久地；耐久地」"},{"word":"durable goods","pos":"n.","zh":"由该形容词加表示商品的名词构成，义为「耐用品」"},{"word":"endure","pos":"v.","zh":"由同一拉丁词干经法语构成，义为「忍受；持续」"},{"word":"obdurate","pos":"adj.","zh":"由表示「对抗」的前缀加同一拉丁词干构成，义为「顽固的；硬心肠的」"}],"senses":[{"no":"01","title":"Resistant to wear","titleCN":"经得起磨损的","definition":"made or built so that it can be used for a long time without breaking or wearing out","definitionCN":"制作或建造得能够长期使用而不损坏或磨坏","example":"The boots proved durable on rough ground.","exampleCN":"这双靴子在碎石地上证明很耐用。","why":"The Latin stem meant hard, and hardness is the physical promise behind the everyday sense.","whyCN":"拉丁词干意为「硬」，硬度就是日常义背后的物理承诺。"},{"no":"02","title":"Long-lasting in time","titleCN":"在时间上持久的","definition":"continuing to exist or remain effective for a long period","definitionCN":"长期继续存在或保持有效","example":"The agreement produced a durable calm.","exampleCN":"这项协议带来了持久的平静。","why":"Hard objects resist wear, and arrangements are described as if they too could resist time.","whyCN":"坚硬之物抵抗磨损，人们便把安排也说得好像能抵抗时间。"},{"no":"03","title":"Abrasion-resistant material","titleCN":"耐磨材料","definition":"a material able to resist rubbing, scraping or repeated contact","definitionCN":"能够抵抗摩擦、刮擦或反复接触的材料","example":"A durable coating protects the pump impeller.","exampleCN":"一层耐磨涂层保护着泵的叶轮。","why":"In engineering the word narrows to the surface property that decides how long a part lasts.","whyCN":"在工程语境里，这个词收窄到决定零件寿命的表面性质。"},{"no":"04","title":"A memory that stays","titleCN":"留得住的记忆","definition":"an impression or memory that remains clear for a long time","definitionCN":"长久保持清晰的印象或记忆","example":"The visit left a durable impression on the students.","exampleCN":"这次参观给学生留下了持久的印象。","why":"What is hard to erase is called durable, whether it is steel or a memory.","whyCN":"难以抹去的东西都被称为耐用或持久，无论是钢还是记忆。"},{"no":"05","title":"Steady economic growth","titleCN":"稳定的持续增长","definition":"growth or demand that continues without sudden collapse","definitionCN":"没有突然崩塌、持续下去的増长或需求","example":"The sector showed durable demand for parts.","exampleCN":"这个行业对零件的需求表现得稳定持久。","why":"Economists borrow the material word for anything that holds its shape under pressure.","whyCN":"经济学家借用这个材料词，指任何在压力下仍能保持形态的东西。"},{"no":"06","title":"Able to hold up under challenge","titleCN":"经得起考验的","definition":"strong enough to survive criticism, stress or repeated testing","definitionCN":"强健到能经受批评、压力或反复检验","example":"The design proved durable under heavy use.","exampleCN":"这一设计在重度使用下证明站得住。","why":"The metaphor moves from abrasion to argument: what does not wear through is trusted.","whyCN":"比喻从磨损转到论证：磨不穿的东西才被信任。"},{"no":"07","title":"Goods made to last","titleCN":"耐用品","definition":"manufactured items, such as appliances or furniture, expected to last several years","definitionCN":"预期能用数年的制成品，如家电或家具","example":"Spending on durables rose before the holiday.","exampleCN":"耐用品支出在假期前上升了。","why":"A plural noun grew out of the adjective to name the whole class of long-lasting purchases.","whyCN":"复数名词由形容词长出，用来指整类长久使用的购买品。"},{"no":"08","title":"Strong in body or habit","titleCN":"身体或习性强健的","definition":"able to endure hardship, work or illness without giving way","definitionCN":"能承受艰苦、劳作或疾病而不垮掉","example":"The plant is durable enough for dry ground.","exampleCN":"这种植物足够强健，能耐旱地。","why":"Living things are judged by the same standard as tools: they must keep working under load.","whyCN":"生物与工具按同一标准衡量：在负荷下还得继续工作。"}],"etymology":{"intro":{"en":"Durable comes through Old French from Latin durabilis, lasting, from durare, to last or harden, and durus, hard. The deeper root is reconstructed and is often connected with the word for tree or wood.","cn":"这个词经古法语来自拉丁语 durabilis「持久的」，源自动词 durare「持续、变硬」与形容词 durus「硬的」。更深词根属重构形式，常与表示树木、木材的词联系起来。"},"items":[{"era":"LATIN DURUS","en":"Durus meant hard or tough, and it supplied the physical image of a surface that does not give way.","cn":"这个词意为坚硬、结实，提供了「表面不屈服」的物理画面。"},{"era":"LATIN DURARE","en":"Durare meant to harden or to last, so hardness and duration were one idea from the start.","cn":"这个词意为使变硬或持续，因此「硬」与「久」从一开始就是同一个概念。"},{"era":"LATIN DURABILIS","en":"The adjective meant able to last, and English took it as a description of goods rather than of people.","cn":"这个形容词意为「能持久的」，英语借入后主要用于描述物品而非人。"},{"era":"OLD FRENCH DURABLE","en":"French carried the adjective into English, where it first described materials and constructions.","cn":"法语把这个形容词带入英语，最初用于描述材料与建筑。"},{"era":"RECONSTRUCTED ROOT","en":"The deeper root behind durus is reconstructed as a word for tree or wood, and the connection is generally accepted rather than certain.","cn":"durus 更深的词根被重构为表示树木或木材的词，这一联系一般认为成立，但不是定论。"},{"era":"ECONOMICS","en":"The plural noun for long-lasting goods took shape in the twentieth century, when household appliances became a separate market; the exact date is uncertain and can only be placed around the middle of that century.","cn":"表示耐用品的复数名词在二十世纪成形，当时家用电器成了独立市场；确切年代不确定，只能定在二十世纪中叶前后。"}]},"similar":{"note":{"en":"The first group looks or sounds like durable; the second group names neighbouring ideas of lasting strength.","cn":"第一组在形音上与「durable」相近；第二组是与「持久坚固」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"durability","ipa":"/ˌdjʊərəˈbɪləti/","tag":"same root","definition":"The quality of lasting or resisting wear.","definitionCN":"指持久或抗磨损的性质。"},{"word":"durably","ipa":"/ˈdjʊərəbli/","tag":"same root","definition":"In a way that lasts or resists wear.","definitionCN":"指以持久或耐磨的方式。"},{"word":"endure","ipa":"/ɪnˈdjʊə/","tag":"same root","definition":"To bear hardship or continue to exist over time.","definitionCN":"指承受艰苦或随时间继续存在。"},{"word":"obdurate","ipa":"/ˈɒbdjərət/","tag":"same root","definition":"Stubbornly refusing to change; hardness turned into a temper.","definitionCN":"指顽固不化；硬度转成了性情。"},{"word":"dual","ipa":"/ˈdjʊəl/","tag":"different root","definition":"Consisting of two parts; it looks close but belongs to the word for two.","definitionCN":"指由两部分组成的；形近但属于表示「二」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sturdy","ipa":"/ˈstɜːdi/","tag":"near meaning","definition":"Strongly built and unlikely to break under use.","definitionCN":"指造得结实、使用中不易损坏的。"},{"word":"lasting","ipa":"/ˈlɑːstɪŋ/","tag":"near meaning","definition":"Continuing for a long time, especially of effects or agreements.","definitionCN":"指持续时间长，尤指效果或协议。"},{"word":"robust","ipa":"/rəʊˈbʌst/","tag":"near meaning","definition":"Strong and able to withstand rough conditions or hard use.","definitionCN":"指强健、能经受恶劣条件或重度使用的。"},{"word":"hardy","ipa":"/ˈhɑːdi/","tag":"near meaning","definition":"Able to survive difficult conditions, usually of plants or people.","definitionCN":"指能耐受艰苦条件，通常指植物或人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real hard-and-last source, the real family and real commerce phrases.","cn":"正常联想使用真实的「硬与持久」来源、真实同族词与真实商业搭配。"},"normal":[{"en":"The Latin stem meant hard, and what is hard lasts.","cn":"拉丁词干意为硬，而硬的东西能持久。"},{"en":"Durability is the noun, durably the adverb, and durables the goods.","cn":"耐久性是名词，耐久地是副词，耐用品是名词复数。"},{"en":"Durable goods is the standard phrase for appliances and furniture.","cn":"耐用品是家电与家具的标准说法。"},{"en":"Durable peace and durable solution are the political phrases.","cn":"持久和平与持久方案是政治语境的说法。"},{"en":"Endure and obdurate come from the same hard stem, one as a verb and one as a temper.","cn":"忍受与顽固出自同一个「硬」词干，一个是动词，一个是性情。"}],"abstract":[{"en":"Durable is a bet that the future will be rough and the object will still be there.","cn":"耐用是一个赌注：未来会很粗粝，而这件东西还在。"},{"en":"Hardness becomes duration, and duration becomes trust.","cn":"硬度变成时长，时长变成信任。"},{"en":"A durable idea is one that survives being used.","cn":"一个持久的观念，就是经得起被使用的观念。"}]},"examples":[{"en":"The coating makes the blade durable in wet soil.","cn":"这层涂层使刀片在湿土中依然耐用。"},{"en":"They hoped for a durable settlement, not a pause.","cn":"他们想要一个持久的解决方案，而不是暂停。"},{"en":"Demand for durables fell after the subsidy ended.","cn":"补贴结束后，耐用品需求下降。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「丢拉伯」——丢在石头上拉了三年也不坏：耐用的、持久的","word":"durable"},"root":"古法语 durable ← 拉丁语 durabilis「能持久的」← durare「持续、变硬」← durus「硬的」；durus 更深词根被重构为表示树木、木材的词，一般认为成立但非定论。同族还有 endure「忍受」与 obdurate「顽固」。二十世纪形成耐用品这一商业义，确切年代来源不确定。","sensesIntro":{"en":"Eight senses test the same hardness over different lengths of time: boots, agreements, coatings, memories, demand, designs, household goods and plants.","cn":"八个义项在不同时间尺度上检验同一种「硬」：靴子、协议、涂层、记忆、需求、设计、家用商品与植物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a boot sole wears thin but the seam holds after three years of gravel.","cn":"核心意象：靴底磨薄了，接缝却在三年碎石路后依然牢固。"},"chain":["HARD SURFACE","RESISTS RUBBING","KEEPS ITS SHAPE","LASTS YEARS","STILL TRUSTED","OUTLIVES USE"],"branches":[{"senses":"01 · 03","en":"THE HARD GOODS: a boot and a coating that resist wear on the surface.","cn":"硬的物件：靴子与涂层在表面抵抗磨损。"},{"senses":"02 · 04","en":"THE LONG EFFECT: a calm that holds, and an impression that stays clear.","cn":"长久的效果：维持得住的平静，以及保持清晰的印象。"},{"senses":"05","en":"THE STEADY MARKET: demand that does not collapse when support is removed.","cn":"稳定的市场：支持撤走后也不崩塌的需求。"},{"senses":"06 · 08","en":"THE THING UNDER STRAIN: a design that survives hard use and a plant that survives dry ground.","cn":"受力之物：经得住重度使用的设计，以及耐得住旱地的植物。"},{"senses":"07","en":"THE CLASS OF GOODS: appliances and furniture bought for years, not for a season.","cn":"商品类别：按年而不是按季购买的家电与家具。"}]},"affixes":{"intro":{"en":"Durable is a Latin adjective carried by French, with a stem that also builds verbs and nouns about endurance.","cn":"这是一个经法语传入的拉丁形容词，其词干还构成表示「忍受」的动词与名词。"},"latinIntro":{"en":"Latin durus and durare are real sources; the still deeper root is a reconstruction and is labelled as such.","cn":"拉丁语的 durus 与 durare 是真实来源；更深的词根属重构形式，并按重构标注。"},"items":[{"word":"durus","structure":"Latin adjective","meaning":"hard, tough","meaningCN":"硬的；结实的","example":"The adjective supplies the physical hardness.","exampleCN":"这个形容词提供了物理上的硬度。"},{"word":"durare","structure":"Latin verb from durus","meaning":"to harden; to last","meaningCN":"使变硬；持续","example":"The verb joins hardness to duration.","exampleCN":"这个动词把硬度与时长接在一起。"},{"word":"-abilis","structure":"Latin adjective ending","meaning":"able to be","meaningCN":"能够被……的","example":"The ending turns lasting into a capacity.","exampleCN":"这个词尾把「持续」变成一种能力。"},{"word":"durabilis","structure":"durare plus -abilis","meaning":"able to last","meaningCN":"能持久的","example":"The Latin adjective is the direct source.","exampleCN":"这个拉丁形容词是直接来源。"},{"word":"-ity","structure":"quality noun ending","meaning":"the state of being","meaningCN":"……的性质","example":"It builds the noun durability.","exampleCN":"它构成名词耐久性。"},{"word":"-ly","structure":"adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It builds the adverb durably.","exampleCN":"它构成副词耐久地。"},{"word":"en-","structure":"French prefix from Latin in-","meaning":"in, make","meaningCN":"在内；使成为","example":"It builds the verb endure from the same stem.","exampleCN":"它由同一词干构成动词忍受。"},{"word":"ob-","structure":"Latin prefix","meaning":"against","meaningCN":"对抗；逆着","example":"It builds obdurate, hardness turned against persuasion.","exampleCN":"它构成顽固，即硬度转而对抗说服。"},{"word":"*deru-","structure":"reconstructed root","meaning":"tree, wood; firm","meaningCN":"树木；木材；坚固","example":"The form is reconstructed rather than recorded.","exampleCN":"该形式是重构，并非有记录。"}],"latinEntries":[{"word":"durus","structure":"Latin adjective","meaning":"hard, tough","meaningCN":"硬的；结实的"},{"word":"durare","structure":"Latin verb","meaning":"to harden, last","meaningCN":"使变硬；持续"},{"word":"durabilis","structure":"Latin adjective","meaning":"able to last","meaningCN":"能持久的"}],"derivatives":[{"word":"durability","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「耐久性」"},{"word":"durably","pos":"adv.","zh":"由该形容词加副词尾构成，义为「持久地」"},{"word":"endure","pos":"v.","zh":"由同一拉丁词干经法语构成，义为「忍受；持续」"},{"word":"obdurate","pos":"adj.","zh":"由表示「对抗」的前缀加同一拉丁词干构成，义为「顽固的」"},{"word":"durables","pos":"n.","zh":"由该形容词加复数词尾构成，义为「耐用品」"}]}},{"word":"load","ipa_uk":"/ləʊd/","ipa_us":"/loʊd/","definition_zh":"负荷；载荷；载重；负担；装载；加载","definition_en":"the weight or force carried by a structure, vehicle or machine, or to put goods, data or a charge into something","core_image":"吊车把一卷钢带挂上吊钩，仪表指针逼近额定值，司机抬手示意停止起升","scene":"吊车把钢卷挂上吊钩，仪表指针逼近额定值，司机抬手示意停止起升。The crane stopped because the load exceeded its rated limit.","sceneCN":"这里指吊具承受的重量（第 1 个义项：结构或吊具承受的载荷）；句意为吊车停了下来，因为载荷超过了额定限度。图中可辨识物件：吊钩、钢卷、载荷仪表、司机、警戒线。","pos":[{"tag":"n.","zh":"负荷；载荷；载重；负担"},{"tag":"v.","zh":"装载；装填；加载"}],"collocations":[{"phrase":"carry a load","zh":"承受载荷"},{"phrase":"load capacity","zh":"承载能力"},{"phrase":"heavy load","zh":"重载"},{"phrase":"load a truck","zh":"装车"},{"phrase":"load the data","zh":"加载数据"},{"phrase":"workload","zh":"工作量"}],"forms":[{"label":"单数","form":"load"},{"label":"复数","form":"loads"},{"label":"第三人称单数","form":"loads"},{"label":"过去式","form":"loaded"},{"label":"过去分词","form":"loaded"},{"label":"现在分词","form":"loading"}],"derivatives":[{"word":"loader","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「装料机；装载者」"},{"word":"loaded","pos":"adj.","zh":"由该动词加已然词尾构成，义为「载重的；有负载的」"},{"word":"loading","pos":"n.","zh":"由该动词加表示进行的名词尾构成，义为「装载；加载」"},{"word":"overload","pos":"v./n.","zh":"由表示「超过」的前缀加该词构成，义为「超载」"},{"word":"unload","pos":"v.","zh":"由表示「取消」的前缀加该动词构成，义为「卸载」"}],"senses":[{"no":"01","title":"The weight a structure carries","titleCN":"结构承受的载荷","definition":"the force or weight that a structure, lifting device or machine has to bear","definitionCN":"结构、吊具或机器必须承受的力或重量","example":"The beam is designed for a load of ten tonnes.","exampleCN":"这根梁按十吨载荷设计。","why":"The word began as a way or a carrying, and engineering fixed it to the weight being carried.","whyCN":"这个词最初指「路途、承载」，工程语境把它固定到被承载的重量上。"},{"no":"02","title":"The capacity of a vehicle","titleCN":"车辆或船舶的载重","definition":"the amount of goods or weight that a vehicle or vessel is able to carry","definitionCN":"车辆或船舶能够装载的货物量或重量","example":"The truck took a full load of gravel.","exampleCN":"卡车装了一整载碎石。","why":"A carrying word naturally measures how much can be carried at once.","whyCN":"表示「承载」的词自然用来度量一次能带多少。"},{"no":"03","title":"The weight of work","titleCN":"工作量或负担","definition":"the amount of work or responsibility a person or system must deal with","definitionCN":"一个人或系统必须处理的工作量或责任","example":"The new clerk cut the load on the front desk.","exampleCN":"新来的职员减轻了前台的负担。","why":"Work is imagined as goods to be carried, and an extra person shares the load.","whyCN":"工作被想象成要搬运的货物，多一个人就分担了荷载。"},{"no":"04","title":"The demand on a circuit","titleCN":"电路的电负载","definition":"the power or current drawn by a device or system from a supply","definitionCN":"设备或系统从电源取用的功率或电流","example":"The generator tripped when the load doubled.","exampleCN":"负载翻倍时发电机跳闸了。","why":"Electrical demand behaves like a weight on a supply, and the old word fitted without change.","whyCN":"用电需求像压在电源上的重量，老词原样就用上了。"},{"no":"05","title":"To put goods on board","titleCN":"把货物装上","definition":"to put goods, fuel or material onto a vehicle or into a container","definitionCN":"把货物、燃料或材料放上车船或容器","example":"They load the pallets before sunrise.","exampleCN":"他们在日出前把托盘装好。","why":"The noun of a burden turned into the verb of placing it, a common British pairing.","whyCN":"「负担」的名词转成「放置负担」的动词，这是英语里常见的名词动化。"},{"no":"06","title":"To charge a weapon or device","titleCN":"给武器或装置装填","definition":"to put a charge, film or medium into a weapon, camera or appliance","definitionCN":"把弹药、胶片或介质装入武器、相机或器具","example":"He loaded the camera with a fresh roll.","exampleCN":"他给相机装上一卷新胶卷。","why":"A device also carries something and needs to be filled before it works.","whyCN":"装置同样要承载东西，用之前必须先填满。"},{"no":"07","title":"To bring data into memory","titleCN":"把数据加载进内存","definition":"to transfer a file or program into a computer's memory so that it can be used","definitionCN":"把文件或程序传入计算机内存以便使用","example":"The program will load the map on startup.","exampleCN":"程序启动时会加载这张地图。","why":"Computing reused the idea of putting something into a carrier before it can act.","whyCN":"计算机沿用「先装进载体才能运作」这个思路。"},{"no":"08","title":"An emotional burden","titleCN":"心理上的负担","definition":"a weight of worry or responsibility that a person feels","definitionCN":"一个人感受到的忧虑或责任之重","example":"She carried a heavy load after the accident.","exampleCN":"事故之后她背负着沉重的心理负担。","why":"The body carries weight and the mind borrows the same measure.","whyCN":"身体承担重量，心智借用了同一套度量。"},{"no":"09","title":"The demand on an engine","titleCN":"发动机的运转负荷","definition":"the amount of power an engine or motor must produce at a given moment","definitionCN":"发动机或电动机在某一时刻必须输出的功率","example":"At full load the engine runs at its hottest.","exampleCN":"满负荷时发动机温度最高。","why":"Every machine has a working demand, and engineers call that demand its load.","whyCN":"每台机器都有运转需求，工程师把这个需求称作它的负荷。"}],"etymology":{"intro":{"en":"Load goes back to Old English lad, a way or a course, from the reconstructed Proto-Germanic laidō, to go forth. The sense of something carried appeared in Middle English, and the verb followed.","cn":"这个词可追到古英语 lad「路途、进程」，来自原始日耳曼语的重构形式 laidō「向前走」。表示「被承载之物」的意思在中古英语出现，动词随后产生。"},"items":[{"era":"OLD ENGLISH LAD","en":"Lad meant a way, a course or a journey, and the earliest sense was about travelling rather than weight.","cn":"这个词意为路途、进程或旅程，最早的意思与行走有关，而非重量。"},{"era":"GERMANIC LAIDO","en":"The Proto-Germanic noun meant a way or a leading, and related forms in other Germanic languages also mean a road or a track.","cn":"原始日耳曼语名词意为路途或引导，其他日耳曼语中的相关形式也指道路或轨迹。"},{"era":"MIDDLE ENGLISH","en":"By the thirteenth century the word also named what a person or animal carried, and the meaning moved from route to burden; how that shift came about is source uncertain, and one hypothesis links it to a related verb meaning to lead.","cn":"到十三世纪，这个词也指人或牲畜背负的东西，意思从路线转向负担；这一语义转变的来源不确定，另有假说认为它受表示「引导、带领」的同族动词影响。"},{"era":"THE VERB","en":"The verb to put a load on appeared in the fourteenth century, and to load a gun or camera followed later.","cn":"表示「给……装货」的动词在十四世纪出现，给枪炮或相机装填的用法随后产生。"},{"era":"ENGINEERING","en":"Structural and mechanical engineering gave the noun its precise force sense, and its first attestation date is uncertain.","cn":"结构与机械工程赋予这个名词精确的力学含义，首见年代不确定。"},{"era":"ELECTRICAL AND DIGITAL","en":"The nineteenth century applied the word to circuits, and the twentieth to data and programs.","cn":"十九世纪把它用于电路，二十世纪又用于数据与程序。"}]},"similar":{"note":{"en":"The first group looks or sounds like load; the second group names neighbouring ideas of weight and filling.","cn":"第一组在形音上与「load」相近；第二组是与「重量、装载」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"loader","ipa":"/ˈləʊdə/","tag":"same root","definition":"A machine or person that loads material, or a program that loads files.","definitionCN":"指装料的机器或人，也指加载文件的程序。"},{"word":"loaded","ipa":"/ˈləʊdɪd/","tag":"same root","definition":"Carrying a load, or charged with something.","definitionCN":"指载着负荷的，或装填了东西的。"},{"word":"overload","ipa":"/ˌəʊvəˈləʊd/","tag":"same root","definition":"To put more weight or demand on something than it can bear.","definitionCN":"指给某物加上超过其承受能力的重量或需求。"},{"word":"unload","ipa":"/ˌʌnˈləʊd/","tag":"same root","definition":"To take goods off a vehicle or remove a burden.","definitionCN":"指把货物从车上卸下或卸去负担。"},{"word":"lode","ipa":"/ləʊd/","tag":"different root","definition":"A vein of ore; it sounds identical but comes from a word for a way or a lead.","definitionCN":"指矿脉；发音相同，但来自表示「路径、引导」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"burden","ipa":"/ˈbɜːdn/","tag":"near meaning","definition":"A heavy load, especially one that is hard to carry or bear.","definitionCN":"指沉重的负荷，尤指难以承担的重负。"},{"word":"weight","ipa":"/weɪt/","tag":"near meaning","definition":"The heaviness of an object, or a mass placed on something.","definitionCN":"指物体的重量，或放在某物上的质量。"},{"word":"cargo","ipa":"/ˈkɑːɡəʊ/","tag":"near meaning","definition":"Goods carried by a ship, aircraft or truck.","definitionCN":"指船、飞机或卡车运载的货物。"},{"word":"payload","ipa":"/ˈpeɪləʊd/","tag":"near meaning","definition":"The part of a vehicle's load that earns revenue or does the work.","definitionCN":"指载具负荷中产生收益或执行任务的那部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real way-word origin, the real trade family and real engineering phrases.","cn":"正常联想使用真实的「路途」来源、真实行业同族词与真实工程搭配。"},"normal":[{"en":"Load first meant a road, then the thing a road carries.","cn":"load 最初指一条路，后来指这条路所承载的东西。"},{"en":"Load capacity and heavy load are the engineering phrases.","cn":"承载能力与重载是工程里的说法。"},{"en":"Load a truck, load a camera and load data are three filling acts.","cn":"装车、装胶卷与加载数据是三个「装填」动作。"},{"en":"Overload and unload mark too much and none at all.","cn":"超载与卸载标出「太多」与「一点不剩」。"},{"en":"Workload is the same weight carried by a person rather than a beam.","cn":"工作量就是由人而不是梁来承担的同一份重量。"}],"abstract":[{"en":"A load is a promise the structure must keep every second.","cn":"载荷是结构每一秒都必须守住的承诺。"},{"en":"The same word weighs a steel coil and a bad memory.","cn":"同一个词既称钢卷的重量，也称一段坏记忆的重量。"},{"en":"Loading is putting something in so that the thing can begin.","cn":"加载就是把东西放进去，好让那件事得以开始。"}]},"examples":[{"en":"The column carries the load of the roof above it.","cn":"这根柱子承受上方屋顶的载荷。"},{"en":"Workers load the truck before the gate opens.","cn":"工人在大门打开前装车。"},{"en":"The screen froze while the program was loading the file.","cn":"程序加载文件时屏幕卡住了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「漏德」——压在梁上的重量不能「漏」掉，得全「德」扛住：负荷","word":"load"},"root":"古英语 lad「路途、进程」← 原始日耳曼语 laidō「向前走」；同族形式多指道路或轨迹。十三世纪起转指所背负之物，十四世纪产生动词，十五世纪用于枪炮装填，十九世纪用于电路，二十世纪用于数据；力学义的确切年代来源不确定。","sensesIntro":{"en":"Nine senses all concern what is carried: force on a structure, goods in a vehicle, work on a person, current in a circuit, cargo placed on board, a charge in a device, data in memory, worry in a mind, and power drawn from an engine.","cn":"九个义项都与「承载」有关：结构受力、车辆载货、人的工作量、电路电流、装船装车、装置装填、内存数据、心中忧虑与发动机输出功率。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hook lifts a coil until the gauge reaches the rated limit.","cn":"核心意象：吊钩吊起钢卷，直到仪表到达额定极限。"},"chain":["A WAY","SOMETHING CARRIED","WEIGHT ON A BEARER","MEASURED LIMIT","POWER DRAWN","DATA FILLED IN"],"branches":[{"senses":"01 · 09","en":"THE FORCE ON A MACHINE: a beam bearing tonnes, and an engine working at full demand.","cn":"机器所受的力：梁承受数吨重量，发动机满负荷运转。"},{"senses":"02 · 05","en":"THE CARGO: the amount a vehicle can take, and the act of putting it aboard.","cn":"货物：车辆能装的数量，以及把货装上去的动作。"},{"senses":"03 · 08","en":"THE HUMAN WEIGHT: too much work at a desk, and too much worry in a mind.","cn":"人的重量：桌上过多的工作，与心中过多的忧虑。"},{"senses":"04","en":"THE ELECTRICAL DRAW: current taken from a supply until the breaker trips.","cn":"电的取用：从电源取用电流，直到断路器跳闸。"},{"senses":"06 · 07","en":"THE THING PUT IN: a charge in a weapon, and a file brought into memory.","cn":"装进去的东西：装进武器的弹药，以及带进内存的文件。"}]},"affixes":{"intro":{"en":"Load is a native English word of Germanic origin, so it has no Latin ancestor; its Latin list is left empty.","cn":"这是一个日耳曼来源的英语本族词，没有拉丁语祖先，因此拉丁词条留空。"},"latinIntro":{"en":"There is no Latin source for load; the relevant origin is Proto-Germanic laidō, a word for a way or a course.","cn":"load 没有拉丁语来源；相关来源是原始日耳曼语 laidō，指路途或进程。"},"items":[{"word":"lad","structure":"Old English noun","meaning":"way, course, journey","meaningCN":"路途；进程；旅程","example":"The oldest sense is about moving, not carrying.","exampleCN":"最古老的意思关乎行走，而非承载。"},{"word":"*laidō","structure":"Proto-Germanic noun","meaning":"a way, a leading","meaningCN":"路途；引导","example":"The form is reconstructed from related languages.","exampleCN":"该形式由相关语言重构而来。"},{"word":"-ed","structure":"completed-state ending","meaning":"carrying a load","meaningCN":"载着负荷的","example":"It forms the adjective loaded.","exampleCN":"它构成形容词 loaded。"},{"word":"-ing","structure":"action noun ending","meaning":"the act of filling","meaningCN":"装填的动作","example":"It forms the noun loading.","exampleCN":"它构成名词 loading。"},{"word":"-er","structure":"agent noun ending","meaning":"the one that loads","meaningCN":"执行装载的人或物","example":"It forms loader.","exampleCN":"它构成 loader。"},{"word":"over-","structure":"English prefix","meaning":"too much","meaningCN":"过多；超过","example":"It forms overload.","exampleCN":"它构成超载。"},{"word":"un-","structure":"English prefix","meaning":"reverse","meaningCN":"反向；取消","example":"It forms unload.","exampleCN":"它构成卸载。"},{"word":"workload","structure":"work plus load","meaning":"the amount of work borne","meaningCN":"所承担的工作量","example":"The compound moves the load from steel to people.","exampleCN":"这个复合词把负荷从钢梁转到人身上。"},{"word":"payload","structure":"pay plus load","meaning":"the earning part of a load","meaningCN":"负荷中产生收益的部分","example":"The compound separates cargo from the vehicle.","exampleCN":"这个复合词把货物与载具分开。"}],"latinEntries":[],"derivatives":[{"word":"loader","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「装载机；装载者」"},{"word":"loading","pos":"n.","zh":"由该动词加表示进行的名词尾构成，义为「装载；加载」"},{"word":"overload","pos":"v./n.","zh":"由表示「超过」的前缀加该词构成，义为「超载」"},{"word":"unload","pos":"v.","zh":"由表示「反向」的前缀加该动词构成，义为「卸载」"},{"word":"workload","pos":"n.","zh":"由「工作」加该名词构成，义为「工作量」"}]}},{"word":"strain","ipa_uk":"/streɪn/","ipa_us":"/streɪn/","definition_zh":"应变；拉紧；拉伤；压力；菌株；过滤","definition_en":"the deformation of a material under force, a severe demand on body or mind, a variety of organism, or to stretch, injure or filter","core_image":"拉伸试验机上，一根试样的标距段被拉长，刻度差一点点扩大，指针同时记录力值","scene":"拉伸试验机上，试样被缓缓拉长，标距段的刻度差逐渐扩大，记录仪同时画出力值曲线。The gauge measures the strain as the specimen stretches.","sceneCN":"这里指材料受力后长度变化的相对量（第 1 个义项：应变）；句意为试样被拉伸时，应变仪测出应变。图中可辨识物件：试样、标距、夹具、引伸计、记录仪。","pos":[{"tag":"n.","zh":"应变；张力；拉伤；压力；菌株"},{"tag":"v.","zh":"拉紧；使劲；扭伤；过滤"}],"collocations":[{"phrase":"strain gauge","zh":"应变片"},{"phrase":"under strain","zh":"处于压力之下"},{"phrase":"muscle strain","zh":"肌肉拉伤"},{"phrase":"strain a rope","zh":"拉紧绳索"},{"phrase":"bacterial strain","zh":"细菌菌株"},{"phrase":"strain the soup","zh":"把汤滤清"}],"forms":[{"label":"单数","form":"strain"},{"label":"复数","form":"strains"},{"label":"第三人称单数","form":"strains"},{"label":"过去式","form":"strained"},{"label":"过去分词","form":"strained"},{"label":"现在分词","form":"straining"}],"derivatives":[{"word":"strained","pos":"adj.","zh":"由该动词加已然词尾构成，义为「紧张的；拉紧的；滤过的」"},{"word":"strainer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「滤网；过滤器」"},{"word":"restrain","pos":"v.","zh":"由表示「回、向后」的前缀加同源动词构成，义为「抑制；约束」"},{"word":"constrain","pos":"v.","zh":"由表示「共同、完全」的前缀加同源动词构成，义为「限制；强迫」"},{"word":"strict","pos":"adj.","zh":"由同一拉丁词干的过去分词而来，义为「严格的；紧的」"}],"senses":[{"no":"01","title":"Deformation per unit length","titleCN":"单位长度的形变量","definition":"the change in length of a material divided by its original length when a force acts on it","definitionCN":"材料受力时长度变化量与原长度之比","example":"The strain in the bar stayed below the elastic limit.","exampleCN":"这根杆的应变仍低于弹性极限。","why":"The verb meant to draw tight, and engineers turned the drawing-tight into a measurable ratio.","whyCN":"这个动词意为拉紧，工程师把「拉紧」变成了可测量的比值。"},{"no":"02","title":"An injury from overuse","titleCN":"过度用力造成的拉伤","definition":"an injury to a muscle or tendon caused by stretching it too far","definitionCN":"因拉伸过度造成的肌肉或肌腱损伤","example":"He suffered a strain in his lower back.","exampleCN":"他的下背部拉伤了。","why":"Tissue stretched past its limit is literally strained, and the injury took the name of the action.","whyCN":"组织被拉过限度就是字面意义上的「被拉紧」，损伤沿用了动作之名。"},{"no":"03","title":"Pressure on a person","titleCN":"精神或关系上的压力","definition":"a severe demand on a person's mind or on a relationship","definitionCN":"对一个人心智或一段关系的沉重要求","example":"The long shifts put a strain on the whole team.","exampleCN":"长时间轮班给整个团队带来了压力。","why":"A rope under tension can break, and people under demand are described with the same image.","whyCN":"受拉的绳子会断，承受要求的人被用同一个画面描述。"},{"no":"04","title":"A biological variety","titleCN":"生物品系或菌株","definition":"a genetic variant of a plant, animal or microorganism bred or identified for a purpose","definitionCN":"为某一目的培育或识别出的植物、动物或微生物的遗传变体","example":"The lab used a hardy strain of wheat.","exampleCN":"实验室使用了一种耐寒的小麦品系。","why":"The lineage sense of the word survived in biology, where a strain is a line of descent; the exact link is source uncertain.","whyCN":"这个词的「血统」义在生物学里保留下来，菌株就是一条传承线；两者联系的确切程度来源不确定。"},{"no":"05","title":"The tightness of a rope","titleCN":"绳索绷紧的程度","definition":"the condition of being pulled tight, or the force produced by that pulling","definitionCN":"被拉紧的状态，或这种拉伸产生的力","example":"The strain on the cable was visible in its hum.","exampleCN":"缆绳的紧绷从它的嗡鸣声里听得出来。","why":"This is the everyday physical core from which the engineering ratio and the injury both grew.","whyCN":"这是日常的物理核心，工程的比值与损伤义都从这里长出。"},{"no":"06","title":"To pull tight","titleCN":"拉紧、绷紧","definition":"to stretch something until it is tight, often by force","definitionCN":"把某物拉到绷紧，常需用力","example":"Strain the rope until the post stops leaning.","exampleCN":"把绳子拉紧，直到立柱不再倾斜。","why":"The verb is the source of the whole family, and it still names the physical act.","whyCN":"动词是整族词的源头，至今仍指那个物理动作。"},{"no":"07","title":"To try very hard","titleCN":"竭力、使劲","definition":"to make a very great effort, often beyond what is comfortable","definitionCN":"付出极大努力，常超出舒适范围","example":"The engine strained to pull the loaded truck uphill.","exampleCN":"发动机竭力把满载卡车拉上坡。","why":"Effort is imagined as pulling against a resistance, and the verb carries that resistance.","whyCN":"努力被想象成对抗阻力地拉，这个动词带着那股阻力。"},{"no":"08","title":"To filter or drain","titleCN":"过滤、沥干","definition":"to pass a liquid or mixture through a sieve or cloth to remove solids","definitionCN":"让液体或混合物通过筛网或布，以除去固体","example":"Strain the oil before you reuse it.","exampleCN":"重复使用前先把油滤一遍。","why":"The same family word meant to press or squeeze, and squeezing a mixture through cloth is filtering.","whyCN":"同族词有「压、挤」的意思，把混合物从布里挤出就是过滤。"},{"no":"09","title":"To injure by twisting","titleCN":"扭伤","definition":"to injure a muscle or joint by sudden or excessive twisting","definitionCN":"因突然或过度扭转而损伤肌肉或关节","example":"He strained his ankle on the uneven ground.","exampleCN":"他在不平的地面上扭伤了脚踝。","why":"The injury sense split from the general over-pulling sense and took the twisting cases with it.","whyCN":"损伤义从一般的「拉过头」分出来，把扭转的情形一并带走。"}],"etymology":{"intro":{"en":"Strain has two sources. The verb and most senses come through Old French estreindre from Latin stringere, to draw tight. The sense of lineage or breed comes separately from Old English streon, offspring or begetting.","cn":"这个词有两个来源。动词与多数义项经古法语 estreindre 来自拉丁语 stringere「拉紧」；表示血统、品种的意思另来自古英语 streon「后代、生育」。"},"items":[{"era":"LATIN STRINGERE","en":"Stringere meant to draw tight, bind or compress, and its past participle strictus gave English strict.","cn":"这个词意为拉紧、束缚、压紧，其过去分词 strictus 给了英语 strict「严格的」。"},{"era":"OLD FRENCH ESTREINDRE","en":"French kept the verb for squeezing and stretching, and English borrowed it in the thirteenth century.","cn":"法语保留了表示挤压与拉伸的动词，英语在十三世纪借入。"},{"era":"THE INJURY SENSE","en":"By the seventeenth century the noun named an injury from overexertion; the first attestation date is uncertain.","cn":"到十七世纪，这个名词指过度用力造成的损伤；这一义项的首见年代不确定。"},{"era":"OLD ENGLISH STREON","en":"A separate noun meant offspring, gain or begetting, and it is the ancestor of the lineage sense.","cn":"另一个名词意为后代、收获、生育，是血统义的祖先。"},{"era":"BIOLOGICAL STRAIN","en":"Nineteenth-century biology used strain for a bred line of organisms, possibly from the lineage sense; the link is source uncertain.","cn":"十九世纪生物学用这个词指培育出的生物品系，可能来自血统义；这一联系来源不确定。"},{"era":"ENGINEERING STRAIN","en":"Mechanics gave the word its precise ratio of deformation, and the first attestation date of that definition is uncertain.","cn":"力学赋予这个词精确的形变比值含义，该定义的首见年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like strain; the second group names neighbouring ideas of stress and filtering.","cn":"第一组在形音上与「strain」相近；第二组是与「应力、过滤」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"strained","ipa":"/streɪnd/","tag":"same root","definition":"Tightened, filtered, or showing the effects of pressure.","definitionCN":"指被拉紧的、滤过的，或显出压力痕迹的。"},{"word":"strainer","ipa":"/ˈstreɪnə/","tag":"same root","definition":"A sieve or cloth used to filter liquid.","definitionCN":"指用来滤液的筛网或布。"},{"word":"restrain","ipa":"/rɪˈstreɪn/","tag":"same root","definition":"To hold back or control, literally to draw tight again.","definitionCN":"指抑制或控制，字面上是「再次拉紧」。"},{"word":"strict","ipa":"/strɪkt/","tag":"same root","definition":"Exact and severe, from the past participle meaning drawn tight.","definitionCN":"指严格严厉的，来自意为「被拉紧」的过去分词。"},{"word":"straight","ipa":"/streɪt/","tag":"different root","definition":"Not curved; it looks close but comes from a word for stretched out, not from the binding verb.","definitionCN":"指不弯的；形近，但来自表示「伸直」的词，而非绑缚动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stress","ipa":"/stres/","tag":"near meaning","definition":"The internal force per unit area in a material, or pressure on a person.","definitionCN":"指材料内部单位面积上的力，或人所受的压力。"},{"word":"tension","ipa":"/ˈtenʃn/","tag":"near meaning","definition":"The pulling force in a stretched object, or a strained relationship.","definitionCN":"指被拉物体中的拉力，或紧张的关系。"},{"word":"sprain","ipa":"/spreɪn/","tag":"near meaning","definition":"To injure a joint by sudden twisting, especially at the ligament.","definitionCN":"指因突然扭转而伤及关节，尤指韧带。"},{"word":"sieve","ipa":"/sɪv/","tag":"near meaning","definition":"A mesh tool used to separate solids from liquid or coarse from fine.","definitionCN":"指把固体与液体、粗与细分开的网具。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real sources, the real engineering family and real medical phrases.","cn":"正常联想使用两个真实来源、真实工程同族词与真实医学搭配。"},"normal":[{"en":"The core verb meant to draw tight, which gives rope strain, muscle strain and mental strain.","cn":"核心动词意为拉紧，由此有绳索紧绷、肌肉拉伤与精神压力。"},{"en":"Strain gauge is the instrument that turns stretching into a number.","cn":"应变片就是把拉伸变成数字的仪器。"},{"en":"Restrain and constrain are the same verb with prefixes added.","cn":"抑制与限制是同一个动词加前缀的结果。"},{"en":"Strain the soup uses the squeezing branch of the family.","cn":"把汤滤清用的是这一族词的「挤压」分支。"},{"en":"The biological strain comes from a different Old English word for offspring.","cn":"生物学里的品系来自另一个表示后代的古英语词。"}],"abstract":[{"en":"Strain is the visible proof that a force got in.","cn":"应变是力已经进来过的可见证据。"},{"en":"A person under strain is a rope with a load tied to it.","cn":"处在压力下的人，就是一根拴着重物的绳。"},{"en":"What is strained is still holding, and that is the whole story.","cn":"被拉紧的东西仍撑着，故事的全部就在这里。"}]},"examples":[{"en":"The strain in the cable was measured with a gauge.","cn":"缆绳的应变用应变片测出。"},{"en":"He strained his shoulder lifting the housing alone.","cn":"他一个人抬壳子时拉伤了肩膀。"},{"en":"The strain of night work showed in everyone's faces.","cn":"夜班的压力写在每个人脸上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「斯特雷恩」——绳子被「斯特」地拉直、拉得「雷恩」响：拉紧、应变","word":"strain"},"root":"一条来源为古法语 estreindre ← 拉丁语 stringere「拉紧」；同族 strict「严格的」来自其过去分词。另一条来源为古英语 streon「后代、生育」，是「血统、品系」义的祖先，与拉丁线不同源。生物学品系与力学应变两义的确切年代与联系来源不确定。","sensesIntro":{"en":"Nine senses split along two roots: tightness, deformation, injury, mental pressure and filtering from the Latin line; biological variety from the Old English line.","cn":"九个义项沿两条词源分开：紧绷、应变、损伤、精神压力与过滤来自拉丁线；生物品系来自古英语线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a specimen is pulled until the marks on it move apart.","cn":"核心意象：试样被拉伸，直到上面的标线彼此分开。"},"chain":["DRAW TIGHT","STRETCH","CHANGE OF LENGTH","MEASURED RATIO","OVER-PULLED TISSUE","LINE OF DESCENT"],"branches":[{"senses":"01 · 05 · 06","en":"THE MEASURED STRETCH: the ratio of deformation, the tightness it produces, and the act of pulling tight.","cn":"被量出的拉伸：形变的比值、它造成的紧绷，以及把绳索拉紧的动作。"},{"senses":"02 · 09","en":"THE INJURED BODY: a muscle pulled too far and a joint twisted too quickly.","cn":"受伤的身体：拉过头的肌肉与扭得太快的关节。"},{"senses":"03 · 07","en":"THE DEMAND ON PEOPLE AND MACHINES: mental pressure, and an engine trying beyond comfort.","cn":"对人机的苛求：精神压力，以及发动机超常地使劲。"},{"senses":"08","en":"THE SQUEEZING BRANCH: liquid pressed through cloth until solids stay behind.","cn":"挤压分支：液体被从布里压出，固体留在后面。"},{"senses":"04","en":"THE LINE OF DESCENT: a bred variety that inherits a trait.","cn":"传承线：继承某种性状的培育品系。"}]},"affixes":{"intro":{"en":"Strain is a French-carried Latin verb with one separate Old English noun of the same spelling behind the biological sense.","cn":"这是一个经法语传来的拉丁动词；生物义背后另有一个拼写相同的古英语名词。"},"latinIntro":{"en":"Latin stringere is the real source of the verb and most nouns; strictus is its participle, and the deeper root is a reconstruction.","cn":"拉丁语 stringere 是动词与多数名词义的真实来源；strictus 是其分词，更深的词根属重构。"},"items":[{"word":"stringere","structure":"Latin verb","meaning":"to draw tight, bind","meaningCN":"拉紧；绑缚","example":"The verb supplies the tightening core.","exampleCN":"这个动词提供了「拉紧」的核心。"},{"word":"strictus","structure":"past participle of stringere","meaning":"drawn tight","meaningCN":"被拉紧的","example":"It gives English strict and the idea of severity.","exampleCN":"它给了英语 strict 与「严格」的意思。"},{"word":"estreindre","structure":"Old French verb","meaning":"to press, squeeze, stretch","meaningCN":"压；挤；拉伸","example":"French carried the verb to English.","exampleCN":"法语把这个动词传给英语。"},{"word":"re-","structure":"Latin prefix","meaning":"back","meaningCN":"回；向后","example":"It builds restrain, to hold back.","exampleCN":"它构成 restrain「抑制」。"},{"word":"con-","structure":"Latin prefix","meaning":"together, wholly","meaningCN":"共同；完全","example":"It builds constrain, to bind completely.","exampleCN":"它构成 constrain「限制」。"},{"word":"-er","structure":"agent noun ending","meaning":"the thing that filters","meaningCN":"进行过滤的东西","example":"It builds strainer.","exampleCN":"它构成 strainer「滤网」。"},{"word":"-ed","structure":"completed-state ending","meaning":"tightened or filtered","meaningCN":"被拉紧或滤过的","example":"It builds strained.","exampleCN":"它构成 strained。"},{"word":"streon","structure":"Old English noun, separate source","meaning":"offspring, gain","meaningCN":"后代；收获","example":"It stands behind the biological sense.","exampleCN":"它支撑着生物义。"},{"word":"*streng-","structure":"reconstructed root","meaning":"tight, stiff","meaningCN":"紧的；僵硬的","example":"The form is a reconstruction.","exampleCN":"该形式是重构。"}],"latinEntries":[{"word":"stringere","structure":"Latin verb","meaning":"to draw tight","meaningCN":"拉紧"},{"word":"strictus","structure":"Latin participle","meaning":"drawn tight","meaningCN":"被拉紧的"},{"word":"strictura","structure":"Latin noun","meaning":"a contraction","meaningCN":"收缩；紧缩"}],"derivatives":[{"word":"strained","pos":"adj.","zh":"由该动词加已然词尾构成，义为「紧张的；滤过的」"},{"word":"strainer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「滤网」"},{"word":"restrain","pos":"v.","zh":"由表示「回、向后」的前缀加同源动词构成，义为「抑制」"},{"word":"constrain","pos":"v.","zh":"由表示「共同、完全」的前缀加同源动词构成，义为「限制」"},{"word":"strict","pos":"adj.","zh":"由同一拉丁词干的过去分词而来，义为「严格的」"}]}},{"word":"tension","ipa_uk":"/ˈtenʃn/","ipa_us":"/ˈtenʃn/","definition_zh":"拉力；张力；紧张；紧张关系；电压；表面张力","definition_en":"the state of being stretched tight, the pulling force in something stretched, or a state of nervous strain between people","core_image":"拔河绳被两队拉得笔直，中间的红布几乎不动，绳子发出细微的吱响","scene":"拔河绳被两队拉得笔直，中间的红布几乎不动，绳子发出细微的吱响。The tension in the rope rises until it begins to creak.","sceneCN":"这里指绷紧的绳索内部承受的拉力（第 1 个义项：拉力、张力）；句意为绳中的拉力不断上升，直到绳子开始吱响。图中可辨识物件：拔河绳、红布标记、两队队员、地面标线。","pos":[{"tag":"n.","zh":"拉力；张力；紧张；电压"}],"collocations":[{"phrase":"surface tension","zh":"表面张力"},{"phrase":"under tension","zh":"处于受拉状态"},{"phrase":"tension between groups","zh":"群体之间的紧张关系"},{"phrase":"ease the tension","zh":"缓解紧张"},{"phrase":"high tension","zh":"高压电；高度紧张"},{"phrase":"tension in the cable","zh":"缆索中的拉力"}],"forms":[{"label":"单数","form":"tension"},{"label":"复数","form":"tensions"},{"label":"动词","form":"tense"},{"label":"形容词","form":"tensional"},{"label":"副词","form":"tensely"},{"label":"名词（紧张状态）","form":"tenseness"}],"derivatives":[{"word":"tense","pos":"adj./v.","zh":"由同一拉丁词干经法语而来，义为「紧张的；拉紧」"},{"word":"tensile","pos":"adj.","zh":"由该名词加表示「可……的」的形容词尾构成，义为「可拉伸的」"},{"word":"tensity","pos":"n.","zh":"由该名词加表示性质的名词尾构成，义为「紧张度」"},{"word":"hypertension","pos":"n.","zh":"由表示「过度」的前缀加该名词构成，义为「高血压」"},{"word":"tensional","pos":"adj.","zh":"由该名词加表示关系的形容词尾构成，义为「张力的」"}],"senses":[{"no":"01","title":"The pull in a stretched object","titleCN":"被拉物体内部的拉力","definition":"the pulling force carried by a rope, cable or rod that is stretched between two points","definitionCN":"被拉在两点之间的绳、缆或杆所承受的拉力","example":"The tension in the cable holds the mast upright.","exampleCN":"缆索中的拉力使桅杆保持直立。","why":"The Latin verb meant to stretch, and the noun names the force that stretching produces.","whyCN":"拉丁动词意为拉伸，这个名词指拉伸所产生的力。"},{"no":"02","title":"Strain between people","titleCN":"人与人之间的紧张关系","definition":"a state of distrust or hostility between people, groups or countries","definitionCN":"人、群体或国家之间不信任或敌对的状态","example":"Tension between the two teams slowed the work.","exampleCN":"两队之间的紧张关系拖慢了工作。","why":"A stretched rope is ready to snap, and relationships under pressure are described by the same image.","whyCN":"拉紧的绳随时会断，承受压力的关系被同一个画面描述。"},{"no":"03","title":"Nervous strain","titleCN":"心理上的紧张","definition":"a feeling of worry and readiness that makes the body or mind tight","definitionCN":"使身体或心智绷紧的担忧与戒备感","example":"The waiting room was full of tension before the result.","exampleCN":"结果出来前，候诊室里满是紧张。","why":"The body tenses like a rope, and the physical word became the standard term for anxiety.","whyCN":"身体像绳子一样绷紧，这个物理词成了焦虑的标准说法。"},{"no":"04","title":"Electrical potential","titleCN":"电压","definition":"the electrical potential difference between two points, especially in older European usage","definitionCN":"两点之间的电势差，尤见于较早的欧洲用法","example":"The sign warned of high tension in the line.","exampleCN":"标牌警告线路带有高压。","why":"Early electrical science pictured voltage as a stretched state, and several European languages still say tension.","whyCN":"早期电学把电压想象成一种绷紧状态，若干欧洲语言至今仍用「张力」一词。"},{"no":"05","title":"The skin of a liquid","titleCN":"液体的表面张力","definition":"the force at the surface of a liquid that makes it behave like a thin elastic sheet","definitionCN":"液体表面使自身表现得像一层薄弹性膜的力量","example":"Surface tension keeps the droplet round.","exampleCN":"表面张力使液滴保持圆形。","why":"Molecules at the surface pull on each other like a stretched membrane, so the old word fits exactly.","whyCN":"表面分子彼此拉扯，像一张绷紧的膜，老词用得恰到好处。"},{"no":"06","title":"The tightness of a setting","titleCN":"绷紧程度","definition":"the degree to which something is pulled tight, as in a belt or a string","definitionCN":"某物被拉紧的程度，如皮带或琴弦","example":"Adjust the tension until the belt deflects ten millimetres.","exampleCN":"调整张紧度，直到皮带下垂十毫米。","why":"Tightness is a matter of degree, and maintenance work needs a word for that degree.","whyCN":"绷紧是程度问题，维修工作需要一个词来表示这个程度。"},{"no":"07","title":"Dramatic suspense","titleCN":"戏剧或叙事的张力","definition":"the quality in a story or performance that keeps an audience waiting for what comes next","definitionCN":"故事或表演中让观众等待后续的品质","example":"The film builds tension without showing the threat.","exampleCN":"影片不露威胁，却把张力堆起来。","why":"An audience is held like a rope between two pulls, and the metaphor became a craft term.","whyCN":"观众像被两股力量拉住的绳，这个比喻成了一门手艺术语。"},{"no":"08","title":"Muscular tightness","titleCN":"肌肉的紧张","definition":"the involuntary tightness of muscles caused by stress or effort","definitionCN":"因压力或用力而造成的肌肉不自主紧绷","example":"Massage reduced the tension in his shoulders.","exampleCN":"按摩缓解了他肩部的紧张。","why":"Muscle fibres literally shorten and tighten, and the word describes that state before it describes the feeling.","whyCN":"肌纤维确实会缩短绷紧，这个词先描述这种状态，再描述那种感受。"}],"etymology":{"intro":{"en":"Tension comes from Latin tensio, a stretching, from tensus, the past participle of tendere, to stretch. French carried the noun into English, and the figurative senses followed the physical one.","cn":"这个词来自拉丁语 tensio「拉伸」，源自 tendere「拉伸」的过去分词 tensus。法语把名词带入英语，比喻义在物理义之后出现。"},"items":[{"era":"LATIN TENDERE","en":"Tendere meant to stretch or extend, and it also stands behind English tend and tense.","cn":"这个词意为拉伸、伸展，也是英语 tend 与 tense 的来源。"},{"era":"LATIN TENSUS","en":"The past participle meant stretched or extended, and it gave the adjective tense its tight sense.","cn":"这个过去分词意为被拉伸、被伸展，给了形容词 tense「绷紧」的意思。"},{"era":"LATIN TENSIO","en":"The noun named the act of stretching and the state of being stretched, with no separate word for the force.","cn":"这个名词指拉伸动作与被拉伸的状态，当时并没有单独的词表示拉力。"},{"era":"FRENCH AND ENGLISH","en":"French tension reached English in the sixteenth century, first as a physical term and soon after as a mental one.","cn":"法语 tension 在十六世纪进入英语，先是物理术语，不久便用于心理。"},{"era":"ELECTRICAL USE","en":"The nineteenth century applied the word to voltage in several European languages, and which language coined that usage is source uncertain.","cn":"十九世纪若干欧洲语言把这个词用于电压；它最早出自哪种语言尚无定论，这一用法来源不确定。"},{"era":"DRAMA AND PHYSICS","en":"Literary criticism borrowed the word for suspense, and physics kept it for surface and structural forces.","cn":"文学批评借这个词指悬念，物理学则保留它指表面与结构中的力。"}]},"similar":{"note":{"en":"The first group looks or sounds like tension; the second group names neighbouring ideas of pulling and strain.","cn":"第一组在形音上与「tension」相近；第二组是与「拉伸、压力」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tense","ipa":"/tens/","tag":"same root","definition":"Tight or nervous, or a verb form that places an action in time.","definitionCN":"指绷紧或紧张的，也指表示时间的动词形式。"},{"word":"tensile","ipa":"/ˈtensaɪl/","tag":"same root","definition":"Capable of being stretched without breaking.","definitionCN":"指能被拉伸而不断裂的。"},{"word":"tensional","ipa":"/ˈtenʃənl/","tag":"same root","definition":"Relating to tension, especially in geology or mechanics.","definitionCN":"指与张力有关的，尤用于地质或力学。"},{"word":"extension","ipa":"/ɪkˈstenʃn/","tag":"same root","definition":"A stretching out or an added part; it shares the Latin stretching verb.","definitionCN":"指伸出或增加的部分；共享拉丁语「拉伸」动词。"},{"word":"tentative","ipa":"/ˈtentətɪv/","tag":"different root","definition":"Done without confidence; it looks close but comes from the word for trying.","definitionCN":"指没有把握地做的；形近，但来自表示「尝试」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"strain","ipa":"/streɪn/","tag":"near meaning","definition":"Deformation under force, or pressure on body and mind.","definitionCN":"指受力形变，或身心所受的压力。"},{"word":"stress","ipa":"/stres/","tag":"near meaning","definition":"Force per unit area inside a material, or mental pressure.","definitionCN":"指材料内部单位面积上的力，或精神压力。"},{"word":"pressure","ipa":"/ˈpreʃə/","tag":"near meaning","definition":"Force applied over an area, or a demanding influence.","definitionCN":"指施加在面积上的力，或一种施压的影响。"},{"word":"suspense","ipa":"/səˈspens/","tag":"near meaning","definition":"The feeling of waiting for an outcome that is not yet known.","definitionCN":"指等待未知结果时的感受。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real stretching verb, the real physics family and real engineering phrases.","cn":"正常联想使用真实的「拉伸」动词、真实物理同族词与真实工程搭配。"},"normal":[{"en":"The Latin verb meant to stretch, so tension is the state of being stretched.","cn":"拉丁动词意为拉伸，所以 tension 就是被拉伸的状态。"},{"en":"Tend, tense and tension all come from the same stretching stem.","cn":"tend、tense 与 tension 都出自同一个「拉伸」词干。"},{"en":"Surface tension and high tension are the two technical phrases.","cn":"表面张力与高压是两个技术说法。"},{"en":"Under tension and ease the tension cover the physical and the social.","cn":"受拉与缓解紧张分别覆盖物理与社会两个层面。"},{"en":"Tensile strength is what decides whether a rope survives its tension.","cn":"抗拉强度决定一根绳能不能撑住它的拉力。"}],"abstract":[{"en":"Tension is force that has not yet been released.","cn":"张力是还没有释放的力。"},{"en":"A room can be as tight as a rope without anyone touching it.","cn":"一个房间可以像绳子一样绷紧，却没人碰它。"},{"en":"Suspense is tension with a clock attached.","cn":"悬念就是挂上时钟的张力。"}]},"examples":[{"en":"The tension in the tie rod was set with a gauge.","cn":"拉杆的拉力用仪表设定。"},{"en":"Tension grew as the deadline approached.","cn":"期限临近，紧张气氛加重。"},{"en":"A drop of soap lowers the surface tension of water.","cn":"一滴肥皂液降低了水的表面张力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「藤申」——藤条被两头拉得直直的，一「申」手还能感到那股力：张力","word":"tension"},"root":"拉丁语 tensio「拉伸」← tensus（tendere「拉伸、伸展」的过去分词）；法语 tension 于十六世纪带入英语。比喻的「紧张」义随物理义而发展，十九世纪若干欧洲语言用它表示电压。同族有 tend、tense、tensile；各比喻用法定型的确切年代来源不确定。","sensesIntro":{"en":"Eight senses all describe something pulled: a cable, a relationship, a nervous body, a voltage, a liquid surface, a belt setting, an audience and a muscle.","cn":"八个义项都在描述被拉住的东西：缆索、关系、紧张的身体、电压、液面、皮带张紧度、观众与肌肉。"},"semanticMap":{"core":{"en":"CORE IMAGE: two teams pull one rope until the rope is straight and humming.","cn":"核心意象：两队人拉同一根绳，直到绳子笔直并发响。"},"chain":["TWO PULLS","ROPE STRAIGHT","FORCE IN THE ROPE","MEASURED TIGHTNESS","READY TO SNAP","RELEASED OR HELD"],"branches":[{"senses":"01 · 06","en":"THE PULL AND ITS DEGREE: the force in a cable and the tightness a mechanic sets.","cn":"拉力及其程度：缆索里的力，以及维修工设定的张紧度。"},{"senses":"02 · 03","en":"THE TAUT RELATIONSHIP: distrust between groups and anxiety in a waiting room.","cn":"绷紧的关系：群体间的猜疑，以及候诊室里的焦虑。"},{"senses":"04","en":"THE ELECTRICAL STRETCH: potential waiting to discharge through a line.","cn":"电的绷紧：等待沿线路释放的电势差。"},{"senses":"05","en":"THE LIQUID SKIN: surface molecules pulling the drop into a round shape.","cn":"液体的表皮：表面分子把液滴拉成圆形。"},{"senses":"07 · 08","en":"THE HELD BODY: an audience waiting, and shoulders tightened by stress.","cn":"被拉住的身体：等待的观众，以及因压力绷紧的肩膀。"}]},"affixes":{"intro":{"en":"Tension is a Latin noun of stretching, carried by French, with a family that still produces physics and medical terms.","cn":"这是一个表示「拉伸」的拉丁名词，经法语传入，其词族至今仍在生成物理与医学术语。"},"latinIntro":{"en":"Latin tendere, tensus and tensio are the real chain; the deeper root is reconstructed rather than recorded.","cn":"拉丁语的 tendere、tensus 与 tensio 构成真实的链条；更深词根属重构，而非有记录形式。"},"items":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch, extend","meaningCN":"拉伸；伸展","example":"The verb is the source of the whole family.","exampleCN":"这个动词是整族词的来源。"},{"word":"tensus","structure":"past participle of tendere","meaning":"stretched","meaningCN":"被拉伸的","example":"It supplies the adjective tense.","exampleCN":"它提供了形容词 tense。"},{"word":"tensio","structure":"Latin noun from tensus","meaning":"a stretching","meaningCN":"拉伸","example":"The noun is the direct source of tension.","exampleCN":"这个名词是 tension 的直接来源。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or state of","meaningCN":"动作或状态","example":"The ending carries the Latin noun into English.","exampleCN":"这个词尾把拉丁名词带入英语。"},{"word":"-ile","structure":"adjective ending","meaning":"capable of being","meaningCN":"能够被……的","example":"It builds tensile, able to be stretched.","exampleCN":"它构成 tensile「可拉伸的」。"},{"word":"-ity","structure":"quality noun ending","meaning":"the state of being","meaningCN":"……的性质","example":"It builds tensity.","exampleCN":"它构成 tensity「紧张度」。"},{"word":"hyper-","structure":"Greek prefix","meaning":"over, beyond","meaningCN":"过度；超过","example":"It builds hypertension, over-tight pressure.","exampleCN":"它构成 hypertension「高血压」。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It builds tensional.","exampleCN":"它构成 tensional。"},{"word":"*ten-","structure":"reconstructed root","meaning":"to stretch","meaningCN":"拉伸","example":"The form is a reconstruction.","exampleCN":"该形式是重构。"}],"latinEntries":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch, extend","meaningCN":"拉伸；伸展"},{"word":"tensus","structure":"Latin participle","meaning":"stretched","meaningCN":"被拉伸的"},{"word":"tensio","structure":"Latin noun","meaning":"a stretching","meaningCN":"拉伸"}],"derivatives":[{"word":"tense","pos":"adj./v.","zh":"由同一拉丁词干经法语而来，义为「紧张的；拉紧」"},{"word":"tensile","pos":"adj.","zh":"由该名词加表示「可……的」的形容词尾构成，义为「可拉伸的」"},{"word":"tensity","pos":"n.","zh":"由该名词加表示性质的名词尾构成，义为「紧张度」"},{"word":"tensional","pos":"adj.","zh":"由该名词加表示关系的形容词尾构成，义为「张力的」"},{"word":"hypertension","pos":"n.","zh":"由表示「过度」的前缀加该名词构成，义为「高血压」"}]}},{"word":"compression","ipa_uk":"/kəmˈpreʃn/","ipa_us":"/kəmˈpreʃn/","definition_zh":"压缩；压紧；压力；压缩程度；数据压缩","definition_en":"the act of pressing something so that it takes less space, the force produced by such pressing, or the reduction of data or content","core_image":"液压机把一块泡沫压到原来一半厚度，松手后它慢慢弹回一些","scene":"液压机把一块泡沫压到原来一半厚度，松手后它慢慢弹回一些。The press applies compression until the foam halves in thickness.","sceneCN":"这里指把物体压小、压紧的动作（第 1 个义项：压缩动作）；句意为压机施加压缩，直到泡沫厚度减半。图中可辨识物件：压板、泡沫块、液压缸、压力表、厚度标尺。","pos":[{"tag":"n.","zh":"压缩；压力；压缩程度；数据压缩"}],"collocations":[{"phrase":"compression test","zh":"压缩试验"},{"phrase":"compression ratio","zh":"压缩比"},{"phrase":"data compression","zh":"数据压缩"},{"phrase":"under compression","zh":"处于受压状态"},{"phrase":"compression stroke","zh":"压缩冲程"},{"phrase":"compression bandage","zh":"压迫绷带"}],"forms":[{"label":"名词（不可数）","form":"compression"},{"label":"复数（指多种压缩）","form":"compressions"},{"label":"动词","form":"compress"},{"label":"形容词","form":"compressive"},{"label":"施动者","form":"compressor"},{"label":"可压缩性","form":"compressibility"}],"derivatives":[{"word":"compress","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「压缩；压紧」"},{"word":"compressor","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「压缩机」"},{"word":"compressive","pos":"adj.","zh":"由该名词加表示性质的形容词尾构成，义为「压缩的；抗压的」"},{"word":"compressible","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可压缩的」"},{"word":"compressibility","pos":"n.","zh":"由可压缩形容词加表示性质的名词尾构成，义为「可压缩性」"}],"senses":[{"no":"01","title":"The act of pressing down","titleCN":"把物体压小的动作","definition":"the act of pressing or squeezing something so that it occupies less space","definitionCN":"把某物压或挤，使其占据更小空间的动作","example":"Compression of the foam took only a few seconds.","exampleCN":"泡沫的压缩只用了几秒钟。","why":"The Latin verb meant to press together, and the noun simply names that pressing.","whyCN":"拉丁动词意为「压到一起」，这个名词就直接指那种压。"},{"no":"02","title":"The force inside a solid","titleCN":"材料内部的压应力","definition":"the internal force per unit area that pushes material together","definitionCN":"使材料彼此靠拢的内部单位面积力","example":"The column fails when compression exceeds its strength.","exampleCN":"当压力超过强度时，这根柱子会破坏。","why":"Engineers needed a word for the pushing side of force, and the pressing verb supplied it.","whyCN":"工程师需要一个词表示力的「推挤」一侧，表示压的动词正好提供。"},{"no":"03","title":"Shrinking a file","titleCN":"把文件压小","definition":"the reduction of the size of digital data by encoding it more efficiently","definitionCN":"通过更高效的编码来减小数字数据体积","example":"Compression cut the image to a tenth of its size.","exampleCN":"压缩把图像减到原来大小的十分之一。","why":"Digital files are treated as material that can be squeezed, and the metaphor is now the standard term.","whyCN":"数字文件被当作可挤压的材料，这个比喻如今成了标准术语。"},{"no":"04","title":"The squeeze inside an engine","titleCN":"发动机的压缩程度","definition":"the reduction of the volume of a gas or fuel mixture in a cylinder before ignition","definitionCN":"点火前气缸内气体或混合气体积的缩小","example":"A higher compression gives the engine more power.","exampleCN":"更高的压缩程度使发动机功率更大。","why":"The piston literally compresses the charge, and the noun names both the stroke and its measure.","whyCN":"活塞确实在压缩混合气，这个名词兼指冲程与其度量。"},{"no":"05","title":"Medical pressing","titleCN":"医学上的压迫","definition":"the application of steady pressure to a body part, as to stop bleeding","definitionCN":"对身体部位持续施压，例如止血","example":"Direct compression stopped the bleeding.","exampleCN":"直接压迫止住了出血。","why":"The same physical act is used on tissue, and the noun keeps its literal force in medicine.","whyCN":"同一个物理动作被用在组织上，这个名词在医学中保留了字面含义。"},{"no":"06","title":"Encoding sound and video","titleCN":"音视频编码压缩","definition":"the process of reducing the bit rate of audio or video while keeping it usable","definitionCN":"在保持可用性的前提下降低音频或视频码率的过程","example":"The stream uses compression to fit the bandwidth.","exampleCN":"这个流媒体用压缩来适应带宽。","why":"Media data behaves like any other data, and the engineering word carried over unchanged.","whyCN":"媒体数据与其它数据一样，工程词原样搬了过来。"},{"no":"07","title":"Shortening a text","titleCN":"内容的浓缩","definition":"the reduction of a text or account to its essential points","definitionCN":"把文本或叙述减到要点","example":"The summary is a compression of a long report.","exampleCN":"这份摘要是对一份长报告的浓缩。","why":"Ideas are imagined as taking up space, so shortening them is called squeezing them.","whyCN":"观念被想象成占空间的东西，因此缩短它们被叫作挤压。"},{"no":"08","title":"The pressed state","titleCN":"被压紧的状态","definition":"the condition of being pressed tightly together, as of a spring or a seal","definitionCN":"被紧密压在一起的状态，如弹簧或密封件","example":"The seal works by compression against the flange.","exampleCN":"这个密封件靠压紧在法兰上起作用。","why":"The result of pressing is a state, and machine design needs a noun for that state.","whyCN":"压的结果是一种状态，机械设计需要名词来表示这种状态。"}],"etymology":{"intro":{"en":"Compression comes from French or Latin compressio, from compressus, the past participle of comprimere, to press together, built from com, together, and premere, to press.","cn":"这个词来自法语或拉丁语 compressio，源自 comprimere「压到一起」的过去分词 compressus；该动词由 com「一起」与 premere「压」构成。"},"items":[{"era":"LATIN COM-","en":"The prefix com- meant together or with, and here it marks the two sides of a material being brought into contact.","cn":"这个前缀意为「一起、共同」，在这里标出材料两侧被压到接触。"},{"era":"LATIN PREMERE","en":"Premere meant to press, squeeze or push down, and it is the same stem behind English press and pressure.","cn":"这个词意为压、挤、按下，也是英语 press 与 pressure 背后的同一词干。"},{"era":"LATIN COMPRIMERE","en":"The compound verb meant to press together or compress, used of physical objects and of shortened speech.","cn":"这一复合动词意为压到一起、压缩，既用于实物，也用于缩短的言语。"},{"era":"LATIN COMPRESSIO","en":"The noun named the act of pressing together, and French carried it into English in the sixteenth century.","cn":"这个名词指压到一起的动作，十六世纪由法语带入英语。"},{"era":"ENGINEERING","en":"Mechanics made compression the opposite of tension, naming the force that shortens a member; the exact date is uncertain and is tied to the formation of stress analysis.","cn":"力学使 compression 成为 tension 的反面，用来指缩短构件的力；确切年代不确定，只知随应力分析一并定型。"},{"era":"DIGITAL AGE","en":"The twentieth century applied the word to data and media, where files are made smaller by encoding.","cn":"二十世纪把这个词用于数据与媒体，文件通过编码变小。"}]},"similar":{"note":{"en":"The first group looks or sounds like compression; the second group names neighbouring ideas of pressing and shrinking.","cn":"第一组在形音上与「compression」相近；第二组是与「压紧、缩小」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compress","ipa":"/kəmˈpres/","tag":"same root","definition":"The verb for pressing something smaller or shortening data.","definitionCN":"指把东西压小或缩短数据的动词。"},{"word":"compressor","ipa":"/kəmˈpresə/","tag":"same root","definition":"A machine that squeezes gas into a smaller volume.","definitionCN":"指把气体压进更小体积的机器。"},{"word":"compressive","ipa":"/kəmˈpresɪv/","tag":"same root","definition":"Relating to force that presses material together.","definitionCN":"指与把材料压拢的力有关的。"},{"word":"compression","ipa":"/kəmˈpreʃn/","tag":"same root","definition":"This word itself, naming the act, the force and the digital reduction.","definitionCN":"本词本身，指动作、力与数字压缩。"},{"word":"compassion","ipa":"/kəmˈpæʃn/","tag":"different root","definition":"Sympathy for suffering; it shares the prefix but comes from a word for feeling, not pressing.","definitionCN":"指对苦难的同情；共享前缀，但来自表示「感受」的词，而非压。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pressure","ipa":"/ˈpreʃə/","tag":"near meaning","definition":"Force applied over an area, including the pressing force in a fluid or solid.","definitionCN":"指施加在面积上的力，包括流体或固体中的压力。"},{"word":"squeeze","ipa":"/skwiːz/","tag":"near meaning","definition":"To press from two sides so that something becomes narrower.","definitionCN":"指从两侧压，使某物变窄。"},{"word":"condensation","ipa":"/kənˌdenˈseɪʃn/","tag":"near meaning","definition":"The shortening of a text or the change of vapour into liquid; it shares the idea of making denser.","definitionCN":"指文本的缩短或蒸汽变液体；共享「使更密」的意思。"},{"word":"encoding","ipa":"/ɪnˈkəʊdɪŋ/","tag":"near meaning","definition":"The conversion of data into a more compact or usable form.","definitionCN":"指把数据转换成更紧凑或可用的形式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real press-together source, the real mechanics family and real technical phrases.","cn":"正常联想使用真实的「压到一起」来源、真实力学同族词与真实技术搭配。"},"normal":[{"en":"Com means together and premere means press, so compression is a pressing together.","cn":"前缀意为一起，词根意为压，所以 compression 就是压到一起。"},{"en":"Press, pressure and compression are three words from one pressing stem.","cn":"press、pressure 与 compression 是同一个「压」词干的三张面孔。"},{"en":"Compression ratio belongs to engines, compression test to materials.","cn":"压缩比属于发动机，压缩试验属于材料。"},{"en":"Compression is the opposite of tension, one shortens and one lengthens.","cn":"压缩与拉伸相对，一个使变短，一个使变长。"},{"en":"Data compression squeezes a file the way a press squeezes foam.","cn":"数据压缩压小文件，就像压机压小泡沫。"}],"abstract":[{"en":"Compression is space removed from something without destroying it.","cn":"压缩是从某物里拿走空间，却不毁掉它。"},{"en":"Every column carries its load by being compressed every second.","cn":"每根柱子都靠每秒被压缩来承担荷载。"},{"en":"A good summary is compression that keeps the shape.","cn":"好的摘要是保住了形状的压缩。"}]},"examples":[{"en":"The test measures compression at three loads.","cn":"这项试验在三种载荷下测量压缩。"},{"en":"Lossless compression keeps every bit of the file.","cn":"无损压缩保留文件的每一个比特。"},{"en":"Too much compression cracked the foam core.","cn":"压缩过度使泡沫芯开裂。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康普瑞申」——把东西「康」在一起、普瑞地压紧：压缩","word":"compression"},"root":"法语或拉丁语 compressio ← compressus（comprimere「压到一起」的过去分词）← com-「一起」+ premere「压」；premere 同族有 press「压」与 pressure「压力」。力学使它与 tension 相对，二十世纪又用于数据与媒体压缩；各义定型年代来源不确定。","sensesIntro":{"en":"Eight senses all reduce space or press things together: a physical squeeze, internal force, a file, a cylinder charge, a wound, a media stream, a long text and a seated seal.","cn":"八个义项都在减少空间或把东西压拢：物理挤压、内部压力、文件、气缸混合气、伤口、媒体流、长文本与压紧的密封件。"},"semanticMap":{"core":{"en":"CORE IMAGE: two plates close on foam until it is half as thick.","cn":"核心意象：两块压板合拢压住泡沫，直到它只剩一半厚度。"},"chain":["TWO PLATES","SPACE CLOSED","VOLUME REDUCED","FORCE BUILT","MATERIAL SHORTENED","DATA SHRUNK"],"branches":[{"senses":"01 · 08","en":"THE PHYSICAL SQUEEZE: the act of pressing and the pressed state that remains.","cn":"物理挤压：压的动作，以及压完之后留下的压紧状态。"},{"senses":"02","en":"THE INTERNAL FORCE: the push inside a column that holds the roof up.","cn":"内部压力：柱子内部撑住屋顶的那股推力。"},{"senses":"03 · 06","en":"THE SHRUNK SIGNAL: a file or a media stream made smaller by encoding.","cn":"被压小的信号：通过编码变小的文件或媒体流。"},{"senses":"04","en":"THE ENGINE CHARGE: gas squeezed in a cylinder before it burns.","cn":"发动机充量：燃烧前在气缸里被压紧的气体。"},{"senses":"05 · 07","en":"THE PRESSED BODY AND TEXT: a bandage on a wound, and a report cut to its points.","cn":"被压的身体与文本：伤口上的绷带，以及删到要点的报告。"}]},"affixes":{"intro":{"en":"Compression is a Latin noun of pressing, carried by French, and its stem still builds compressors and compressibility.","cn":"这是一个表示「压」的拉丁名词，经法语传入，其词干至今仍构成压缩机与可压缩性等词。"},"latinIntro":{"en":"Latin com- and premere are the real parts, comprimere the compound, and compressio the noun.","cn":"拉丁语 com- 与 premere 是真实构件，comprimere 是复合动词，compressio 是名词。"},"items":[{"word":"com-","structure":"Latin prefix, assimilated form of con-","meaning":"together","meaningCN":"一起；共同","example":"The prefix brings the two sides together.","exampleCN":"这个前缀把两侧带到一起。"},{"word":"premere","structure":"Latin verb","meaning":"to press, squeeze","meaningCN":"压；挤","example":"The verb is the pressing core.","exampleCN":"这个动词是「压」的核心。"},{"word":"comprimere","structure":"com- plus premere","meaning":"to press together","meaningCN":"压到一起","example":"The compound is the direct source.","exampleCN":"这个复合动词是直接来源。"},{"word":"compressio","structure":"Latin noun","meaning":"a pressing together","meaningCN":"压到一起","example":"The noun entered English through French.","exampleCN":"这个名词经法语进入英语。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result of","meaningCN":"动作或结果","example":"The ending builds the English noun.","exampleCN":"这个词尾构成英语名词。"},{"word":"-or","structure":"agent noun ending","meaning":"the thing that presses","meaningCN":"进行压缩的装置","example":"It builds compressor.","exampleCN":"它构成 compressor「压缩机」。"},{"word":"-ive","structure":"adjective ending","meaning":"having the function of","meaningCN":"具有……作用的","example":"It builds compressive.","exampleCN":"它构成 compressive。"},{"word":"-ible","structure":"adjective ending","meaning":"can be","meaningCN":"可以被……的","example":"It builds compressible.","exampleCN":"它构成 compressible。"},{"word":"-ity","structure":"quality noun ending","meaning":"the state of being","meaningCN":"……的性质","example":"It builds compressibility.","exampleCN":"它构成 compressibility。"}],"latinEntries":[{"word":"premere","structure":"Latin verb","meaning":"to press, squeeze","meaningCN":"压；挤"},{"word":"comprimere","structure":"Latin verb","meaning":"to press together","meaningCN":"压到一起"},{"word":"compressio","structure":"Latin noun","meaning":"a pressing together","meaningCN":"压到一起"}],"derivatives":[{"word":"compress","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「压缩；压紧」"},{"word":"compressor","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「压缩机」"},{"word":"compressive","pos":"adj.","zh":"由该名词加表示性质的形容词尾构成，义为「抗压的」"},{"word":"compressible","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可压缩的」"},{"word":"compressibility","pos":"n.","zh":"由可压缩形容词加表示性质的名词尾构成，义为「可压缩性」"}]}},{"word":"compression force","ipa_uk":"/kəmˈpreʃn fɔːs/","ipa_us":"/kəmˈpreʃn fɔːrs/","definition_zh":"压缩力；压力；压紧力；预紧力","definition_en":"the force that presses or shortens a structural member, specimen or joint","core_image":"压力机上，混凝土试块夹在两块压板之间，表盘指针随荷载上升，直到试块裂开","scene":"压力机上，混凝土试块夹在两块压板之间，表盘指针随荷载上升，直到试块裂开。The compression force rises until the concrete cube cracks.","sceneCN":"这里指压力机通过压板施加给试块的压缩力（第 2 个义项：压缩试验载荷）；句意为压缩力不断上升，直到混凝土立方体开裂。图中可辨识物件：试块、上下压板、压力表、加载手轮、裂纹。","pos":[{"tag":"n.","zh":"压缩力；压力；压紧力"}],"collocations":[{"phrase":"apply a compression force","zh":"施加压缩力"},{"phrase":"compression force test","zh":"抗压试验"},{"phrase":"axial compression force","zh":"轴向压力"},{"phrase":"bolt compression force","zh":"螺栓压紧力"},{"phrase":"maximum compression force","zh":"最大压缩力"},{"phrase":"compression force on the joint","zh":"接头所受压力"}],"forms":[{"label":"单数","form":"compression force"},{"label":"复数","form":"compression forces"},{"label":"动词搭配","form":"apply compression force"},{"label":"相关形容词","form":"compressive"},{"label":"相关名词","form":"compression"}],"derivatives":[{"word":"compression","pos":"n.","zh":"本词组的前半部分，义为「压缩；压力」"},{"word":"compressive","pos":"adj.","zh":"由前半部分加表示性质的形容词尾构成，义为「抗压的」"},{"word":"compress","pos":"v.","zh":"由前半部分去掉名词词尾得到，义为「压缩」"},{"word":"force","pos":"n./v.","zh":"本词组的后半部分，义为「力；迫使」"},{"word":"forceful","pos":"adj.","zh":"由后半部分加表示性质的形容词尾构成，义为「有力的」"}],"senses":[{"no":"01","title":"Force pushing a member together","titleCN":"压在构件上的压缩力","definition":"the force applied along the axis of a structural member so that it tends to shorten","definitionCN":"沿构件轴线施加、使其趋于缩短的力","example":"The compression force on the column is constant.","exampleCN":"柱子所受的压缩力是恒定的。","why":"Compression names the pressing state and force names the push, so the pair means the push that shortens a member.","whyCN":"前半指压紧状态，后半指推力，合起来就是使构件缩短的那股推力。"},{"no":"02","title":"The load in a crush test","titleCN":"压缩试验中施加的载荷","definition":"the load a testing machine applies to a specimen between two platens","definitionCN":"试验机通过两块压板施加到试样上的载荷","example":"The compression force was increased at one millimetre per minute.","exampleCN":"压缩力以每分钟一毫米的速度增加。","why":"A test needs a measured push, and the compound names exactly that controlled input.","whyCN":"试验需要一股可测量的推力，这个词组正好指那种受控输入。"},{"no":"03","title":"The clamping push of a press","titleCN":"压机或夹具的压紧力","definition":"the force a press, clamp or hydraulic cylinder uses to hold or shape a workpiece","definitionCN":"压机、夹具或液压缸用来夹持或成形工件的力","example":"Too little compression force let the part slip.","exampleCN":"压紧力不足使零件滑动了。","why":"Holding and forming both depend on a push from outside, and the phrase covers both jobs.","whyCN":"夹持与成形都依赖外部的推力，这个词组两者都覆盖。"},{"no":"04","title":"The preload in a bolted joint","titleCN":"螺栓连接的预紧力","definition":"the force that keeps the clamped parts of a joint pressed tightly together","definitionCN":"使接头中被夹紧的零件保持紧密贴合的压力","example":"The compression force in the joint prevents fatigue loosening.","exampleCN":"接头的压紧力能防止疲劳松动。","why":"A bolt works by stretching and pressing, and the pressing half is what the phrase names.","whyCN":"螺栓靠拉伸与压紧工作，这个词组指的是压紧的那一半。"},{"no":"05","title":"Pressure in a soil layer","titleCN":"土体所受的压缩力","definition":"the vertical or lateral force that consolidates soil or rock in the ground","definitionCN":"使地下土体或岩体固结的竖向或侧向力","example":"The compression force from the new fill settled the clay.","exampleCN":"新填土带来的压缩力使黏土沉降。","why":"Geotechnics treats the ground as a material being squeezed, and the phrase applies unchanged.","whyCN":"岩土工程把地层当作被挤压的材料，这个词组原样适用。"},{"no":"06","title":"Load on bone or joint","titleCN":"骨骼或关节承受的压缩负荷","definition":"the force that presses along a bone or through a joint during standing or impact","definitionCN":"站立或受冲击时沿骨骼或穿过关节的压紧力","example":"Running triples the compression force at the knee.","exampleCN":"跑步会使膝关节的压缩力增至三倍。","why":"Bone is a structure, and biomechanics borrows the engineer's phrase for the load it carries.","whyCN":"骨骼是一种结构，生物力学借用了工程师的这个词组来描述它承受的负荷。"},{"no":"07","title":"The force of a crash","titleCN":"碰撞挤压时的压缩力","definition":"the force produced when two bodies are driven together in a collision","definitionCN":"两个物体在碰撞中被相互压近时产生的力","example":"The bumper absorbs the compression force of the impact.","exampleCN":"保险杠吸收撞击产生的压缩力。","why":"Impact is the most brutal compression, and crash analysis needs a name for that push.","whyCN":"撞击是最猛烈的压缩，碰撞分析需要为那股推力命名。"},{"no":"08","title":"The confining push in a rock test","titleCN":"岩石试验中的围压","definition":"the all-round compressive force applied to a rock or soil specimen in a triaxial test","definitionCN":"三轴试验中对岩石或土样四周施加的压缩力","example":"The compression force around the core was held at ten megapascals.","exampleCN":"岩芯周围的压缩力保持在十兆帕。","why":"Confining pressure is a compression force applied from every side, and the phrase is literal.","whyCN":"围压就是从各个方向施加的压缩力，这个词组是字面用法。"}],"etymology":{"intro":{"en":"Compression force joins a Latin pressing noun to a word for strength that came through French. The compound itself is a modern technical term rather than a classical phrase.","cn":"这个复合词把拉丁语表示「压」的名词与一个经法语而来的「力量」词接在一起。复合形式本身是现代技术术语，并非古典词组。"},"items":[{"era":"LATIN COMPRIMERE","en":"Compression goes back to comprimere, to press together, built from com, together, and premere, to press.","cn":"表示压缩的一半可追到 comprimere「压到一起」，由 com「一起」与 premere「压」构成。"},{"era":"LATIN FORTIS","en":"Force comes from fortis, strong, through the Vulgar Latin noun fortia, strength.","cn":"表示力的一半来自 fortis「强的」，经俗拉丁语名词 fortia「力量」而来。"},{"era":"FRENCH FORCE","en":"Old French force carried both the sense of strength and of a body of armed men into English.","cn":"古法语 force 把「力量」与「一队武装人员」两个意思一并带入英语。"},{"era":"MECHANICS","en":"The pairing of compression with force is a modern engineering usage, fixed when stress analysis needed precise labels; the exact date is uncertain and falls in the period when stress analysis acquired its technical vocabulary.","cn":"把「压缩」与「力」配对是现代工程用法，在应力分析需要精确标签时固定下来；确切年代不确定，只能定在应力分析形成专门术语的时期。"},{"era":"TEST STANDARDS","en":"Testing standards made the phrase routine for the load applied between platens or around a specimen.","cn":"试验标准使这个词组成为表示压板之间或试样周围载荷的常规说法。"},{"era":"BIOMECHANICS","en":"The twentieth century extended the phrase to bone and joint loading, where engineering and medicine share a vocabulary.","cn":"二十世纪把这个词组扩展到骨骼与关节负荷，工程与医学在这里共享一套词汇。"}]},"similar":{"note":{"en":"The first group looks or sounds like compression force; the second group names neighbouring ideas about pushing loads.","cn":"第一组在形音上与「compression force」相近；第二组是与「压力载荷」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compression","ipa":"/kəmˈpreʃn/","tag":"same root","definition":"The act or state of being pressed, without naming the force itself.","definitionCN":"指被压的动作或状态，本身不指那股力。"},{"word":"compressive","ipa":"/kəmˈpresɪv/","tag":"same root","definition":"The adjective for force or stress that presses material together.","definitionCN":"指把材料压拢的力或应力的形容词。"},{"word":"compress","ipa":"/kəmˈpres/","tag":"same root","definition":"The verb for squeezing or shortening something.","definitionCN":"指挤压或缩短某物的动词。"},{"word":"tension force","ipa":"/ˈtenʃn fɔːs/","tag":"opposite phrase","definition":"The pulling counterpart that tends to lengthen a member.","definitionCN":"指趋于拉长构件的对应拉力。"},{"word":"compression ratio","ipa":"/kəmˈpreʃn ˈreɪʃiəʊ/","tag":"related phrase","definition":"The proportion by which a volume is reduced, not a force at all.","definitionCN":"指体积被缩小的比例，与力无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"axial load","ipa":"/ˈæksiəl ləʊd/","tag":"near meaning","definition":"A force acting along the centre line of a member, whether pushing or pulling.","definitionCN":"指沿构件中线作用的力，推或拉都可以。"},{"word":"compressive stress","ipa":"/kəmˈpresɪv stres/","tag":"near meaning","definition":"The compression force divided by the area over which it acts.","definitionCN":"指压缩力除以它作用的面积。"},{"word":"preload","ipa":"/ˌpriːˈləʊd/","tag":"near meaning","definition":"The force deliberately built into a joint before it carries service load.","definitionCN":"指接头在承受工作载荷前预先建立的力。"},{"word":"clamping force","ipa":"/ˈklæmpɪŋ fɔːs/","tag":"near meaning","definition":"The push a clamp or mould uses to hold parts in place.","definitionCN":"指夹具或模具用来固定零件的推力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real pressing and strength sources, the real test vocabulary and real joint phrases.","cn":"正常联想使用真实的「压」与「力量」来源、真实试验词汇与真实接头说法。"},"normal":[{"en":"Compression supplies the direction of the push and force supplies the push itself.","cn":"前半给出推的方向，后半给出推力本身。"},{"en":"Compression force and tension force are the two axial opposites.","cn":"压缩力与拉力是轴向的两个反面。"},{"en":"Compressive stress is the same force divided by area.","cn":"压应力就是同一个力除以面积。"},{"en":"Bolt compression force is the preload that keeps a joint tight.","cn":"螺栓压紧力就是让接头保持紧密的预紧力。"},{"en":"The compression test is where the phrase is measured on a specimen.","cn":"压缩试验就是在试样上量出这个词组的地方。"}],"abstract":[{"en":"Compression force is a push that the material must answer with its own stiffness.","cn":"压缩力是一股推力，材料必须用自己的刚度来回答。"},{"en":"A joint stays tight because a hidden force never stops pressing.","cn":"接头之所以紧密，是因为一股看不见的力从未停止压着。"},{"en":"Bone and bridge answer the same question in the same units.","cn":"骨骼与桥梁用同样的单位回答同一个问题。"}]},"examples":[{"en":"The compression force on the pier doubled after the deck was widened.","cn":"桥面加宽后，桥墩所受的压缩力翻倍。"},{"en":"Increase the compression force slowly to avoid a brittle failure.","cn":"缓慢增加压缩力，以避免脆性破坏。"},{"en":"The knee feels the compression force of every landing.","cn":"每次落地，膝关节都承受压缩力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"前半意为压紧，后半意为力——压着构件的力：压缩力","word":"compression force"},"root":"前半 compression 来自拉丁语 comprimere「压到一起」（com-「一起」+ premere「压」）；后半 force 来自拉丁语 fortis「强的」经俗拉丁语 fortia「力量」、古法语 force 进入英语。两者合为现代工程术语，用于构件、试验、接头、土体、骨骼与碰撞；固定年代来源不确定。","sensesIntro":{"en":"Eight senses apply the same push in different places: a member, a test specimen, a press, a bolted joint, soil, a joint in the body, a crash, and a confined rock core.","cn":"八个义项把同一股推力用在不同的地方：构件、试样、压机、螺栓接头、土体、人体关节、碰撞与受围压的岩芯。"},"semanticMap":{"core":{"en":"CORE IMAGE: a concrete cube sits between two platens while the gauge climbs.","cn":"核心意象：混凝土立方体夹在两块压板之间，表盘读数一路上升。"},"chain":["TWO PLATENS","CONTACT","FORCE RISES","MEMBER SHORTENS","CRACK APPEARS","FAILURE RECORDED"],"branches":[{"senses":"01 · 04","en":"THE HELD STRUCTURE: a column pushed along its axis, and a joint kept tight by preload.","cn":"被压住的结构：沿轴受压的柱子，以及靠预紧力保持紧密的接头。"},{"senses":"02","en":"THE MEASURED INPUT: a test machine applying a controlled push to a specimen.","cn":"被量出的输入：试验机对试样施加受控推力。"},{"senses":"03 · 06","en":"THE WORKING BODY: a press holding a workpiece, and a knee taking each landing.","cn":"工作的身体：压机夹住工件，以及承受每次落地的膝盖。"},{"senses":"05 · 08","en":"THE SQUEEZED GROUND: soil consolidating under fill, and rock held from every side.","cn":"被压的地层：填土下固结的土，以及四周受压的岩石。"},{"senses":"07","en":"THE CRASH PUSH: two bodies driven together in a fraction of a second.","cn":"碰撞推力：两个物体在几分之一秒内被压到一起。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin pressing noun with a Latin strength noun carried by French; both halves remain productive.","cn":"这个词组把拉丁语表示「压」的名词与一个经法语而来的「力量」名词合并，两半都仍有构词能力。"},"latinIntro":{"en":"Latin premere and fortis are the two real sources; the English compound itself is modern and has no Latin equivalent.","cn":"拉丁语的 premere 与 fortis 是两个真实来源；英语复合词本身是现代产物，没有对应的拉丁词组。"},"items":[{"word":"premere","structure":"Latin verb","meaning":"to press","meaningCN":"压","example":"It supplies the pressing half.","exampleCN":"它提供「压」的那一半。"},{"word":"com-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"It makes the pressing a pressing together.","exampleCN":"它使「压」成为「压到一起」。"},{"word":"fortis","structure":"Latin adjective","meaning":"strong","meaningCN":"强的","example":"It supplies the force half.","exampleCN":"它提供「力」的那一半。"},{"word":"fortia","structure":"Vulgar Latin noun","meaning":"strength","meaningCN":"力量","example":"The noun stands behind the French word.","exampleCN":"这个名词位于法语词之后。"},{"word":"force","structure":"Old French noun from fortia","meaning":"strength, a push","meaningCN":"力量；推力","example":"It carries the strength into English.","exampleCN":"它把「力量」带入英语。"},{"word":"-ive","structure":"adjective ending","meaning":"having the function of","meaningCN":"具有……作用的","example":"It builds compressive.","exampleCN":"它构成 compressive。"},{"word":"-ful","structure":"adjective ending","meaning":"full of","meaningCN":"充满……的","example":"It builds forceful.","exampleCN":"它构成 forceful。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act of","meaningCN":"……的动作","example":"It builds compression.","exampleCN":"它构成 compression。"},{"word":"compressive stress","structure":"adjective plus noun","meaning":"force divided by area","meaningCN":"力除以面积","example":"The phrase turns force into intensity.","exampleCN":"这个说法把力变成强度。"}],"latinEntries":[{"word":"premere","structure":"Latin verb","meaning":"to press","meaningCN":"压"},{"word":"fortis","structure":"Latin adjective","meaning":"strong","meaningCN":"强的"},{"word":"fortia","structure":"Vulgar Latin noun","meaning":"strength","meaningCN":"力量"}],"derivatives":[{"word":"compression","pos":"n.","zh":"本词组前半部分，义为「压缩；压力」"},{"word":"compressive","pos":"adj.","zh":"由前半部分加表示性质的形容词尾构成，义为「抗压的」"},{"word":"force","pos":"n./v.","zh":"本词组后半部分，义为「力；迫使」"},{"word":"forceful","pos":"adj.","zh":"由后半部分加表示性质的形容词尾构成，义为「有力的」"},{"word":"preload","pos":"n.","zh":"由表示「预先」的前缀加表示载荷的词构成，义为「预紧力」"}]}},{"word":"deformation","ipa_uk":"/ˌdiːfɔːˈmeɪʃn/","ipa_us":"/ˌdiːfɔːrˈmeɪʃn/","definition_zh":"形变；变形；畸变；失真；地质变形","definition_en":"a change in the shape or size of an object or material, or a distortion of form, data or the ground","core_image":"梁在加载后中部下垂，千分表读数增加，卸载后指针回弹了一部分","scene":"梁在加载后中部下垂，千分表读数增加，卸载后指针回弹了一部分。The dial gauge records the deformation of the beam under load.","sceneCN":"这里指构件受力后形状发生的改变（第 1 个义项：形状或尺寸的变化）；句意为千分表记录了梁在载荷下的形变。图中可辨识物件：梁、加载砝码、千分表、支座、下垂曲线。","pos":[{"tag":"n.","zh":"形变；变形；畸变；失真"}],"collocations":[{"phrase":"elastic deformation","zh":"弹性形变"},{"phrase":"plastic deformation","zh":"塑性形变"},{"phrase":"permanent deformation","zh":"永久变形"},{"phrase":"structural deformation","zh":"结构变形"},{"phrase":"deformation under load","zh":"载荷下的形变"},{"phrase":"image deformation","zh":"图像畸变"}],"forms":[{"label":"单数","form":"deformation"},{"label":"复数","form":"deformations"},{"label":"动词","form":"deform"},{"label":"形容词","form":"deformed"},{"label":"施动者","form":"deformer"},{"label":"可变形性","form":"deformability"}],"derivatives":[{"word":"deform","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「使变形」"},{"word":"deformed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「变形的；畸形的」"},{"word":"deformable","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可变形的」"},{"word":"deformity","pos":"n.","zh":"由同一词干加表示状态的名词尾构成，义为「畸形；缺陷」"},{"word":"deformability","pos":"n.","zh":"由可变形形容词加表示性质的名词尾构成，义为「可变形性」"}],"senses":[{"no":"01","title":"A change of shape","titleCN":"形状或尺寸的改变","definition":"any change in the shape or dimensions of a body, usually caused by force or heat","definitionCN":"物体形状或尺寸的任何改变，通常由力或热引起","example":"Deformation began as soon as the load was applied.","exampleCN":"载荷一加上，形变就开始了。","why":"The Latin verb meant to put out of shape, and the noun simply names that result.","whyCN":"拉丁动词意为「使失去形状」，这个名词就指那个结果。"},{"no":"02","title":"Recoverable elastic change","titleCN":"可恢复的弹性形变","definition":"deformation that disappears when the load is removed because the material returns to its original shape","definitionCN":"载荷去除后消失、材料恢复原状的形变","example":"Elastic deformation of the spring stayed within two millimetres.","exampleCN":"弹簧的弹性形变保持在两毫米以内。","why":"A material can bend and come back, and engineers separate that reversible part from the rest.","whyCN":"材料可以弯了再回来，工程师把这可逆的部分与其余部分分开。"},{"no":"03","title":"Permanent plastic change","titleCN":"不可恢复的塑性形变","definition":"deformation that remains after the load is removed because the material has yielded","definitionCN":"载荷去除后仍然存在、因材料已屈服的形变","example":"Plastic deformation left a dent in the plate.","exampleCN":"塑性形变在板上留下了一个凹坑。","why":"Once a material yields, its atoms have moved to new positions, and the change is written into the object.","whyCN":"材料一旦屈服，原子已移到新位置，改变就写进了物体本身。"},{"no":"04","title":"The sag of a structure","titleCN":"结构的下垂或变形","definition":"the deflection or distortion of a beam, frame or building under service loads","definitionCN":"梁、框架或建筑在工作载荷下的挠曲或扭曲","example":"The deformation of the beam was visible to the eye.","exampleCN":"梁的变形肉眼可见。","why":"Large structures make small strains visible as a sag, and the same noun covers that scale.","whyCN":"大型结构把微小的应变变成看得见的下垂，同一个名词覆盖这个尺度。"},{"no":"05","title":"A change in the ground","titleCN":"地壳或地层的变形","definition":"the folding, faulting or settling of rock and soil over geological time","definitionCN":"岩石与土壤在地质时间尺度上的褶皱、断裂或沉降","example":"Deformation along the fault raised the ridge.","exampleCN":"沿断层的变形使山脊抬升。","why":"The earth deforms like a solid under stress, only slowly, and geology kept the mechanical word.","whyCN":"地球像受力固体一样变形，只是很慢，地质学保留了这个力学词。"},{"no":"06","title":"A twisted outward form","titleCN":"外形的扭曲走样","definition":"a distorted or unnatural shape, especially one that looks wrong to the eye","definitionCN":"扭曲或不自然的形状，尤指看起来不对劲的外形","example":"Heat caused a slight deformation of the plastic cover.","exampleCN":"受热使塑料外壳出现轻微变形。","why":"The everyday eye judges shape, and anything out of true is called deformed.","whyCN":"日常眼光判断形状，任何不正的东西都被称为变形。"},{"no":"07","title":"Distortion in an image or signal","titleCN":"图像或信号的畸变","definition":"a unwanted change in the shape or values of an image, waveform or dataset","definitionCN":"图像、波形或数据集的形状或数值发生的不希望的变化","example":"Lens deformation made the straight lines curve.","exampleCN":"镜头畸变使直线弯曲。","why":"An image has a shape too, and any deviation from the true shape is called deformation.","whyCN":"图像也有形状，任何偏离真实形状的变化都被称为形变。"},{"no":"08","title":"A malformed living form","titleCN":"生物体的畸形","definition":"an abnormal shape of a body part caused by growth, injury or disease","definitionCN":"由生长、损伤或疾病造成的身体部位形状异常","example":"The x-ray showed a deformation of the joint.","exampleCN":"X 光片显示出关节的畸形。","why":"Medicine borrowed the word for shape that has gone wrong in a living body.","whyCN":"医学借这个词指活体上出了错的形状。"}],"etymology":{"intro":{"en":"Deformation comes from Latin deformatio, from deformare, to put out of shape, built from de, away from, and forma, form or shape. French carried the noun into English.","cn":"这个词来自拉丁语 deformatio，源自动词 deformare「使失去形状」，由 de「离开」与 forma「形状」构成。法语把名词带入英语。"},"items":[{"era":"LATIN FORMA","en":"Forma meant shape, form or mould, and it is the element that makes the word about outward figure.","cn":"这个词意为形状、形式或模具，是使这个词关乎外形的成分。"},{"era":"LATIN DE-","en":"The prefix meant away from or down, and here it marks a departure from the proper shape.","cn":"这个前缀意为「离开、向下」，在这里标出偏离应有形状。"},{"era":"LATIN DEFORMARE","en":"The verb meant to shape badly, disfigure or mar, and it was used of faces and objects alike.","cn":"这个动词意为弄坏形状、毁容、损毁，面孔与物件都可用。"},{"era":"LATIN DEFORMATIO","en":"The noun named the act or the resulting bad shape, and French deformation carried it into English.","cn":"这个名词指动作或由此产生的坏形状，法语 deformation 把它带入英语。"},{"era":"MECHANICS","en":"Engineering made the word measurable as a change of dimensions; the first attestation date of that specialization is uncertain.","cn":"工程学使这个词成为可测量的尺寸变化；这一专门化的首见年代不确定。"},{"era":"GEOLOGY AND IMAGING","en":"Geology applied it to rock over long time, and imaging to lenses and signals in the twentieth century.","cn":"地质学把它用于长时间尺度上的岩石，二十世纪成像技术又把它用于镜头与信号。"}]},"similar":{"note":{"en":"The first group looks or sounds like deformation; the second group names neighbouring ideas of shape change.","cn":"第一组在形音上与「deformation」相近；第二组是与「形状改变」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deform","ipa":"/dɪˈfɔːm/","tag":"same root","definition":"The verb for changing or spoiling the shape of something.","definitionCN":"指改变或弄坏某物形状的动词。"},{"word":"deformed","ipa":"/dɪˈfɔːmd/","tag":"same root","definition":"Having a shape that is no longer correct or natural.","definitionCN":"指形状已不正确或不自然的。"},{"word":"deformity","ipa":"/dɪˈfɔːməti/","tag":"same root","definition":"A malformation of a body part, usually present from birth or growth.","definitionCN":"指身体部位的畸形，通常源于先天或生长。"},{"word":"formation","ipa":"/fɔːˈmeɪʃn/","tag":"same root","definition":"The act of forming something, from the same shape word without the negative prefix.","definitionCN":"指形成某物的动作，共享「形状」词干但没有否定前缀。"},{"word":"information","ipa":"/ˌɪnfəˈmeɪʃn/","tag":"different root","definition":"Knowledge or data; it contains the shape word but means something else entirely.","definitionCN":"指知识或数据；含有「形状」词干，但意思完全不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"distortion","ipa":"/dɪˈstɔːʃn/","tag":"near meaning","definition":"A twisted or inaccurate shape, especially of an image or a statement.","definitionCN":"指扭曲或不准确的形状，尤指图像或陈述。"},{"word":"deflection","ipa":"/dɪˈflekʃn/","tag":"near meaning","definition":"The bending of a beam or plate under load.","definitionCN":"指梁或板在载荷下的弯曲。"},{"word":"strain","ipa":"/streɪn/","tag":"near meaning","definition":"The change in length divided by the original length.","definitionCN":"指长度变化量与原长度之比。"},{"word":"warping","ipa":"/ˈwɔːpɪŋ/","tag":"near meaning","definition":"A twisting out of shape, especially from heat or moisture.","definitionCN":"指扭曲变形，尤因受热或受潮。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real away-from-shape source, the real mechanics family and real test phrases.","cn":"正常联想使用真实的「离开形状」来源、真实力学同族词与真实试验搭配。"},"normal":[{"en":"De means away and forma means shape, so deformation is a departure from shape.","cn":"前缀意为离开，词根意为形状，所以形变就是离开原来的形状。"},{"en":"Elastic deformation comes back, plastic deformation stays.","cn":"弹性形变会回来，塑性形变会留下。"},{"en":"Deform, deformed and deformity are the everyday family.","cn":"使变形、变形的与畸形是日常同族词。"},{"en":"Structural deformation is measured with a dial gauge on site.","cn":"结构变形在工地上用千分表测量。"},{"en":"Image deformation is the same departure from shape, drawn by a lens.","cn":"图像畸变是同一个「离开形状」，只是由镜头画出。"}],"abstract":[{"en":"Deformation is a record of force that the object could not ignore.","cn":"形变是物体无法忽视的那股力留下的记录。"},{"en":"A structure that never deforms is either unloaded or lying.","cn":"从不形变的结构，要么没受力，要么在说谎。"},{"en":"The ground deforms slowly enough that a lifetime looks like stillness.","cn":"大地变形得足够慢，慢到一生看起来都像静止。"}]},"examples":[{"en":"The test records deformation every tenth of a second.","cn":"试验每十分之一秒记录一次形变。"},{"en":"Permanent deformation meant the part had to be replaced.","cn":"永久变形意味着这个零件必须更换。"},{"en":"Geologists mapped deformation across the whole valley.","cn":"地质学家测绘了整个谷地的变形。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迪福美申」——形状被「迪」地一下改了，不再美：形变、变形","word":"deformation"},"root":"拉丁语 deformatio ← deformare「使失去形状」← de-「离开」+ forma「形状」；法语 deformation 带入英语。工程学使之成为可测量的尺寸变化，地质学用于岩层，二十世纪成像技术用于镜头与信号；专门化的确切年代来源不确定。同族有 formation 与 information，但后者语义已远。","sensesIntro":{"en":"Eight senses all depart from a proper shape: a general change, elastic return, plastic permanence, a sagging beam, folded rock, a warped cover, a bent image and a malformed joint.","cn":"八个义项都偏离了应有形状：一般变化、弹性回弹、塑性残留、下垂的梁、褶皱的岩层、走样的外壳、弯曲的图像与畸形的关节。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beam sags under weights and the dial needle moves away from zero.","cn":"核心意象：梁在砝码下下垂，千分表指针离开零位。"},"chain":["TRUE SHAPE","FORCE APPLIED","SHAPE DEPARTS","MEASURED CHANGE","RETURNS OR STAYS","NEW FORM"],"branches":[{"senses":"01","en":"THE GENERAL CHANGE: any departure of size or shape from what it was.","cn":"一般变化：尺寸或形状偏离原来的任何情况。"},{"senses":"02 · 03","en":"THE TWO OUTCOMES: a change that springs back and a change that remains.","cn":"两种结果：会弹回去的变化，与留下来的变化。"},{"senses":"04","en":"THE VISIBLE SAG: a beam or frame that bends enough to be seen.","cn":"看得见的下垂：梁或框架弯到肉眼可见。"},{"senses":"05 · 06","en":"THE OUTER WORLD: rock folded over ages, and a cover warped by heat.","cn":"外部世界：经年褶皱的岩石，以及受热走样的外壳。"},{"senses":"07 · 08","en":"THE DISTORTED FORM: a lens bending straight lines and a joint grown out of true.","cn":"扭曲的形态：镜头把直线弄弯，以及长歪了的关节。"}]},"affixes":{"intro":{"en":"Deformation is a Latin noun built on the word for shape, with a negative prefix that marks departure from it.","cn":"这是一个建立在「形状」一词上的拉丁名词，其否定前缀标出对形状的偏离。"},"latinIntro":{"en":"Latin forma and deformare are the real sources; the noun deformatio is directly attested, and the deeper root of forma is reconstructed.","cn":"拉丁语的 forma 与 deformare 是真实来源；名词 deformatio 有直接文献，forma 更深词根属重构。"},"items":[{"word":"forma","structure":"Latin noun","meaning":"shape, form, mould","meaningCN":"形状；形式；模具","example":"The noun supplies the shape at the centre.","exampleCN":"这个名词提供了中心的「形状」。"},{"word":"de-","structure":"Latin prefix","meaning":"away from, down","meaningCN":"离开；向下","example":"The prefix marks the departure.","exampleCN":"这个前缀标出偏离。"},{"word":"deformare","structure":"de- plus forma","meaning":"to put out of shape","meaningCN":"使失去形状","example":"The verb is the direct source of the English family.","exampleCN":"这个动词是英语词族的直接来源。"},{"word":"deformatio","structure":"Latin noun from deformare","meaning":"a disfiguring","meaningCN":"毁形；变形","example":"The attested noun passed through French.","exampleCN":"这个有文献的名词经法语传来。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result of","meaningCN":"动作或结果","example":"The ending builds the English noun.","exampleCN":"这个词尾构成英语名词。"},{"word":"-ed","structure":"completed-state ending","meaning":"having a bad shape","meaningCN":"形状已坏的","example":"It builds deformed.","exampleCN":"它构成 deformed。"},{"word":"-ity","structure":"quality noun ending","meaning":"the state of being","meaningCN":"……的状态","example":"It builds deformity.","exampleCN":"它构成 deformity。"},{"word":"-able","structure":"adjective ending","meaning":"can be","meaningCN":"可以被……的","example":"It builds deformable.","exampleCN":"它构成 deformable。"},{"word":"formatio","structure":"Latin noun from formare","meaning":"a shaping","meaningCN":"成形","example":"The positive noun shows the same shape stem without the prefix.","exampleCN":"肯定名词显示同一个「形状」词干，只是没有前缀。"}],"latinEntries":[{"word":"forma","structure":"Latin noun","meaning":"shape, form","meaningCN":"形状；形式"},{"word":"deformare","structure":"Latin verb","meaning":"to put out of shape","meaningCN":"使失去形状"},{"word":"deformatio","structure":"Latin noun","meaning":"a disfiguring","meaningCN":"毁形"},{"word":"formatio","structure":"Latin noun","meaning":"a shaping","meaningCN":"成形"}],"derivatives":[{"word":"deform","pos":"v.","zh":"由该名词去掉名词词尾得到，义为「使变形」"},{"word":"deformed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「变形的」"},{"word":"deformable","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可变形的」"},{"word":"deformity","pos":"n.","zh":"由同一词干加表示状态的名词尾构成，义为「畸形」"},{"word":"deformability","pos":"n.","zh":"由可变形形容词加表示性质的名词尾构成，义为「可变形性」"}]}},{"word":"deform","ipa_uk":"/dɪˈfɔːm/","ipa_us":"/dɪˈfɔːrm/","definition_zh":"使变形；压坏形状；使扭曲；使失真；使成畸形","definition_en":"to change or spoil the shape of something, or to make a material, image or body part lose its proper form","core_image":"夹具夹得太紧，薄壁圆管被压扁了一点，圆度计读出偏差","scene":"夹具夹得太紧，薄壁圆管被压扁了一点，圆度计读出偏差。Too much clamping pressure can deform the thin tube.","sceneCN":"这里指外力把物体原来的形状压坏（第 1 个义项：使形状改变）；句意为过大的夹紧力会使薄壁管变形。图中可辨识物件：薄壁管、夹具、圆度计、压力表、扁痕。","pos":[{"tag":"v.","zh":"使变形；使扭曲；使失真"}],"collocations":[{"phrase":"deform the shape","zh":"使形状变形"},{"phrase":"deform under load","zh":"在载荷下变形"},{"phrase":"deform a material","zh":"使材料变形"},{"phrase":"deform the image","zh":"使图像失真"},{"phrase":"deform the truth","zh":"歪曲事实"},{"phrase":"deform the surface","zh":"使表面变形"}],"forms":[{"label":"动词原形","form":"deform"},{"label":"第三人称单数","form":"deforms"},{"label":"过去式","form":"deformed"},{"label":"过去分词","form":"deformed"},{"label":"现在分词","form":"deforming"},{"label":"名词","form":"deformation"}],"derivatives":[{"word":"deformation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「形变；变形」"},{"word":"deformed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「变形的；畸形的」"},{"word":"deformable","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可变形的」"},{"word":"deformity","pos":"n.","zh":"由同一词干加表示状态的名词尾构成，义为「畸形」"},{"word":"deformer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「使变形的工具或人」"}],"senses":[{"no":"01","title":"To change a shape by force","titleCN":"用外力使形状改变","definition":"to change the shape or dimensions of an object by applying force, heat or pressure","definitionCN":"通过施加力、热或压力来改变物体的形状或尺寸","example":"The clamp can deform the pipe if it is overtightened.","exampleCN":"夹具拧得太紧会使管子变形。","why":"The Latin verb meant to put out of shape, and the physical act remains the base of every other sense.","whyCN":"拉丁动词意为「使失去形状」，这个物理动作是其余各义的基础。"},{"no":"02","title":"To bend out of true","titleCN":"自身弯曲走形","definition":"to bend or sag so that a body no longer has its intended shape","definitionCN":"弯曲或下垂，使物体不再具有原本设定的形状","example":"The shelf began to deform under the weight.","exampleCN":"搁板在重压下开始变形。","why":"An object can deform without an obvious hand on it, and the verb covers that slow sag.","whyCN":"物件可以在没有明显外力的情况下变形，这个动词覆盖那种缓慢的下垂。"},{"no":"03","title":"To shape metal by force","titleCN":"用外力加工成形","definition":"to change the shape of a material deliberately as part of a forming process","definitionCN":"作为成形工艺的一部分，有意改变材料的形状","example":"The press deforms the sheet into a shallow bowl.","exampleCN":"压机把板料压成浅碗形。","why":"In metal work, deformation is not damage but the intended operation, and the verb is neutral.","whyCN":"在金属加工里，变形不是损坏而是预期操作，这个动词是中性词。"},{"no":"04","title":"To distort a form","titleCN":"使外形扭曲走样","definition":"to spoil the natural or intended outline of something so that it looks wrong","definitionCN":"破坏某物自然或预期的轮廓，使其看起来不对劲","example":"Heat deformed the plastic housing.","exampleCN":"受热使塑料外壳走了形。","why":"The eye judges outline, and anything bent out of its true line reads as deformed.","whyCN":"眼睛判断轮廓，任何弯离正确线条的东西都显得变形。"},{"no":"05","title":"To make a body part malformed","titleCN":"使身体部位成畸形","definition":"to cause a part of a living body to grow or set in an abnormal shape","definitionCN":"使活体的某一部分长成或固定成异常形状","example":"The injury deformed the joint over time.","exampleCN":"那次损伤随时间使关节变形。","why":"Medicine uses the verb for shape that has gone wrong in tissue, whether from growth or trauma.","whyCN":"医学用这个动词指组织中出了错的形状，无论源于生长还是创伤。"},{"no":"06","title":"To distort an image or signal","titleCN":"使图像或信号失真","definition":"to alter an image, waveform or dataset so that it no longer represents the original faithfully","definitionCN":"改变图像、波形或数据集，使其不再忠实反映原物","example":"A cheap lens deforms the edges of the picture.","exampleCN":"廉价镜头会使画面边缘失真。","why":"A picture has a shape, and a lens that bends it is said to deform it.","whyCN":"画面有形状，把它弄弯的镜头就被说成使它变形。"},{"no":"07","title":"To bend the ground","titleCN":"使地表或岩层变形","definition":"to cause rock or soil to fold, subside or shift under pressure","definitionCN":"在压力下使岩石或土壤褶皱、沉降或位移","example":"The excavation deformed the slope above the road.","exampleCN":"开挖使公路上方的坡体变形。","why":"The ground behaves as a solid under long pressure, and geology uses the same verb.","whyCN":"地层在长期压力下像固体一样行为，地质学用同一个动词。"},{"no":"08","title":"To twist the truth","titleCN":"歪曲事实或意义","definition":"to distort a statement, record or meaning so that it misrepresents what happened","definitionCN":"歪曲陈述、记录或含义，使其错误地呈现事实","example":"The summary deforms what the report actually says.","exampleCN":"这份摘要歪曲了报告的实际内容。","why":"Meaning is given a shape, and bending it away from the truth is the same metaphor as bending metal.","whyCN":"意义被赋予形状，把它弯离事实与弯金属是同一个比喻。"}],"etymology":{"intro":{"en":"Deform comes from Latin deformare, to put out of shape, from de, away from, and forma, shape. English took the verb through French, and the technical senses grew out of the plain one.","cn":"这个词来自拉丁语 deformare「使失去形状」，由 de「离开」与 forma「形状」构成。英语经法语引入这个动词，技术义从朴素义发展而来。"},"items":[{"era":"LATIN FORMA","en":"Forma meant shape, form or mould, and it is the element that keeps the word about visible figure.","cn":"这个词意为形状、形式或模具，是使这个词始终关乎可见外形的成分。"},{"era":"LATIN DE-","en":"The prefix meant away from or down, and it marks the loss of the proper shape rather than a new one.","cn":"这个前缀意为「离开、向下」，标出的是失去原有形状，而不是获得新形状。"},{"era":"LATIN DEFORMARE","en":"The verb meant to shape badly, disfigure or mar, and it applied to faces, bodies and objects.","cn":"这个动词意为弄坏形状、毁容、损毁，可用于面孔、身体与物件。"},{"era":"FRENCH AND ENGLISH","en":"Old French deformar carried the verb into English, where it first described spoiled outward form.","cn":"古法语把这个动词带入英语，最初描述被破坏的外形。"},{"era":"METAL AND MECHANICS","en":"Industrial forming made the verb neutral, naming the intended change of shape; the first attestation date is uncertain.","cn":"工业成形使这个动词变成中性，指有意的形状改变；首见年代不确定。"},{"era":"IMAGING AND FIGURE","en":"The twentieth century extended the verb to lenses and signals, and older uses kept it for the body and for truth.","cn":"二十世纪把这个动词扩展到镜头与信号，较早的用法则把它留在身体与真相上。"}]},"similar":{"note":{"en":"The first group looks or sounds like deform; the second group names neighbouring ideas of bending and spoiling shape.","cn":"第一组在形音上与「deform」相近；第二组是与「弯曲、弄坏形状」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deformation","ipa":"/ˌdiːfɔːˈmeɪʃn/","tag":"same root","definition":"The noun for the change of shape or the resulting distorted form.","definitionCN":"指形状改变或由此产生的扭曲形态。"},{"word":"deformed","ipa":"/dɪˈfɔːmd/","tag":"same root","definition":"The adjective for something whose shape has been spoiled.","definitionCN":"指形状已被弄坏的形容词。"},{"word":"deformity","ipa":"/dɪˈfɔːməti/","tag":"same root","definition":"A bodily malformation, usually structural rather than caused by a single load.","definitionCN":"指身体畸形，通常是结构性的，而非单次载荷造成。"},{"word":"reform","ipa":"/rɪˈfɔːm/","tag":"same root","definition":"To improve or reshape something; it uses the shape word with a prefix meaning again.","definitionCN":"指改良或重塑某物；用同一个「形状」词干，前缀意为「再次」。"},{"word":"defame","ipa":"/dɪˈfeɪm/","tag":"different root","definition":"To damage someone's reputation; it looks close but comes from the word for fame.","definitionCN":"指损害他人名誉；形近，但来自表示「名声」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"distort","ipa":"/dɪˈstɔːt/","tag":"near meaning","definition":"To twist something out of its true shape or meaning.","definitionCN":"指把某物扭离真实形状或含义。"},{"word":"bend","ipa":"/bend/","tag":"near meaning","definition":"To make something curved rather than straight.","definitionCN":"指使某物由直变弯。"},{"word":"warp","ipa":"/wɑːp/","tag":"near meaning","definition":"To twist out of shape, especially through heat or moisture.","definitionCN":"指扭曲变形，尤因受热或受潮。"},{"word":"buckle","ipa":"/ˈbʌkl/","tag":"near meaning","definition":"To bend suddenly under compression, as a thin plate or rail does.","definitionCN":"指受压突然弯曲，如薄板或钢轨。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real away-from-shape source, the real family and real shop phrases.","cn":"正常联想使用真实的「离开形状」来源、真实同族词与真实车间说法。"},"normal":[{"en":"Deform is de plus form: take the form away.","cn":"deform 就是「去掉」加「形状」：把形状拿走。"},{"en":"Deformation is the noun, deformed the adjective, deformity the bodily form.","cn":"形变是名词，变形的 是形容词，畸形是身体形态。"},{"en":"Deform under load is the phrase on every material test.","cn":"在载荷下变形是每种材料试验上的说法。"},{"en":"A press deforms the sheet on purpose; a clamp deforms the pipe by mistake.","cn":"压机有意使板料变形，夹具却误使管子变形。"},{"en":"Reform uses the same shape stem with a prefix meaning again.","cn":"reform 用同一个「形状」词干，只是前缀意为「再次」。"}],"abstract":[{"en":"To deform is to leave a mark that the object did not choose.","cn":"使变形就是在物体上留下一个它没有选择的痕迹。"},{"en":"The same verb bends steel and bends a sentence.","cn":"同一个动词既弯钢，也弯句子。"},{"en":"A deformed truth is still the truth with its shape taken away.","cn":"被歪曲的事实，仍然是被拿走了形状的事实。"}]},"examples":[{"en":"Do not deform the seal when you fit the cover.","cn":"装端盖时不要使密封件变形。"},{"en":"The impact deformed the guard but saved the frame.","cn":"撞击使护板变形，却保住了框架。"},{"en":"A bad lens will deform the whole image.","cn":"劣质镜头会使整幅图像失真。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迪福姆」——把形状「迪」地改掉、不再有原来的形：使变形","word":"deform"},"root":"拉丁语 deformare「使失去形状」← de-「离开」+ forma「形状」，经法语进入英语。原义为毁坏外形，工业成形使它变成中性词，二十世纪又扩展到镜头与信号；各义定型的确切年代来源不确定。","sensesIntro":{"en":"Eight senses all take a shape away: by force, by sagging, by deliberate forming, by heat, by injury, by a lens, by excavation, and by a misleading summary.","cn":"八个义项都在拿走一个形状：用外力、靠下垂、有意成形、受热、受伤、镜头、开挖与误导性的摘要。"},"semanticMap":{"core":{"en":"CORE IMAGE: a clamp closes on a thin tube and the round section turns oval.","cn":"核心意象：夹具夹住薄壁管，圆截面变成椭圆。"},"chain":["TRUE FORM","FORCE OR HEAT","OUTLINE MOVES","ROUND BECOMES OVAL","CHANGE STAYS","MEANING BENDS"],"branches":[{"senses":"01 · 02","en":"THE LOADED BODY: a pipe squeezed by a clamp and a shelf sagging slowly.","cn":"受力之物：被夹具挤住的管子，以及慢慢下垂的搁板。"},{"senses":"03","en":"THE INTENDED FORMING: a press turning sheet into a bowl on purpose.","cn":"有意的成形：压机有意把板料压成碗。"},{"senses":"04 · 05","en":"THE SPOILED FORM: a housing warped by heat and a joint changed by injury.","cn":"被弄坏的形状：受热走样的外壳，以及受伤改变的关节。"},{"senses":"06 · 07","en":"THE DISTORTED WORLD: a lens bending edges, and a slope moving after excavation.","cn":"被扭曲的世界：镜头把边缘弄弯，以及开挖后移动的坡体。"},{"senses":"08","en":"THE BENT MEANING: a summary that takes the shape of the truth away.","cn":"被弯的意义：把事实形状拿走的摘要。"}]},"affixes":{"intro":{"en":"Deform is a Latin verb built on the word for shape, and its English family covers damage, medicine and images.","cn":"这是一个建立在「形状」一词上的拉丁动词，其英语词族覆盖损坏、医学与影像。"},"latinIntro":{"en":"Latin forma and the prefix de- are the real parts; the verb deformare is attested and is the direct source.","cn":"拉丁语的 forma 与前缀 de- 是真实构件；动词 deformare 有文献，是直接来源。"},"items":[{"word":"forma","structure":"Latin noun","meaning":"shape, form","meaningCN":"形状；形式","example":"The noun is the shape being lost.","exampleCN":"这个名词就是被失去的形状。"},{"word":"de-","structure":"Latin prefix","meaning":"away from","meaningCN":"离开","example":"The prefix marks the loss.","exampleCN":"这个前缀标出失去。"},{"word":"deformare","structure":"de- plus forma","meaning":"to put out of shape","meaningCN":"使失去形状","example":"The verb is attested in Latin.","exampleCN":"这个动词在拉丁语文献中有据。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result of","meaningCN":"动作或结果","example":"It builds deformation.","exampleCN":"它构成 deformation。"},{"word":"-ed","structure":"completed-state ending","meaning":"having lost its shape","meaningCN":"已失去形状的","example":"It builds deformed.","exampleCN":"它构成 deformed。"},{"word":"-able","structure":"adjective ending","meaning":"can be","meaningCN":"可以被……的","example":"It builds deformable.","exampleCN":"它构成 deformable。"},{"word":"-ity","structure":"quality noun ending","meaning":"the state of being","meaningCN":"……的状态","example":"It builds deformity.","exampleCN":"它构成 deformity。"},{"word":"-er","structure":"agent noun ending","meaning":"the thing that deforms","meaningCN":"使变形的人或物","example":"It builds deformer.","exampleCN":"它构成 deformer。"},{"word":"formare","structure":"Latin verb from forma","meaning":"to shape","meaningCN":"使成形","example":"The positive verb shows the same stem.","exampleCN":"肯定动词显示同一个词干。"}],"latinEntries":[{"word":"forma","structure":"Latin noun","meaning":"shape, form","meaningCN":"形状；形式"},{"word":"formare","structure":"Latin verb","meaning":"to shape","meaningCN":"使成形"},{"word":"deformare","structure":"Latin verb","meaning":"to put out of shape","meaningCN":"使失去形状"}],"derivatives":[{"word":"deformation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「形变」"},{"word":"deformed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「变形的」"},{"word":"deformable","pos":"adj.","zh":"由该动词加表示「可……的」的形容词尾构成，义为「可变形的」"},{"word":"deformity","pos":"n.","zh":"由同一词干加表示状态的名词尾构成，义为「畸形」"},{"word":"deformer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「使变形的工具」"}]}},{"word":"elasticity","ipa_uk":"/ˌiːlæˈstɪsəti/","ipa_us":"/ˌiːlæˈstɪsəti/","definition_zh":"弹性；回弹性；弹性系数；伸缩性；灵活性","definition_en":"the ability of a material to return to its original shape after being stretched or compressed, or the responsiveness of a quantity to a change in another","core_image":"橡皮筋被拉长到两倍，松手后立刻缩回原来的长度，没有留下永久变形","scene":"橡皮筋被拉长到两倍，松手后立刻缩回原来的长度，没有留下永久变形。Rubber shows elasticity when it returns to its original length after being stretched.","sceneCN":"这里指材料被拉伸后恢复原状的能力（第 1 个义项：弹性）；句意为橡胶在拉伸后恢复原长，显示出弹性。图中可辨识物件：橡皮筋、拉伸的手指、标尺、原长虚线、回弹箭头。","pos":[{"tag":"n.","zh":"弹性；回弹性；伸缩性；灵活性"}],"collocations":[{"phrase":"elasticity of demand","zh":"需求弹性"},{"phrase":"elasticity of supply","zh":"供给弹性"},{"phrase":"price elasticity","zh":"价格弹性"},{"phrase":"high elasticity","zh":"高弹性"},{"phrase":"rubber elasticity","zh":"橡胶弹性"},{"phrase":"lose its elasticity","zh":"失去弹性"}],"forms":[{"label":"名词（不可数）","form":"elasticity"},{"label":"复数（指多种弹性）","form":"elasticities"},{"label":"形容词","form":"elastic"},{"label":"副词","form":"elastically"},{"label":"相关名词","form":"elastic"},{"label":"相关形容词","form":"elasticized"}],"derivatives":[{"word":"elastic","pos":"adj./n.","zh":"由该名词去掉名词词尾得到，义为「有弹性的；松紧带」"},{"word":"elastically","pos":"adv.","zh":"由弹性形容词加副词尾构成，义为「有弹性地」"},{"word":"elasticized","pos":"adj.","zh":"由弹性形容词加已然词尾构成，义为「加了松紧的」"},{"word":"inelastic","pos":"adj.","zh":"由表示否定的前缀加弹性形容词构成，义为「无弹性的；缺乏弹性的」"},{"word":"viscoelastic","pos":"adj.","zh":"由表示「黏性」的成分加弹性形容词构成，义为「黏弹性的」"}],"senses":[{"no":"01","title":"Return to the original shape","titleCN":"恢复原状的弹性","definition":"the property of a material that lets it return to its original shape after a stretching or squeezing force is removed","definitionCN":"材料在拉力或压力去除后恢复原有形状的性质","example":"The elasticity of the rubber seal keeps the joint tight.","exampleCN":"橡胶密封件的弹性使接头保持紧密。","why":"The Greek source meant ductile or flexible, and physics narrowed it to the ability to spring back.","whyCN":"希腊语来源意为可延展、柔韧，物理学把它收窄为弹回的能力。"},{"no":"02","title":"The response of demand","titleCN":"需求的弹性","definition":"the degree to which the quantity demanded changes when price or income changes","definitionCN":"价格或收入变化时，需求量随之变化的程度","example":"Elasticity of demand was high for the cheaper parts.","exampleCN":"较便宜零件的需求弹性较高。","why":"Economists borrowed the material word because demand also stretches and shrinks in response to a pull.","whyCN":"经济学家借用了材料词，因为需求也会随拉力伸缩。"},{"no":"03","title":"The response of supply","titleCN":"供给的弹性","definition":"the degree to which the quantity supplied changes when price changes","definitionCN":"价格变化时供给量随之变化的程度","example":"Low elasticity of supply kept prices rising.","exampleCN":"供给弹性低使价格持续上升。","why":"Supply stretches less easily than demand in many markets, and the word carries that image.","whyCN":"许多市场里供给比需求更难伸缩，这个词带着那个画面。"},{"no":"04","title":"The bounce of rubber","titleCN":"橡胶的回弹性","definition":"the strong, quick recovery of a rubbery material after large deformation","definitionCN":"橡胶类材料在大形变后强烈而迅速地恢复","example":"Rubber elasticity comes from long molecules unfolding.","exampleCN":"橡胶弹性来自长分子链的展开。","why":"Rubber stretches many times its length, and its return is the most visible example of the property.","whyCN":"橡胶能拉到原长的许多倍，它的回缩是这种性质最直观的例子。"},{"no":"05","title":"Stretch in a physical sense","titleCN":"物理上的伸缩性","definition":"the ability of a body to extend and recover without breaking","definitionCN":"物体能够伸长并恢复而不断裂的能力","example":"The elasticity of the fabric lets it fit any frame.","exampleCN":"这种布料的伸缩性使其适合任何框架。","why":"Textiles and skin also stretch and return, and the word covers any such body.","whyCN":"织物与皮肤同样会伸长再回缩，这个词覆盖任何这类物体。"},{"no":"06","title":"Flexibility in rules","titleCN":"制度或规则的灵活性","definition":"the ability of a system, rule or schedule to change without breaking","definitionCN":"制度、规则或安排能够改变而不崩溃的能力","example":"The elasticity of the schedule absorbed the delay.","exampleCN":"进度安排的灵活性吸收了这次延误。","why":"A rule that can bend and recover is useful, and the physical metaphor made flexibility a virtue.","whyCN":"能弯又能回的规则有用，物理比喻使「灵活」成为一种优点。"},{"no":"07","title":"A measured economic ratio","titleCN":"经济学中量出的弹性系数","definition":"a numerical ratio expressing how much one economic variable responds to another","definitionCN":"表示一个经济变量对另一个变量反应程度的数值比","example":"The study reported an elasticity of one point two.","exampleCN":"研究报告给出的弹性系数为一点二。","why":"Once the metaphor became measurable, it turned into a ratio with a number attached.","whyCN":"当比喻变得可测量，它就成了带数字的比值。"},{"no":"08","title":"Adaptability in a person","titleCN":"人的适应变通能力","definition":"the ability of a person or arrangement to adapt to change and recover balance","definitionCN":"人或安排适应变化并恢复平衡的能力","example":"Her elasticity under pressure impressed the crew.","exampleCN":"她在压力下的变通能力让班组佩服。","why":"The same image of bending without breaking describes a temperament as well as a material.","whyCN":"同一个「弯而不断」的画面，既能描述材料，也能描述性情。"}],"etymology":{"intro":{"en":"Elasticity comes from the adjective elastic, built in New Latin from Greek elastos, ductile or flexible, and the noun ending. The word was shaped in seventeenth-century physics and later spread to economics.","cn":"这个词来自形容词 elastic，后者在新拉丁语中由希腊语 elastos「可延展、柔韧」加名词词尾构成。它在十七世纪物理学中成形，后来扩展到经济学。"},"items":[{"era":"GREEK ELASTOS","en":"Elastos meant ductile, beaten out or flexible, and it described metal that could be worked rather than broken.","cn":"这个词意为可延展的、被打薄的、柔韧的，描述可以加工而不折断的金属。"},{"era":"GREEK ELAUNEIN","en":"The related verb meant to drive, strike or beat out, and the connection to hammered metal is generally accepted.","cn":"相关动词意为驱动、击打、打薄，与锤打金属的联系一般认为成立。"},{"era":"NEW LATIN ELASTICUS","en":"Seventeenth-century science built the adjective elasticus from the Greek word, and English took it as elastic.","cn":"十七世纪科学由这个希腊词构成形容词 elasticus，英语以 elastic 借入。"},{"era":"SEVENTEENTH-CENTURY PHYSICS","en":"Boyle and his contemporaries used elasticity for air and springs that return after compression; the first attestation date and the identity of the first user are both uncertain.","cn":"波义耳及其同时代人用这个词指受压后回弹的空气与弹簧；最早用例的首见年代与首见者都不确定。"},{"era":"MATERIAL SCIENCE","en":"Later physics separated elastic from plastic behaviour and made elasticity a measurable property.","cn":"后来的物理学把弹性行为与塑性行为分开，使弹性成为可测量的性质。"},{"era":"ECONOMICS","en":"Nineteenth and twentieth-century economics applied the word to the response of prices, demand and supply.","cn":"十九与二十世纪的经济学把这个词用于价格、需求与供给的反应。"}]},"similar":{"note":{"en":"The first group looks or sounds like elasticity; the second group names neighbouring ideas of springing back and responsiveness.","cn":"第一组在形音上与「elasticity」相近；第二组是与「回弹、反应」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"elastic","ipa":"/ɪˈlæstɪk/","tag":"same root","definition":"Able to stretch and return, or a strip of such material.","definitionCN":"指能拉伸回缩的，也指这种材料的带子。"},{"word":"elastically","ipa":"/ɪˈlæstɪkli/","tag":"same root","definition":"In a way that springs back after deformation.","definitionCN":"指以形变后回弹的方式。"},{"word":"inelastic","ipa":"/ˌɪnɪˈlæstɪk/","tag":"derived opposite","definition":"Not returning to shape, or not responding much to price changes.","definitionCN":"指不回弹的，或对价格变化反应不大的。"},{"word":"elasticated","ipa":"/ɪˈlæstɪkeɪtɪd/","tag":"same root","definition":"Made with stretchy material, usually of clothing.","definitionCN":"指用弹性材料制成的，通常指衣物。"},{"word":"elliptical","ipa":"/ɪˈlɪptɪkl/","tag":"different root","definition":"Oval in shape, or indirect in speech; it looks close but comes from a different Greek word.","definitionCN":"指椭圆形的，或言语迂回的；形近但来自另一个希腊词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"resilience","ipa":"/rɪˈzɪliəns/","tag":"near meaning","definition":"The ability to recover quickly from compression, shock or hardship.","definitionCN":"指从压缩、冲击或困难中迅速恢复的能力。"},{"word":"flexibility","ipa":"/ˌfleksəˈbɪləti/","tag":"near meaning","definition":"The ability to bend without breaking, or to change plans easily.","definitionCN":"指弯曲而不断裂的能力，或轻易改变计划的能力。"},{"word":"springiness","ipa":"/ˈsprɪŋinəs/","tag":"near meaning","definition":"The quality of bouncing back after being pressed.","definitionCN":"指受压后弹回的性质。"},{"word":"responsiveness","ipa":"/rɪˈspɒnsɪvnəs/","tag":"near meaning","definition":"The degree to which something reacts to a change, used in economics and biology.","definitionCN":"指某物对变化的反应程度，用于经济学与生物学。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Greek ductile source, the real physics family and real economics phrases.","cn":"正常联想使用真实的希腊语「可延展」来源、真实物理同族词与真实经济学搭配。"},"normal":[{"en":"The Greek word described metal that could be beaten out, and the modern word describes a shape that comes back.","cn":"希腊词描述能被锤薄的金属，现代词描述能回来的形状。"},{"en":"Elastic and elasticity are the adjective and the noun of the same property.","cn":"elastic 与 elasticity 是同一性质的形容词与名词。"},{"en":"Elasticity of demand and elasticity of supply are the two economics phrases.","cn":"需求弹性与供给弹性是两个经济学说法。"},{"en":"Inelastic means it will not stretch, in physics and in markets.","cn":"inelastic 意味着拉不动，物理与市场都通用。"},{"en":"Rubber elasticity is the textbook example, because it can stretch several times its length.","cn":"橡胶弹性是教科书例子，因为它能拉到原长的好几倍。"}],"abstract":[{"en":"Elasticity is shape with a memory of where it came from.","cn":"弹性是有记忆的形状，记得自己原来在哪。"},{"en":"A market that stretches without breaking has elasticity too.","cn":"拉得开却不崩的市场也有弹性。"},{"en":"What bends and returns is trusted with more load next time.","cn":"弯了还能回来的东西，下次会被托付更多重量。"}]},"examples":[{"en":"The elasticity of the spring was tested at three temperatures.","cn":"这根弹簧的弹性在三种温度下测试过。"},{"en":"Price elasticity explains why the discount raised sales.","cn":"价格弹性解释了为什么打折提升了销量。"},{"en":"Old rubber loses its elasticity and starts to crack.","cn":"老化的橡胶失去弹性并开始开裂。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「伊拉斯提西提」——拉长了还能「提」回来，像皮筋一样：弹性","word":"elasticity"},"root":"新拉丁语 elasticus ← 希腊语 elastos「可延展、柔韧」，与 elaunein「驱动、击打、打薄」相关，该联系一般认为成立。十七世纪物理学用它指受压后回弹的性质，最早用例来源不确定；十九至二十世纪扩展到经济学的需求、供给与价格反应。","sensesIntro":{"en":"Eight senses all describe a return or a response: a material, demand, supply, rubber, fabric, a schedule, an economic ratio and a person.","cn":"八个义项都在描述「回」或「反应」：材料、需求、供给、橡胶、织物、进度安排、经济比值与一个人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rubber band stretched to twice its length snaps back to the mark.","cn":"核心意象：橡皮筋被拉到两倍长，松手后弹回标线。"},"chain":["AT REST","STRETCHED","STORED FORCE","RELEASED","SHAPE RECOVERED","NO PERMANENT CHANGE"],"branches":[{"senses":"01 · 05","en":"THE MATERIAL PROPERTY: rubber and fabric that extend and recover.","cn":"材料性质：能够伸长并恢复的橡胶与织物。"},{"senses":"04","en":"THE RUBBER BOUNCE: long molecules unfolding and pulling themselves back.","cn":"橡胶回弹：长分子展开后把自己拉回去。"},{"senses":"02 · 03 · 07","en":"THE MARKET RESPONSE: demand stretched by price, supply stretched by profit, both measured as a ratio.","cn":"市场反应：需求被价格拉动，供给被利润拉动，两者都量成比值。"},{"senses":"06","en":"THE BENDING RULE: a schedule that gives and recovers without breaking.","cn":"可弯的规则：能退让又能恢复、不会崩的安排。"},{"senses":"08","en":"THE ADAPTABLE PERSON: someone who bends under pressure and comes back to balance.","cn":"能变通的人：在压力下弯腰，再回到平衡。"}]},"affixes":{"intro":{"en":"Elasticity is a modern scientific noun built from a Greek adjective by way of New Latin, with a productive English family.","cn":"这是一个现代科学名词，由希腊语形容词经新拉丁语构成，在英语里有能产的词族。"},"latinIntro":{"en":"The Latin link is New Latin elasticus, a scientific coinage from Greek elastos; the deeper Greek root is reconstructed.","cn":"拉丁语环节是新拉丁语 elasticus，这是一个由希腊语 elastos 构成的科学新造词；更深的希腊词根属重构。"},"items":[{"word":"elastos","structure":"Greek adjective","meaning":"ductile, flexible","meaningCN":"可延展的；柔韧的","example":"The adjective described workable metal.","exampleCN":"这个形容词描述可加工的金属。"},{"word":"elaunein","structure":"Greek verb","meaning":"to drive, strike, beat out","meaningCN":"驱动；击打；打薄","example":"The verb links the property to hammering.","exampleCN":"这个动词把该性质与锤打联系起来。"},{"word":"elasticus","structure":"New Latin adjective","meaning":"elastic","meaningCN":"有弹性的","example":"Science coined the adjective in the seventeenth century.","exampleCN":"科学界在十七世纪造出这个形容词。"},{"word":"-ity","structure":"quality noun ending","meaning":"the state of being","meaningCN":"……的性质","example":"The ending turns the adjective into a property.","exampleCN":"这个词尾把形容词变成一种性质。"},{"word":"-ic","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It shapes the adjective elastic.","exampleCN":"它构成形容词 elastic。"},{"word":"-ally","structure":"adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It builds elastically.","exampleCN":"它构成 elastically。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"It builds inelastic.","exampleCN":"它构成 inelastic。"},{"word":"visco-","structure":"combining form from Latin viscum","meaning":"sticky","meaningCN":"黏的","example":"It builds viscoelastic, both sticky and springy.","exampleCN":"它构成 viscoelastic「黏弹性的」。"},{"word":"-ed","structure":"completed-state ending","meaning":"made with","meaningCN":"用……制成的","example":"It builds elasticized.","exampleCN":"它构成 elasticized。"}],"latinEntries":[{"word":"elasticus","structure":"New Latin adjective","meaning":"elastic","meaningCN":"有弹性的"},{"word":"viscum","structure":"Latin noun","meaning":"mistletoe, sticky substance","meaningCN":"槲寄生；黏性物"}],"derivatives":[{"word":"elastic","pos":"adj./n.","zh":"由该名词去掉名词词尾得到，义为「有弹性的；松紧带」"},{"word":"elastically","pos":"adv.","zh":"由弹性形容词加副词尾构成，义为「有弹性地」"},{"word":"inelastic","pos":"adj.","zh":"由表示否定的前缀加弹性形容词构成，义为「无弹性的」"},{"word":"viscoelastic","pos":"adj.","zh":"由表示「黏性」的成分加弹性形容词构成，义为「黏弹性的」"},{"word":"elasticized","pos":"adj.","zh":"由弹性形容词加已然词尾构成，义为「加了松紧的」"}]}}]);
